/* Loan Niche Encyclopedia deep extensions, part 3: Government + Conventional & agency (34 entries). Matrix, walkthrough, worked income example, scenarios, Q&A, AE questions, red flags, pricing, marketing, checklist. Figures marked (verify) or (lender-specific) must be confirmed against current handbook/guide/lender matrix. Illustrative numbers only; no rate quotes; no approval promises. Updated 2026-11. */
window.NICHE_DEEP=Object.assign(window.NICHE_DEEP||{},{
"a_va_purchase":{"matrix":[["Min FICO","VA sets no minimum score; AUS (DU/LPA) decides. Common overlays 580-620; many wholesale lenders 600+ for AUS approve, 620-640 for manual UW (lender-specific)"],["Max LTV/CLTV","100% of the lesser of price or appraised value, plus financed funding fee (can exceed 100% LTV); CLTV with approved DPA seconds per lender (lender-specific)"],["Loan limits","Full entitlement: no VA limit (Blue Water Navy Act 2020). Partial entitlement: county conforming limit drives guaranty; 2026 baseline $832,750, high-cost ceiling $1,249,125; San Diego County 2026 limit (verify)"],["DTI/AUS","41% benchmark ratio, not a cap; DU Approve/Eligible or LPA Accept often above 50% when residual income is strong; above 41% residual must exceed guideline by 20% unless compensating factors"],["Residual income","Required on every VA loan. West region (CA/NV/AZ), loans $80k+: family of 1 $491, 2 $823, 3 $990, 4 $1,117, 5 $1,158, +$80 each extra member; Midwest/South (IL/FL) 4-person $1,003 (verify table)"],["Funding fee","First use: 2.15% under 5% down, 1.50% at 5%+, 1.25% at 10%+; subsequent use under 5% down 3.30%. Exempt: VA disability compensation, Purple Heart on active duty, eligible surviving spouses; pre-discharge rating counts (verify current table)"],["Reserves","None required by VA for 1-unit; 6 months PITI required for 3-4 units; lenders may overlay for multiple properties (lender-specific)"],["Seasoning/waiting","Chapter 7 BK: 2 years from discharge; Chapter 13: 12 months of trustee-approved payments; foreclosure/deed-in-lieu: 2 years typical; prior VA loan claim must be repaid or entitlement reduced"],["Property types","1-4 units (veteran occupies one), VA-approved condos only (VA condo list), PUDs, new construction (builder must have VA ID and warranty or 10% down), manufactured on permanent foundation as real property"],["Occupancy","Must certify intent to occupy within a reasonable time (generally 60 days; up to 12 months with specific date and reason); spouse occupancy satisfies for deployed members; dependent child occupancy allowed in limited cases (verify)"],["Appraisal","VA fee appraiser assigned through WebLGY; MPRs (safe, sound, sanitary); Tidewater initiative gives 2 working days to submit data if value looks short; ROV allowed; NOV issued by SAR/VA"],["Assumability","Assumable with lender/VA approval; release of liability requires creditworthy assumer; entitlement stays tied up unless assumer is a veteran who substitutes entitlement; 0.5% assumption funding fee"],["Seller concessions","Concessions capped at 4% of reasonable value (excludes normal closing costs and discount points); buyer-broker fee may be paid by veteran under VA circular policy (verify current status)"],["States","Federal program; Steve can originate in CA, IL, NV, FL, AZ; state-level property tax exemptions for disabled veterans differ (CA $175k+ indexed basic exemption, FL full exemption at 100% P&T)"]],"walkthrough":["Pull COE in WebLGY at first contact; check entitlement code, funding fee exemption status and any entitlement tied up in prior loans","Collect DD-214 or Statement of Service, VA award letter if disabled, LES for active duty; confirm BAH and housing allowance by ZIP","Run credit and both AUS engines; compare DU vs LPA findings and note residual income test outcome","Compute residual income manually with the regional table, including maintenance at $0.14 per sq ft of living area","Issue pre-approval tied to verified entitlement and residual income, not just DTI","Coach agent on VA offer strength: appraisal timeline, MPR repairs, 4% concession cap, termite inspection norms in CA","Open escrow; order VA appraisal immediately through WebLGY with accurate POC for Tidewater","Review NOV; manage MPR repairs (peeling paint, roof life, safety items) with seller before final inspection","Clear conditions: verify funding fee exemption reflected on CD; confirm occupancy certification signed","Confirm escrow holds termite clearance if required by lender or appraiser","CD three business days before consummation; review concessions vs 4% limit","Close, fund, and record; set 210-day reminder for future IRRRL review and annual check-in for property tax exemption filing"],"incomeExample":{"title":"VA residual income test, family of 4, Chula Vista","steps":["Gross income: Navy E-7 base $5,600 + BAH (San Diego with dependents, illustrative) $4,100 + spouse W-2 $3,200 = $12,900/month","Taxes on taxable income only (base + spouse $8,800) estimated at 22% = $1,936; BAH is non-taxable, no withholding","Net effective income = $12,900 - $1,936 = $10,964","Proposed PITI on $750,000 purchase: P&I (illustrative) $4,650 + taxes $781 + insurance $160 + HOA $120 = $5,711","Maintenance/utilities: 1,600 sq ft x $0.14 = $224","Other debts: auto $520, student loan $180 = $700; childcare $600","Residual = $10,964 - $5,711 - $224 - $700 - $600 = $3,729","West region requirement for family of 4: $1,117; DTI = ($5,711 + $700) / $12,900 = 49.7%, so 120% test applies: $1,117 x 1.2 = $1,340"],"result":"Residual $3,729 far exceeds $1,340, so the 49.7% DTI is acceptable with AUS approval; document the residual worksheet in the file."},"scenarios":[{"t":"PCS buyer using BAH","who":"Marcus, 34, Navy E-6, Imperial Beach","situation":"Marcus received orders to NAVSTA San Diego and arrives in 45 days. He has $9,000 saved and his wife works remotely. They want a 3-bedroom near the base with a yard. He has never used his VA benefit.","structure":"VA purchase, 0% down, funding fee financed, seller credit toward closing costs","numbers":"Price $715,000, base loan $715,000, 2.15% fee $15,372 financed, total loan $730,372; seller credit up to 4% for concessions plus normal costs","why":"Zero down plus BAH counted as non-taxable income maximizes buying power while keeping savings for moving","alternatives":"FHA 3.5% down (MIP adds cost), conventional 97 (MI and higher credit pricing)","watch":"Occupancy timing with orders; confirm report-no-later-than date and offer close date align; termite clearance"},{"t":"Disabled veteran exempt from fee","who":"Danielle, 41, retired Army E-7, Temecula","situation":"Danielle has a 70% VA disability rating and works as a logistics coordinator. She rents in Murrieta and wants a single-story home. Her credit is 668 after a 2022 medical collection.","structure":"VA purchase with funding fee exemption, disability income grossed up","numbers":"Price $640,000, loan $640,000, no funding fee; VA comp $1,800 non-taxable grossed up 25% for DTI if lender allows","why":"Exemption saves about $13,760 and non-taxable income grossed up improves ratios","alternatives":"CalVet/VA for disaster coverage benefits, conventional with LPMI","watch":"Award letter must show rating effective; medical collections typically excluded but confirm AUS treatment"},{"t":"Repeat user, restored entitlement","who":"Javier, 52, retired Marine MSgt, Oceanside","situation":"Javier sold his first VA-financed home in 2019 and paid off the loan. He now wants a 4-bedroom closer to his daughter in Vista. He has 20% down from savings but prefers to keep liquidity.","structure":"VA purchase with 10% down to cut funding fee to 1.25%","numbers":"Price $820,000, 10% down $82,000, loan $738,000, fee $9,225 vs $24,354 at 3.30% zero-down","why":"Putting 10% down saves over $15,000 in subsequent-use fees and lowers payment","alternatives":"Zero down with 3.3% fee to preserve cash; conventional 80% to avoid fee entirely","watch":"Restore entitlement via VA Form 26-1880 if COE still shows used entitlement"},{"t":"Duplex house hack","who":"Kayla, 29, Navy Corpsman, National City","situation":"Kayla wants a duplex, live in one unit, rent the other. She has 2 years of military service and no landlord history. Rent schedule shows $2,400 for the second unit.","structure":"VA 2-unit purchase, rental income limited by lender policy without landlord experience","numbers":"Price $890,000 full entitlement no down; rental income may be used only with 6 months reserves or documented experience (lender-specific)","why":"VA allows 1-4 units with zero down, rare in SoCal","alternatives":"FHA 2-unit 3.5% down with self-sufficiency not required for 2 units; conventional 5% down 2-4 unit","watch":"Lender overlays on rental income, reserves; second unit permitted use and code compliance"},{"t":"Surviving spouse","who":"Linda, 58, school administrator, El Cajon","situation":"Linda's husband died from a service-connected condition and she receives DIC. She qualifies for a COE as a surviving spouse. She wants to downsize from a rental to a condo.","structure":"VA purchase on VA-approved condo, funding fee exempt via DIC","numbers":"Price $485,000, loan $485,000, no funding fee; HOA $410/month counted in PITI","why":"Surviving spouse benefit with no fee and no MI lowers monthly cost meaningfully","alternatives":"FHA condo (needs FHA approval), conventional 95%","watch":"Condo must be on VA approved list or submitted for approval; budget timeline"},{"t":"Credit rebuild path","who":"Tyrell, 27, Army veteran, Hemet","situation":"Tyrell separated in 2024 and works as an HVAC tech for 14 months. Middle score 594 due to a high utilization and one late. He has $4,000 saved.","structure":"VA purchase via lender accepting sub-620 with AUS approval, or 60-90 day rapid rescore plan","numbers":"Price $480,000 target; pay down two cards by $1,800 to drop utilization below 30% (illustrative)","why":"VA residual income and no MI make payment manageable once score clears overlays","alternatives":"FHA at 580; wait and rebuild","watch":"Job continuity after separation: military to civilian same-field counts; avoid new debt during process"}],"qa":[{"q":"Is there a VA loan limit in 2026?","a":"Not with full entitlement. County limits only matter when entitlement is partially used. Lenders still set their own maximum loan amounts."},{"q":"Can my spouse's income count?","a":"Yes, if married and on the loan. A non-veteran non-spouse co-borrower creates a joint loan where the guaranty covers only the veteran's portion, requiring a down payment on the rest."},{"q":"Do I need to be a first-time buyer?","a":"No. VA has no first-time buyer requirement and can be reused."},{"q":"Can the seller pay my funding fee?","a":"Yes, it counts toward the 4% concession cap along with things like paying off buyer debts."},{"q":"What if the appraisal comes in low?","a":"The Tidewater process gives notice before value is final; the veteran can renegotiate, pay the difference in cash or request an ROV with better comps."},{"q":"How long after closing must I move in?","a":"Generally within 60 days; longer with a documented reason and date. Deployed members can satisfy through spouse occupancy."},{"q":"Can I buy a fixer?","a":"Only if it meets MPRs at closing or repairs are completed or escrowed per lender policy; consider VA renovation programs from limited lenders."},{"q":"Can I pay my buyer agent's commission?","a":"VA's temporary policy allowed veterans to pay reasonable buyer-broker fees after the 2024 NAR settlement changes; confirm the current circular and lender treatment (verify)."},{"q":"Does a VA loan affect my disability rating?","a":"No. Using the home loan benefit is separate from compensation."},{"q":"Can I use VA for a second home or rental?","a":"No; it must be a primary residence, although you may keep a VA-financed home as a rental after moving and use remaining entitlement."}],"aeQuestions":["What is your minimum FICO for VA purchase with DU Approve/Eligible vs manual?","Do you allow DTI above 55% with strong residual income?","Will you count rental income on a 2-4 unit VA without landlord history?","Do you require termite inspections on every California VA file?","What is your max loan amount with full entitlement?","Do you allow non-taxable income gross-up, and at what percent?","How do you handle buyer-paid buyer-broker fees on the CD?","Do you require reserves on 2-unit VA?","Can you close a VA loan with a POA for a deployed member?","What is your turn time for VA appraisal reviews and Tidewater responses?"],"redFlags":["COE shows entitlement used on a home the veteran thought was paid off","Occupancy unclear: orders send the member out of area soon after closing","Seller concessions exceed 4% once debt payoff is included","Non-veteran co-borrower who is not a spouse (joint loan needs down payment)","Condo not on VA list with short contract timeline","Residual income barely meets table with DTI above 41%","Builder lacks VA builder ID or warranty on new construction","Large unexplained deposits in the last 60 days"],"pricing":"VA pricing is usually among the best of any 0%-down product because the guaranty reduces lender risk; credit-score and loan-amount adjusters still apply and vary by investor. The funding fee is the main cost driver and is waived for compensated disabled veterans, which can be worth 2-3% of the loan. Compare whether a slightly higher rate with lender credit to cover closing costs beats paying points, given VA's 4% concession cap. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Free first-time veteran homebuyer workshops at base family readiness centers (follow base solicitation rules)","Partner with VA-savvy buyer agents in Oceanside, Temecula and Chula Vista","PCS season checklists published on LinkedIn and Facebook groups for incoming families (no rate quotes)","Veteran Service Officer and county VSO referral education (no referral fees per RESPA Section 8)","Disabled veteran property tax exemption explainer content","Educational posts on funding fee exemptions with Steve's NMLS and Patriot Pacific NMLS"],"checklist":["COE (WebLGY)","DD-214 member 4 or Statement of Service","VA award letter for exemption","LES (most recent) or 30 days paystubs","2 years W-2s / tax returns as needed","Residual income worksheet","VA appraisal NOV","Termite report if required","Purchase contract and addenda","Occupancy certification","VA Form 26-1802a (HUD/VA addendum)","Bank statements 2 months","Funding fee receipt or exemption evidence","Condo/PUD VA approval printout","Hazard insurance with replacement coverage"],"updated":"2026-11"},
"a_va_irrrl":{"matrix":[["Min FICO","No VA minimum; no credit qualifying in most cases. Lenders often overlay 580-640 tri-merge or soft pull (lender-specific)"],["Max LTV","No appraisal required by VA; loan = payoff + allowable costs + funding fee + up to 2 discount points; some lenders require appraisal or AVM (lender-specific)"],["Loan limits","No VA limit; lender maximums apply"],["DTI/AUS","Not required unless payment increases 20%+ or delinquency; then full underwriting incl. DTI and residual"],["Residual income","Only required when payment increases by 20% or more or loan is not current"],["Funding fee","0.50%, exempt for disability compensation recipients and eligible surviving spouses"],["Seasoning","Later of 210 days from first payment due date of loan being refinanced and 6 consecutive monthly payments made (38 U.S.C. 3709)"],["Net tangible benefit","Fixed to fixed: rate drop of at least 0.50%; fixed to ARM: at least 2.00% drop; ARM to fixed: allowed with payment change; term shortening can be NTB"],["Recoupment","Fees and closing costs (excluding taxes, escrow, insurance, assessments) recouped through monthly savings within 36 months"],["Payment history","No more than one 30-day late in 12 months typical; lenders may require 0x30 (lender-specific)"],["Occupancy","Veteran must certify prior occupancy; current occupancy not required"],["Property types","Any property with an existing VA loan; condo VA approval not required for IRRRL"],["Cash out","None except up to $6,000 for energy efficient improvements; small incidental refunds allowed"],["States","Federal; available in all of Steve's licensed states"]],"walkthrough":["Get current mortgage statement and note date; confirm the loan is VA (case number) and the veteran certifies prior occupancy","Compute seasoning: first payment date + 210 days and count payments made","Run the rate-reduction NTB test at today's pricing (fixed-fixed 0.50%+)","Build recoupment math: total fees / monthly P&I savings must be 36 months or fewer","Decide appraisal need: VA does not require; lender may for loans over a threshold","Order credit or mortgage-only verification per lender; obtain payoff","Issue VA Loan Comparison disclosure within 3 business days of application (required by VA Circular 26-19-22 era guidance; verify)","Lock and confirm points do not exceed allowed financing (up to 2 points)","Verify funding fee exemption status in WebLGY","Send second comparison at closing; confirm NTB and recoupment still pass","Close; no rescission period required on IRRRL in most cases (non-cash-out refi of same lender may differ), confirm with title","Calendar a 12-month check to watch for further rate improvement"],"incomeExample":{"title":"IRRRL net tangible benefit and 36-month recoupment","steps":["Current loan: $520,000 balance, 30-year fixed, P&I $3,460 (illustrative)","Proposed: new loan $520,000 + 0.50% fee $2,600 = $522,600; P&I illustrative $3,170","Rate decrease is 0.75 point, satisfying the 0.50 point fixed-to-fixed NTB","Monthly P&I savings = $3,460 - $3,170 = $290","Recoupable costs: lender/title/escrow fees $4,200 + funding fee $2,600 = $6,800 (prepaids and escrow excluded)","Recoupment = $6,800 / $290 = 23.4 months","Limit is 36 months; passes"],"result":"Passes both NTB and recoupment; payment drops $290/month. If fee was exempt, recoupment falls to 14.5 months."},"scenarios":[{"t":"2023 buyer stepping down in rate","who":"Andre, 38, Navy Chief (E-7), Santee","situation":"Andre bought in mid-2023 with a VA loan at a rate well above today's market. He has made 30 on-time payments and has no plans to move before his 2030 retirement. He wants a lower payment, not cash, and does not want to pay for an appraisal.","structure":"VA IRRRL, no appraisal, lender credit applied against title and escrow fees","numbers":"Balance $585,000; illustrative P&I falls about $300/month; recoupable costs about $7,200 incl. 0.5% fee; recoupment about 24 months","why":"Meets the 0.50 point fixed-to-fixed test and the 36-month recoupment with minimal paperwork","alternatives":"Conventional rate/term (needs appraisal; MI if under 20% equity); waiting for a deeper drop","watch":"Do not add points that push recoupment past 36 months; confirm 210 days and 6 payments are both satisfied"},{"t":"Hybrid ARM before first adjustment","who":"Sharon, 47, Air Force veteran and hospital supply manager, Henderson NV","situation":"Sharon took a VA 5/1 hybrid ARM in 2021 and the first adjustment is eight months away. Her budget is tight because she supports a parent. She wants a fixed payment she can plan around.","structure":"IRRRL from ARM to 30-year fixed","numbers":"Current P&I $2,410; proposed fixed P&I $2,560 (illustrative), a 6% increase, under the 20% re-qualification trigger","why":"ARM-to-fixed is itself a recognized benefit; no full income re-verification needed under the 20% threshold","alternatives":"Conventional refinance with full documentation; keep the ARM and budget for caps","watch":"Lender may still pull credit; one 30-day late in last 12 months can be a lender overlay problem"},{"t":"Former home now a rental","who":"Ron, 55, retired Army SFC, moved from Fallbrook CA to Phoenix AZ","situation":"Ron took a job in Phoenix and kept his Fallbrook home as a rental with a VA loan. The rent covers PITI but barely. A lower rate would add cash flow and cushion for repairs.","structure":"IRRRL on the non-owner-occupied former residence with prior-occupancy certification","numbers":"P&I drop about $240/month (illustrative); funding fee 0.5% financed","why":"IRRRL only requires that he once lived there; no need to qualify on DSCR","alternatives":"DSCR or conventional investment refi (higher pricing and appraisal)","watch":"Many lenders overlay non-owner IRRRLs or price them higher; confirm before application"},{"t":"Exempt veteran repeating an IRRRL","who":"Gina, 44, Marine veteran with 80% rating, Murrieta","situation":"Gina refinanced into her current VA loan 18 months ago. Market rates have fallen another 0.75 point. She is fee exempt and wants to know whether doing it again makes sense.","structure":"IRRRL with lender credit covering most third-party fees","numbers":"Recoupable costs about $3,000 vs $260/month savings = 11.5 months (illustrative)","why":"Exemption plus small costs make the math work quickly","alternatives":"Hold current loan if savings are marginal","watch":"VA anti-churning rules: document NTB and recoupment; reject solicitations promising 'skip two payments' as savings"},{"t":"Shortening term toward retirement","who":"Paul, 61, retired Navy Senior Chief, Coronado","situation":"Paul has $410,000 left on a 30-year VA loan and wants to be mortgage-free by 75. His pension, VA compensation and part-time teaching income are stable. He is comfortable with a higher payment.","structure":"IRRRL from 30-year to 15-year fixed","numbers":"P&I rises from $2,780 to roughly $3,450 (illustrative), a 24% increase, so full underwriting with DTI and residual applies","why":"Large lifetime interest savings and payoff at about 76","alternatives":"Keep 30-year and prepay principal voluntarily","watch":"Payment increase over 20% means income docs, credit and residual income are required"}],"qa":[{"q":"Do I need an appraisal?","a":"VA does not require one, but some lenders do."},{"q":"Can I take cash?","a":"No, except energy-efficiency improvements up to $6,000."},{"q":"Do I have to live in the home?","a":"No, but you must certify you previously lived there."},{"q":"How often can I IRRRL?","a":"Whenever seasoning, NTB and recoupment are met, but serial refinancing that doesn't benefit you is scrutinized."},{"q":"Will my credit be checked?","a":"Lender-specific; many pull credit and require recent on-time payments."},{"q":"Can I roll in closing costs?","a":"Yes, allowable costs plus up to two discount points can be financed."},{"q":"What if I'm behind on payments?","a":"A loan not current requires full underwriting and VA prior approval."},{"q":"Does an IRRRL use more entitlement?","a":"No; entitlement transfers from the old loan."},{"q":"Can I switch lenders?","a":"Yes; IRRRL can be done with any VA lender."}],"aeQuestions":["Do you require an appraisal or AVM on IRRRL?","Minimum FICO or no-score allowed?","Do you allow non-owner IRRRL?","How do you compute recoupment (which fees counted)?","Max points financed?","Do you allow removing a borrower?","Manual underwriting if payment rises 20%+?","Turn time from app to close?","Do you require 0x30 in 12 months?"],"redFlags":["Fewer than 6 payments or under 210 days","Rate drop under 0.50 point fixed to fixed","Recoupment over 36 months","Payment increase 20%+ without full qualifying","Loan is not actually VA (FHA or conventional)","Solicitation promising skip-a-payment as savings (misleading)","Cash-out disguised as IRRRL"],"pricing":"IRRRL pricing is often competitive because the loan is a seasoned VA asset, but lenders add adjusters for loan size, points and non-owner occupancy. The 0.5% funding fee (waived when exempt) and title fees are the main costs. Recoupment math includes points, so paying points can disqualify the refinance. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Annual VA mortgage review letters to past clients (no rate quote; offer review)","Content: how VA seasoning and recoupment rules protect veterans from churning","Partner with veteran financial counselors","Facebook groups for veteran homeowners: educational posts","Email reminders to clients at 210-day mark","Military spouse networks"],"checklist":["Current mortgage statement","VA case number","Note/first payment date","Payment history 12 months","NTB worksheet","Recoupment worksheet","VA Loan Comparison disclosures (initial and closing)","Funding fee exemption verification","Homeowners insurance","Payoff letter","Occupancy certification (prior)","Credit report if required"],"updated":"2026-11"},
"a_va_cashout":{"matrix":[["Min FICO","No VA minimum; overlays commonly 620 at 90% LTV and 640-680 at 100% (lender-specific)"],["Max LTV","VA allows up to 100% LTV including funding fee; many lenders cap at 90% (lender-specific)"],["Loan limits","Full entitlement: no VA limit; lender caps apply; partial entitlement uses county limit formula"],["DTI/AUS","AUS required; 41% benchmark; full residual income test"],["Residual income","Same regional table as purchase; maintenance at $0.14/sq ft"],["Funding fee","Type II: 2.15% first use, 3.30% subsequent; exempt categories apply"],["Seasoning","Existing VA loan: 210 days from first payment and 6 payments for Type I/II on VA-to-VA (verify); title seasoning per lender"],["NTB","Type I (no cash beyond payoff) must meet one of VA's 8 NTB tests and 36-month recoupment; Type II must meet NTB test and disclosure"],["Reserves","None by VA; lender overlay possible"],["Occupancy","Must occupy as primary residence now"],["Appraisal","Full VA appraisal required; MPRs"],["Rescission","3-day right of rescission applies to primary residence; VA comparison disclosures required"],["Property types","1-4 units, VA approved condos"],["States","Federal; available CA, IL, NV, FL, AZ"]],"walkthrough":["Determine Type I (refinance non-VA into VA, no cash beyond payoff) vs Type II (cash out)","Collect mortgage statements, payoffs and any second-lien payoffs","Order the VA appraisal through WebLGY immediately","Underwrite fully with AUS and VA residual income","Run the VA net tangible benefit test and deliver the loan comparison disclosure within 3 business days","Calculate the funding fee and confirm exemption status","Check the lender's LTV cap against appraised value","Lock","Deliver the closing comparison disclosure; sign with 3-day rescission","Fund and disburse cash or pay off debts at closing","Record and set a review reminder for future IRRRL eligibility"],"incomeExample":{"title":"Type II cash-out to pay off high-interest debt, Escondido","steps":["Appraised value $780,000; lender cap 90% LTV = $702,000 max total loan","Funding fee 2.15% (first use) on base loan; base loan max = $702,000 / 1.0215 = $687,225","Payoff existing mortgage $520,000; closing costs $9,000","Cash available = $687,225 - $520,000 - $9,000 = $158,225","Pays off credit cards $38,000 (payments $1,140/month) and auto $22,000 ($610/month)","Monthly debt removed: $1,750; new PITI increases by illustrative $1,050","Net monthly cash flow improvement: $700"],"result":"Cash out at 90% LTV produces about $158k and reduces monthly outflow by $700; document NTB."},"scenarios":[{"t":"FHA buyer converting to VA (Type I)","who":"Cesar, 39, Navy veteran and port mechanic, Chula Vista","situation":"Cesar bought with FHA in 2021 before he knew about his VA benefit. He pays about $310/month in annual MIP for the life of the loan. He has a 30% disability rating and wants to stop paying mortgage insurance.","structure":"VA Type I refinance (no cash beyond payoff and costs), funding fee exempt","numbers":"Balance $540,000; MIP eliminated; illustrative P&I similar; recoupable costs $6,500 / $310 savings = 21 months","why":"Removes life-of-loan MIP and funding fee is waived","alternatives":"FHA streamline (keeps MIP); conventional refi if 20% equity","watch":"Type I must still pass VA NTB and 36-month recoupment; full VA appraisal required"},{"t":"Debt consolidation after medical bills","who":"Shauna, 45, Air Force retiree and pharmacy tech, Tucson AZ","situation":"A medical event left Shauna with $46,000 of card debt. Her home is worth about $430,000 with a $210,000 balance at a rate slightly above market. Her minimum payments total $1,380/month and her score has slipped to 641.","structure":"Type II cash-out at 85% LTV","numbers":"New loan $365,500; pays off $46,000 cards; cash to borrower about $95,000 after costs (illustrative)","why":"Replaces high-interest revolving payments with mortgage debt and resets utilization","alternatives":"HELOC second if the first-lien rate were low; credit counseling plan","watch":"Discuss reuse risk of paid-off cards; 3-day rescission; subsequent-use fee 3.30% since she used VA before"},{"t":"Solar and ADU deposit","who":"Rick, 50, Marine veteran and electrician, Temecula","situation":"Rick wants to add solar and start a detached ADU for his mother-in-law. He has about $500,000 of equity. His contractor needs a deposit and design fees before permits.","structure":"Type II cash-out to 80% LTV","numbers":"Value $900,000; new loan $720,000; existing $400,000; cash about $310,000 after costs","why":"Single fixed loan funds the projects with no draw administration","alternatives":"Renovation loan (draws), HELOC (variable), CalVet Home Improvement (verify availability)","watch":"ADU construction risk; property tax reassessment on new construction; keep receipts"},{"t":"Divorce buyout","who":"Jasmine, 37, Navy veteran and nurse, Oceanside","situation":"Jasmine's divorce decree awards her the house and requires a $140,000 equalization payment to her ex-spouse within 120 days. Both are on the current VA loan. She earns enough to qualify alone.","structure":"Type II cash-out paying the ex-spouse through escrow","numbers":"Value $820,000; payoff $450,000; new loan $615,000 (75% LTV) covers buyout and costs","why":"Removes the ex from the loan and pays the obligation in one transaction","alternatives":"Conventional equity buyout (Fannie treats some as limited cash-out; verify); assumption with release","watch":"Decree and quitclaim must be final; child support/alimony counted in DTI"},{"t":"Paying off a private second","who":"Mike, 59, Army veteran and contractor, Reno NV","situation":"After a slow 2024, Mike took a private second with a balloon due next spring. His first is a VA loan. He now has two years of recovered income.","structure":"Type II cash-out consolidating first and private second","numbers":"Value $610,000; combined payoffs $470,000; new loan about $490,000 (80% LTV)","why":"Removes balloon risk and lowers total monthly payment","alternatives":"Non-QM bank statement loan if income docs are thin","watch":"Self-employed income averaging; recent credit events"}],"qa":[{"q":"Can I borrow 100% of my home's value?","a":"VA allows it including the funding fee, but most lenders cap cash-out at 90%."},{"q":"How long after buying can I cash out?","a":"Typically 210 days and 6 payments when refinancing an existing VA loan; lenders may add title seasoning."},{"q":"Is there a rescission period?","a":"Yes, a 3-business-day right of rescission on a primary residence."},{"q":"Can I refinance an FHA or conventional loan into VA?","a":"Yes, through a Type I or Type II VA cash-out refinance."},{"q":"Do I need to live in the home?","a":"Yes, it must be your current primary residence."},{"q":"Is there a funding fee?","a":"Yes, 2.15% first use or 3.30% subsequent use unless you are exempt."},{"q":"Can I use the cash to pay off a car or cards?","a":"Yes, and lenders often require debts paid at closing to qualify."},{"q":"Do I need an appraisal?","a":"Yes, a full VA appraisal is required."}],"aeQuestions":["What is your max LTV for VA Type II cash-out?","FICO tiers by LTV for cash-out?","Do you allow Type I at 100% LTV?","Title seasoning requirement?","Manual underwriting allowed on cash-out?","Max loan amount with full entitlement?","Typical VA appraisal turn time in San Diego and Riverside?","Will you pay judgments and collections at closing?"],"redFlags":["New rate higher than current with no net tangible benefit","Type I recoupment exceeds 36 months","Seasoning of 210 days and 6 payments not met","Veteran no longer occupies the home","Cash used for speculation without understanding risk","Appraisal value short of lender's LTV cap","Repeated solicitations encouraging serial refinancing"],"pricing":"VA cash-out pricing carries LTV-based and cash-out adjusters that vary by lender. The funding fee is a major cost unless exempt. Compare HELOC vs full cash-out when the existing rate is low. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Educational content on VA cash-out vs HELOC","FHA-to-VA conversion campaigns for veterans paying MIP","Veteran financial wellness workshops","Past client equity reviews","Partner with CPAs serving veterans"],"checklist":["COE","Payoff statements","VA appraisal","Loan comparison disclosures","Residual income worksheet","Income docs","Asset docs","Rescission notice","Funding fee exemption","Insurance","Title report"],"updated":"2026-11"},
"a_va_jumbo":{"matrix":[["Min FICO","No VA minimum; common jumbo overlays: 620-660 to $1.5M, 680-700+ above $1.5M-$2M (lender-specific)"],["Max LTV","Up to 100% with full entitlement, plus financed funding fee; partial entitlement requires 25% of amount above available guaranty"],["Loan limits","No VA cap with full entitlement (since Jan 2020); lender maximums usually $2M-$4M (lender-specific); 2026 high-cost conforming ceiling $1,249,125 is used only for partial-entitlement math"],["DTI/AUS","DU/LPA approval required by most investors; many cap DTI at 50% above a size threshold (lender-specific)"],["Residual income","VA regional table applies; some jumbo investors require residual of 120% or more (lender-specific)"],["Funding fee","Same schedule (2.15%/3.30% under 5% down); on a $1.5M loan that is $32,250 first use; exempt categories pay none"],["Reserves","VA none on 1-unit; overlays commonly 6-12 months PITI over $1.5M (lender-specific)"],["Seasoning","BK/foreclosure same as VA purchase; some jumbo investors add 3-4 years (lender-specific)"],["Property types","1-4 units, VA-approved condos; acreage and unique homes may hit appraisal comparability issues"],["Occupancy","Primary only"],["Appraisal","VA fee appraiser; desk review or second appraisal above certain sizes (lender-specific)"],["Assumability","Assumable; buyer must qualify; useful selling feature in a high-rate market"],["Pricing","Loan-size adjusters typically start above conforming high-balance levels (lender-specific)"],["States","Mostly CA coastal counties; also Las Vegas luxury, Scottsdale AZ, South Florida"]],"walkthrough":["Confirm full entitlement and no prior claim on COE","Ask 2-3 wholesale lenders for current VA jumbo max loan, FICO tiers and reserve overlays","Run DU and LPA; note any 'refer' due to size","Verify reserves in liquid or retirement accounts (retirement at lender haircut)","Compute residual income including HOA and Mello-Roos where applicable","Write pre-approval with clear max price based on payment comfort, not just approval","Order VA appraisal on day one of escrow; prepare comparable sales package for Tidewater","Plan for second appraisal or desk review if required","Lock; explain size adjusters in writing","Clear conditions; verify funding fee or exemption","CD review including Mello-Roos and supplemental tax estimate","Close and record"],"incomeExample":{"title":"VA jumbo affordability, full entitlement, Carlsbad","steps":["Purchase $1,500,000, 0% down; first-use funding fee 2.15% = $32,250; total loan $1,532,250","Illustrative P&I $9,550; property tax at 1.1% = $1,375; Mello-Roos $250; insurance $260; total PITI $11,435","Other debts: auto $650","At 50% DTI cap (lender-specific): required gross = ($11,435 + $650) / 0.50 = $24,170/month","Residual check (family of 3, West): requirement $990; net income after taxes at that gross estimated $17,400; minus PITI, debts, maintenance (2,600 sq ft x $0.14 = $364) = $4,951","If fee-exempt, total loan is $1,500,000 and P&I drops about $200/month"],"result":"Needs roughly $24,200 gross monthly income at a 50% DTI cap; residual passes easily, so DTI and reserves are the binding constraints."},"scenarios":[{"t":"O-4 buying near NAB Coronado","who":"Elena, 38, Navy Lieutenant Commander, Coronado","situation":"Elena and her husband, a software engineer, earn about $29,000/month combined including BAH. They have $90,000 saved and want to keep most of it as reserves. Coronado single-family prices are well above the conforming ceiling.","structure":"VA jumbo, 0% down, first-use fee financed","numbers":"Price $1,750,000; loan with fee $1,787,625; reserves 9 months verified","why":"Avoids 10-20% down required by conventional jumbo and keeps liquidity","alternatives":"Conventional jumbo with 10% down; VA with 5% down to drop fee to 1.5%","watch":"Lender max loan and FICO tier at this size; short PCS horizon"},{"t":"100% P&T veteran","who":"Brian, 50, retired Marine Major, Del Mar","situation":"Brian is rated 100% permanent and total and works as a defense consultant. He is funding-fee exempt and would also qualify for California's disabled veteran property tax exemption. He prefers zero down so he can invest proceeds from selling his Texas home.","structure":"VA jumbo 0% down, fee exempt","numbers":"Price $2,100,000; no funding fee (saves $45,150 vs first use)","why":"Exemption plus no MI makes VA jumbo cheaper than conventional jumbo","alternatives":"Conventional jumbo 20% down","watch":"File county exemption claim after closing; lender max may be $2M-$3M"},{"t":"Dual-military couple","who":"Sam, 33, and Kim, 32, Navy Lieutenants, Point Loma","situation":"Both are on sea-shore rotation and expect to remain in San Diego four more years. They have used no VA entitlement. They want a home they can later rent.","structure":"VA jumbo using one spouse's full entitlement","numbers":"Price $1,400,000; loan $1,430,100 with fee","why":"Zero down and later rentable; second spouse's entitlement remains for the next PCS","alternatives":"Conventional high-balance with 10% down","watch":"Only one entitlement is needed; keep the other for future use"},{"t":"Retired Master Chief with multiple incomes","who":"Frank, 60, retired Navy MCPO, San Marcos","situation":"Frank has a Navy pension, 40% VA compensation and a civilian program manager salary. He is selling his Escondido home and will net $400,000. He wants to keep payment under $9,000.","structure":"VA jumbo with 10% down; funding fee waived because he receives VA compensation","numbers":"Price $1,600,000; 10% down $160,000; loan $1,440,000; no funding fee","why":"Down payment keeps payment under target while compensation status removes the fee entirely","alternatives":"Conventional jumbo 20% down","watch":"Bridge timing if Escondido sale closes after purchase"},{"t":"Airline pilot and Air Force veteran","who":"Rachel, 45, captain at a major airline, San Clemente","situation":"Rachel's income includes base, per diem and variable flight pay. She has 25 years of credit with a 790 score. She wants a home near the coast for her family of four.","structure":"VA jumbo, 0% down, AUS approve","numbers":"Price $1,850,000; qualifying income 2-year average flight pay (per diem excluded unless documented)","why":"Strong credit unlocks best tier pricing; VA residual easily met","alternatives":"Conventional jumbo 10% down","watch":"Variable pay documentation and two-year averaging"}],"qa":[{"q":"Is there a VA limit on a $2M loan?","a":"No VA limit with full entitlement; the lender sets a maximum."},{"q":"Why do lenders require more reserves on VA jumbo?","a":"Investors buying large VA loans want cushion; it's an overlay, not a VA rule."},{"q":"Does putting 5% down help?","a":"It cuts the funding fee to 1.5% for first use and slightly lowers payment."},{"q":"Can I use VA jumbo with a loan still open?","a":"Yes, but partial entitlement means a down payment on the excess above remaining guaranty."},{"q":"Is VA jumbo assumable?","a":"Yes, subject to buyer qualification."},{"q":"Will the appraisal be harder?","a":"Luxury comps can be sparse; prepare a strong comp package."},{"q":"Can I buy a home with an ADU?","a":"Yes if it's one property; ADU income treatment varies by lender."},{"q":"What credit score do I need?","a":"Varies; higher tiers get better pricing."},{"q":"Can I get a VA jumbo ARM?","a":"Some lenders offer VA hybrid ARMs."}],"aeQuestions":["What is your VA max loan amount with full entitlement?","FICO tiers by loan size?","Reserve requirement by loan size?","DTI cap above $1.5M?","Second appraisal threshold?","How are loan-size adjusters priced?","Will you allow gift funds for reserves?","Do you offer VA jumbo ARMs?","Condo and acreage limits?","Turn time on jumbo VA conditions?"],"redFlags":["COE shows partial entitlement not disclosed","Reserves dependent on unvested or restricted stock","DTI above lender cap","Appraisal comps far apart","Mello-Roos and HOA not included in payment","Occupancy questionable: second home disguised as primary","Large recent deposits"],"pricing":"VA jumbo carries loan-size adjusters and sometimes FICO tiers that differ across wholesale lenders, so spreads can be large. Funding fee on a large loan is material; 5% or 10% down lowers it. Exempt veterans should compare total cost against conventional jumbo, where MI isn't needed at 20% down. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Officer financial readiness talks (follow base rules)","Luxury buyer agents in Coronado, Point Loma, Carlsbad","Content on 'no VA loan limit' explained with examples","Pilot and veteran professional networks","Financial planners serving O-4+ and retirees","Disabled veteran property tax exemption content"],"checklist":["COE with full entitlement","Income docs (LES, W-2s, returns)","Reserves statements","VA appraisal","Second appraisal if required","Residual worksheet","Mello-Roos disclosure","Insurance with replacement cost","Purchase contract","Funding fee exemption proof","Lender max loan matrix","Gift letter if applicable"],"updated":"2026-11"},
"a_va_secondtier":{"matrix":[["Min FICO","No VA minimum; overlays 580-640 (lender-specific)"],["Max LTV","100% up to remaining entitlement x 4; above that, 25% down on excess"],["Loan limits","County conforming limit used to compute guaranty when entitlement is in use; 2026 baseline $832,750, ceiling $1,249,125"],["DTI/AUS","AUS; both mortgages count in DTI unless rental income offsets"],["Residual income","Standard; includes both housing payments"],["Funding fee","Subsequent use 3.30% under 5% down, 1.50% at 5%+, 1.25% at 10%+"],["Reserves","Lenders may require reserves for retained property (lender-specific)"],["Seasoning","None specific"],["Property types","1-4 units"],["Occupancy","New home must be primary"],["Appraisal","VA appraisal"],["Retained property rental income","Lease + 75% of rent typically; lender may require property management experience (lender-specific)"],["States","All"]],"walkthrough":["Pull COE; identify entitlement in use","Get county limit for new property","Compute remaining entitlement","Compute max no-down loan","Determine down payment if over","Document rental income of retained property","AUS","Appraisal","Close"],"incomeExample":{"title":"Second-tier entitlement calculation","steps":["Prior VA loan $400,000 still active (rented in Oceanside); entitlement in use = 25% x $400,000 = $100,000","New property county limit (illustrative San Diego) $1,100,000 (verify 2026)","Remaining entitlement = 25% x $1,100,000 - $100,000 = $175,000","Max no-down loan = $175,000 x 4 = $700,000","Purchase $850,000: excess $150,000; 25% down = $37,500"],"result":"Veteran can buy $850k with $37,500 down while keeping the first home."},"scenarios":[{"t":"PCS out, keep the San Diego home","who":"Robert, 42, Navy Chief (E-7), Oceanside","situation":"Robert bought in Oceanside in 2020 with a $400,000 VA loan and a low rate. He just returned to San Diego after a tour in Virginia, where he rented, and now wants a larger home in Vista. He wants to keep Oceanside as a rental.","structure":"Second-tier VA purchase in Vista; Oceanside leased at $3,100/month","numbers":"Remaining entitlement $175,000 (illustrative); max no-down loan $700,000; $780,000 price needs $20,000 down","why":"Keeps a low-rate rental while buying a new primary","alternatives":"Sell Oceanside to restore full entitlement; conventional 5% down","watch":"Lease, deposit and 75% rent offset; reserves overlay"},{"t":"Growing family, condo kept","who":"Anna, 35, Marine veteran and teacher, Vista","situation":"Anna owns a VA-financed condo with a $310,000 balance. She had twins and needs a 4-bedroom. Her condo rents for $2,500.","structure":"Second-tier on $760,000 home","numbers":"Entitlement in use $77,500; county limit (illustrative) $1,100,000; remaining $197,500; max no-down $790,000","why":"No down payment needed","alternatives":"Sell condo","watch":"HOA rental restrictions in condo"},{"t":"Retiree relocating to Temecula","who":"Dan, 58, retired Navy Senior Chief, Temecula","situation":"Dan owns a VA home in Chula Vista and is moving to wine country. Riverside County limit is lower (verify 2026) which reduces remaining entitlement. He has proceeds from investments for a down payment.","structure":"Second-tier with 10% down to cut funding fee to 1.25%","numbers":"Chula Vista loan $360,000 (entitlement in use $90,000); Riverside limit assumed $832,750 (verify); remaining $118,188; max no-down $472,750; $850,000 price needs $94,313 on the gap, so he puts 10% ($85,000) plus small extra","why":"Keeps Chula Vista as income property while the larger down payment lowers the fee","alternatives":"Conventional purchase with 20% down; sell Chula Vista first","watch":"Lower county limit increases required down payment; confirm Riverside 2026 limit"},{"t":"Prior foreclosure loss","who":"Leo, 40, Army veteran and warehouse supervisor, Hemet","situation":"Leo lost a VA home to foreclosure in 2018; VA paid a claim. He has rebuilt credit to 660. He wants to buy again.","structure":"Second-tier using remaining entitlement after loss","numbers":"Entitlement charged $45,000 (illustrative); remaining used for new purchase","why":"Can still buy with little down","alternatives":"FHA after waiting period","watch":"Claim debt to VA; entitlement restored only after repayment"},{"t":"Short sale with VA loss in Las Vegas","who":"Maria, 45, Navy veteran and casino accountant, Las Vegas NV","situation":"Maria short-sold a VA-financed home in 2016 and VA paid the holder a guaranty claim of $28,000. She has saved $30,000 and has a 702 score. She wants a $480,000 single-family home in Henderson.","structure":"Second-tier purchase using entitlement remaining after the loss","numbers":"Clark County limit = baseline $832,750; remaining = 25% x $832,750 - $28,000 = $180,188; max no-down loan $720,750, so $480,000 needs $0 down","why":"Even after a loss, remaining bonus entitlement covers a modest purchase with zero down","alternatives":"FHA after its 3-year short-sale wait; conventional after 4 years","watch":"Confirm whether VA established a debt she must repay; subsequent-use 3.30% fee unless exempt"}],"qa":[{"q":"What is second-tier (bonus) entitlement?","a":"The additional guaranty available above the basic $36,000, tied to the county conforming limit, that lets a veteran with a VA loan still open buy again."},{"q":"Can I own two VA-financed homes?","a":"Yes, if remaining entitlement covers the new loan or you make a down payment on the gap; the new home must be your primary residence."},{"q":"Do I have to sell my first home?","a":"No. You can keep it as a rental."},{"q":"How much down will I need?","a":"25% of the amount by which the loan exceeds four times your remaining entitlement."},{"q":"Can I restore entitlement instead?","a":"One-time restoration is possible if the prior loan is paid off and you still own the home; otherwise sell and pay off."},{"q":"Does rent from the old home count?","a":"Usually with a lease and, for some lenders, landlord history or reserves."},{"q":"Which funding fee applies?","a":"Subsequent use: 3.30% under 5% down, lower with 5% or 10% down."},{"q":"Why does county limit matter?","a":"Remaining entitlement is computed from the new property's county limit."},{"q":"What about a prior foreclosure?","a":"Unrepaid VA loss reduces entitlement until repaid."}],"aeQuestions":["Will you count rental income on the retained VA property with only a new lease?","Do you require landlord history or reserves when keeping the prior home?","Which county limit do you use when the new property is in a different county?","Do you accept VA's entitlement calculation on the COE or recompute it?","Can the down payment on the gap be gifted?","Do you require 2 months of reserves for each financed property?","How do you treat a prior VA loss with debt still owed?","Can you close second-tier files with DU Approve above 50% DTI?","Any overlay on loan amount when entitlement is partial?"],"redFlags":["COE entitlement figure doesn't match the borrower's story","Prior VA claim debt unpaid (reduces entitlement and may block approval)","Retained property lease signed by a relative at above-market rent","HOA on retained condo prohibits rentals","Down payment from an unseasoned or undocumented source","New 'primary' is really a second home","County limit used from the wrong county"],"pricing":"Second-tier loans price like any VA purchase; the main extra cost is the subsequent-use funding fee of 3.30% under 5% down, falling to 1.50% or 1.25% with 5% or 10% down. Because a down payment is often required anyway on the gap, coach the veteran on whether hitting the 5% or 10% threshold saves more fee than it costs in liquidity. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["PCS-return content: 'keep your first home, buy your next'","Agent training on remaining entitlement math","Veteran landlord meetups and property managers in Oceanside and Temecula","Annual entitlement review for past clients who still own VA homes","Base relocation office educational materials (where permitted)"],"checklist":["COE","Lease","Rental history","County limit printout","Entitlement calc","Income docs","Assets","Appraisal","Credit","Purchase contract"],"updated":"2026-11"},
"a_va_eem":{"matrix":[["Min FICO","Follows underlying VA purchase or refinance; overlays 580-640 (lender-specific)"],["Max EEM amount","Up to $3,000 with documented costs; up to $6,000 if the added monthly payment does not exceed the projected monthly utility savings; above $6,000 requires VA determination of value-based savings (verify current Lender Handbook Ch. 7)"],["LTV","EEM amount is added on top of the purchase or IRRRL loan; may exceed 100% of value; funding fee applies to total"],["Loan limits","No VA limit with full entitlement; EEM portion is not counted toward the 4% concession cap"],["DTI/AUS","EEM amount generally not used to recompute qualifying when within the $6,000 tier; projected savings not added to income (verify lender approach)"],["Residual income","Same VA table; some lenders reduce maintenance/utility estimate for documented efficiency (lender-specific)"],["Funding fee","Calculated on total loan including EEM; exempt veterans pay none"],["Eligible improvements","Solar PV and thermal, heat pumps, insulation, windows, weatherstripping, HVAC upgrades, water heaters, caulking; repairs to meet MPRs are not EEM"],["Energy audit","HERS or qualified energy assessment recommended and often required by lender for amounts over $3,000 (lender-specific)"],["Completion","Improvements completed within a set period after closing (often 6 months) with escrowed funds released after inspection (lender-specific)"],["Property types","Existing 1-4 unit primary residences; new construction usually ineligible because efficiency is already in price (verify)"],["IRRRL use","EEM can be added to an IRRRL as the only form of cash allowed, up to $6,000"],["Leased solar","Leased or PPA solar is not an EEM improvement and must be addressed by the appraiser and title (lender-specific)"],["States","Federal program; CA climate zones and NV/AZ heat make HVAC and solar the common items"]],"walkthrough":["Confirm the lender actually funds VA EEM (few do; ask before quoting)","Identify improvement scope and obtain contractor bids with license numbers","Order energy assessment if over $3,000 or if the lender requires it","Compute projected monthly utility savings and compare with added P&I from the EEM amount","Structure the base VA purchase or IRRRL normally; add EEM on top","Disclose total loan and funding fee on LE","Appraisal on as-is basis; EEM does not need to be supported by value at the $6,000 tier","Set up escrow holdback for improvement funds with disbursement instructions","Close; contractor completes within lender's deadline","Final inspection or contractor invoice and lien release; release funds","Keep receipts for federal energy tax credits if any remain available (verify; several credits ended after 2025)","Confirm utility savings with the veteran at 6 months to document outcome"],"incomeExample":{"title":"VA EEM $6,000 payment-vs-savings test, Temecula","steps":["Base VA purchase loan $620,000 for a 1998 home with original single-pane windows and a 20-year-old AC","Improvements: high-SEER heat pump $9,800 and dual-pane windows $7,200; EEM requested $6,000 (remaining costs paid by veteran or seller concession)","Added P&I on $6,000 at an illustrative 30-year payment factor of 0.0063 = $38/month (plus funding fee financed on $6,000: $129 at 2.15%)","Energy assessment projects summer cooling savings averaging $72/month over 12 months","Test: added payment $38-$39 is less than projected savings $72, so the $6,000 tier is supported","Net monthly benefit about $33 plus comfort and resale value"],"result":"Qualifies for the $6,000 EEM tier because projected savings exceed added payment; amounts above $6,000 would need VA-approved value-based support."},"scenarios":[{"t":"Inland Empire summer bills","who":"Carlos, 36, Marine veteran and UPS driver, Menifee","situation":"Carlos is buying a 1990s home whose AC unit is near end of life. His summer electric bills in the rental next door ran over $400. He wants to fix it at purchase rather than run up a credit card.","structure":"VA purchase with $6,000 EEM toward a heat pump","numbers":"Base loan $575,000 + EEM $6,000; added P&I about $38/month vs projected savings $85","why":"Finances efficiency at mortgage cost instead of card rates","alternatives":"Seller credit within 4% cap; PACE avoided due to lien priority issues","watch":"Lender availability; heat pump install timeline after closing"},{"t":"IRRRL plus insulation","who":"Teresa, 49, retired Navy Chief, Lake Havasu City AZ","situation":"Teresa is doing an IRRRL and her attic insulation is minimal. She wants to add insulation and radiant barrier. IRRRL otherwise allows no cash.","structure":"IRRRL with $3,500 EEM","numbers":"Recoupment test applies to IRRRL costs; EEM documented with bids","why":"Only way to add improvement funds to an IRRRL","alternatives":"Pay cash; utility rebates","watch":"Recoupment still must pass; EEM is not a cash-out"},{"t":"Solar on a San Diego purchase","who":"James, 44, Navy veteran and electrician, Spring Valley","situation":"James wants owned solar on his purchase so the system adds value at resale. Bids are $18,000 after removing utility incentives. He knows only $6,000 is easy.","structure":"VA EEM up to $6,000; balance from savings","numbers":"EEM $6,000; out-of-pocket $12,000","why":"Partial financing at mortgage cost","alternatives":"Solar loan (separate lien or UCC), lease (no ownership)","watch":"Net metering rules changed in CA (NEM 3.0) reduce savings estimates; use realistic numbers"},{"t":"Older Las Vegas home","who":"Denise, 52, Air Force veteran and nurse, Las Vegas NV","situation":"Denise is buying a 1985 home with leaky ducts and single-pane windows. Her energy audit lists duct sealing and windows. She is fee exempt.","structure":"VA purchase + $5,500 EEM","numbers":"No funding fee; added P&I $35/month vs $60 savings","why":"Comfort and lower bills with no fee","alternatives":"Seller concession for repairs","watch":"Escrow holdback documentation"},{"t":"Military family in Twentynine Palms","who":"Kevin, 30, Marine Sergeant, Twentynine Palms","situation":"Desert heat makes cooling costs high. The home has an aging swamp cooler. Kevin wants central heat pump.","structure":"VA purchase + EEM $6,000","numbers":"Price $310,000; EEM $6,000; projected savings $95/month","why":"Reduces energy burden in extreme climate","alternatives":"Seller credit","watch":"Contractor scheduling; ensure MPRs met separately"}],"qa":[{"q":"Is EEM a separate loan?","a":"No, it's added to the VA purchase or IRRRL amount."},{"q":"How much can I add?","a":"$3,000 with documentation, up to $6,000 if payment increase doesn't exceed projected savings, more with VA review."},{"q":"Does EEM count against my 4% seller concessions?","a":"No; it's financed, not a concession."},{"q":"Can I use it for repairs?","a":"Only energy-efficiency improvements; MPR repairs are separate."},{"q":"Can I use EEM for leased solar?","a":"No; leases are not owned improvements."},{"q":"Does the appraisal have to support it?","a":"Not for the $6,000 tier in most cases."},{"q":"Who does the work?","a":"A licensed contractor after closing, with funds escrowed."},{"q":"Can I do this on an IRRRL?","a":"Yes, up to $6,000."},{"q":"Is there a funding fee on the EEM?","a":"Yes, fee applies to the total loan unless exempt."}],"aeQuestions":["Do you fund VA EEM on purchase and IRRRL?","Do you require an energy audit at $3,000 or $6,000?","Escrow holdback process and deadline?","Can the EEM pay a solar contractor directly?","Do you allow EEM above $6,000?","How do you treat leased solar on the appraisal?","Draw/inspection fee?","Does EEM change your DTI calculation?"],"redFlags":["Contractor wants full payment before closing","EEM used for non-energy repairs","Savings estimate unrealistic after CA NEM 3.0","Leased solar mischaracterized as owned","Lender does not actually offer EEM","Improvements needed for MPRs being financed as EEM"],"pricing":"EEM adds little to pricing because it rides on the base VA loan, but the funding fee applies to the EEM amount and lenders may charge a holdback or inspection fee. Compare whether a seller concession for the same improvement is cheaper than financing it. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Inland Empire and desert-climate buyer content on cooling costs","Partner with licensed HVAC and insulation contractors (no referral payments; RESPA Section 8)","Military housing office energy-savings tips","Solar installer education on VA EEM limits","Past-client IRRRL plus efficiency campaigns"],"checklist":["Base VA loan file","Contractor bids with license numbers","Energy assessment / HERS report","Savings vs payment worksheet","Escrow holdback agreement","Contractor W-9 and insurance","Completion certificate","Lien release","Funding fee calc incl. EEM","Final inspection or invoice"],"updated":"2026-11"},
"a_va_nadl":{"matrix":[["Lender","VA itself is the direct lender; brokers do not originate or get paid. Steve's role is referral and education only"],["Eligibility","Native American veterans, or non-Native veterans married to Native Americans, purchasing on federal trust land, reservation land or allotted land under an MOU between the tribe and VA"],["Min FICO","No minimum score; VA underwrites credit history, income stability and residual income"],["Max LTV","Generally up to 100% of reasonable value (verify)"],["Loan limits","Tied to county conforming limits (2026 baseline $832,750, high-cost $1,249,125) for the loan amount (verify)"],["DTI/Residual","VA credit standards: 41% benchmark and regional residual income"],["Funding fee","1.25% for purchase/construction and 0.50% for IRRRL; exempt categories apply (verify current table)"],["Rate","Set by VA; no points; fixed 30-year"],["MOU requirement","Tribe must have a signed MOU with VA; San Diego County has many tribes (e.g., Pala, Pauma, Rincon, La Jolla, Barona, Viejas, Sycuan) but MOU status varies (verify)"],["Purposes","Purchase, construct, improve, or refinance (NADL IRRRL) a home on trust land; may finance improvements like energy upgrades"],["Property","Must meet MPRs; leasehold on trust land through tribal/BIA lease; title via BIA TSR"],["Occupancy","Primary residence"],["Timeline","Longer than conventional VA due to BIA lease approval and Title Status Report"],["States","Federal; available where MOUs exist, including many CA, AZ, NV tribes"]],"walkthrough":["Confirm tribal enrollment or spouse's enrollment and veteran status","Check whether the tribe has an MOU with VA","Connect veteran to the VA NADL regional loan specialist (Steve refers; no fee)","Pull COE","Gather income and credit documents","Tribe/BIA issue residential lease and approve encumbrance","Order BIA Title Status Report","VA appraisal","VA underwrites and issues commitment","Construction or purchase closes with VA as lender","Funding fee paid unless exempt","Steve follows up and stays available for future refinances outside trust land"],"incomeExample":{"title":"NADL residual income check, family of 5, Pauma Valley","steps":["Gross income: tribal government job $5,200 + VA compensation $1,100 (non-taxable) + spouse $2,400 = $8,700","Taxes on $7,600 taxable at 18% = $1,368; net $7,332","Construction loan $420,000 for new home on trust land; illustrative PITI $2,950 (property tax often not assessed on trust land, verify)","Maintenance 1,700 sq ft x $0.14 = $238; debts $450; childcare $300","Residual = $7,332 - $2,950 - $238 - $450 - $300 = $3,394","West family of 5 requirement $1,158; DTI = ($2,950 + $450)/$8,700 = 39%"],"result":"Residual of $3,394 exceeds $1,158 and DTI under 41%, so credit standards are met."},"scenarios":[{"t":"Building on allotted land","who":"Raymond, 45, Navy veteran and tribal fire captain, Pala","situation":"Raymond holds an assignment on his tribe's trust land and wants to build a 3-bedroom home for his family. Two conventional lenders declined because they cannot take a mortgage on trust land. His tribe reports an active MOU with VA (verify).","structure":"NADL construction loan with a BIA-approved residential lease and VA as lender","numbers":"Construction cost $410,000 (illustrative); 1.25% funding fee unless exempt","why":"The most practical long-term fixed financing on trust land for a veteran","alternatives":"HUD Section 184 (also trust-land capable); tribal housing authority programs","watch":"BIA lease and Title Status Report timelines; builder must meet VA standards"},{"t":"Non-Native veteran married to a tribal member","who":"Melissa, 39, Army veteran and RN, Valley Center","situation":"Melissa is not Native American, but her husband is an enrolled member of a local band. They want to buy an existing home on the reservation that a relative is selling. She has a full COE and a 710 score.","structure":"NADL purchase with Melissa as the eligible veteran, home on trust land","numbers":"Price $350,000 (illustrative); 0% down; funding fee 1.25% unless exempt","why":"Spouse-of-Native path opens NADL to a non-Native veteran","alternatives":"Section 184 using her husband's enrollment","watch":"Tribal rules may require the enrolled spouse on the lease"},{"t":"Lowering an existing NADL payment","who":"Henry, 61, Marine veteran and retired BIA employee, Fort Mojave AZ","situation":"Henry took an NADL in 2019 and wants a lower payment on a fixed income. He has paid on time for six years. He does not want cash out.","structure":"NADL IRRRL directly through VA","numbers":"0.50% funding fee unless exempt; payment reduction depends on VA's posted rate","why":"Streamlined path that stays with VA","alternatives":"None practical on trust land other than Section 184 refinance","watch":"NTB and seasoning rules similar to VA IRRRL"},{"t":"Roof and solar on an NADL home","who":"Lorraine, 52, Air Force veteran and teacher, Barona","situation":"Lorraine's 2007 home needs a new roof, and she wants owned solar to cut bills. She has $15,000 saved and wants to finance the rest. Her tribe's housing office also offers small repair grants.","structure":"NADL refinance for improvements, combined with tribal grant","numbers":"Improvements $34,000; grant $8,000; financed $26,000 (illustrative)","why":"Keeps one VA lien on trust land at a set rate","alternatives":"Tribal grant only; personal loan","watch":"VA inspection of completed work; contractor licensing"},{"t":"Manufactured home on assigned land","who":"Jordan, 29, Navy veteran and IT technician, Rincon","situation":"Jordan and his wife are moving home after his enlistment. They want a new manufactured home on a permanent foundation on land assigned by the tribe. They have $6,000 saved.","structure":"NADL for manufactured home classified as real property on trust land","numbers":"Home and site work $210,000 (illustrative); 0% down","why":"Zero down and fixed rate where few lenders operate","alternatives":"Section 184; chattel loan (higher cost)","watch":"Foundation engineer certification; lease term must exceed loan term"}],"qa":[{"q":"Can Steve originate an NADL?","a":"No. VA is the lender; Steve can educate and refer at no charge."},{"q":"Do I have to live on the reservation?","a":"The home must be on eligible trust/reservation land and be your primary residence."},{"q":"Is there a down payment?","a":"Usually none (verify)."},{"q":"Can a non-Native veteran use NADL?","a":"Yes, if married to a Native American and the home is on eligible land."},{"q":"How long does it take?","a":"Often longer than private loans due to BIA lease and title report."},{"q":"What if my tribe doesn't have an MOU?","a":"The tribe must sign one before NADL can be used."},{"q":"Is there a funding fee?","a":"Yes unless exempt."},{"q":"Can I refinance into a lower rate later?","a":"Yes via NADL IRRRL."}],"aeQuestions":["(For VA NADL office) Does the tribe have a current MOU?","Which regional NADL specialist covers San Diego County tribes?","Typical BIA lease and TSR timeline?","Builder requirements for construction?","Manufactured home eligibility on trust land?","Funding fee for construction vs purchase?","Can a Section 184 loan be refinanced into NADL?","Property tax treatment on trust land?"],"redFlags":["Someone charges the veteran a broker fee for NADL (VA is direct lender)","Tribe has no MOU","Land is fee simple, not trust (other programs fit)","Lease not approved by BIA","Construction contract lacks VA-acceptable builder","Unclear enrollment documentation"],"pricing":"NADL rates are set by VA and there are no points, so pricing comparison is mainly against Section 184 and tribal programs. Funding fee applies unless exempt. Steve earns nothing on NADL referrals and should say so clearly to avoid any appearance of conflict. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Tribal veterans representative (TVR) relationships","Education at tribal veteran events (with tribal permission)","Partner with tribal housing departments","Content comparing NADL vs Section 184","Native veteran organizations"],"checklist":["COE","Tribal enrollment documentation","Marriage certificate if spouse eligibility","Tribe/VA MOU confirmation","BIA residential lease","Title Status Report","Income docs","Credit report","VA appraisal","Construction contract and plans if building","Funding fee exemption proof"],"updated":"2026-11"},
"a_calvet":{"matrix":[["Structure","Land-sale contract: CalVet buys the home and sells it to the veteran; CalVet holds title until payoff (CalVet/VA uses VA guaranty)"],["Programs","CalVet/VA (zero down using VA guaranty), CalVet 80/20 style, CalVet 97 (non-VA-guaranteed, 3% down), CalVet Home Improvement, manufactured home on rented land, CalVet construction (verify current menu)"],["Min FICO","CalVet/VA follows VA; CalVet 97 requires credit standards similar to conventional, often 620+ (verify)"],["Max LTV","CalVet/VA 100% plus funding fee; CalVet 97 at 97%; mobile home in park lower (verify)"],["Loan limits","CalVet/VA tied to county conforming limit (2026 baseline $832,750; high-cost up to $1,249,125) (verify CalVet's current cap)"],["Funding fee","CalVet/VA: VA funding fee applies unless exempt; CalVet 97: CalVet funding fee (e.g. 1.25% verify); origination fee typically 1%"],["Disaster coverage","CalVet includes disaster indemnity (flood and earthquake) coverage with deductible; fire/hazard through CalVet's master policy (verify premium and deductible)"],["Life insurance","Optional CalVet life and disability coverage available (verify)"],["Eligibility","Veterans with honorable service including peacetime; CalVet 97 for those not VA-eligible; currently serving members eligible (verify)"],["Occupancy","Must occupy as primary residence; rental restrictions without CalVet approval"],["Property types","Single-family, condos, manufactured homes on owned land or in parks, small farms (verify)"],["Rate","Set by CalVet, funded by bonds; variable by program but historically stable"],["Brokers","Originated through CalVet-approved lenders/brokers; Steve can originate if Patriot Pacific is approved (verify)"],["States","California only"]],"walkthrough":["Confirm veteran status and which CalVet program fits (CalVet/VA, CalVet 97, mobile home, home improvement)","Explain the land-sale contract structure and CalVet's insurance coverage","Compare CalVet rate, origination fee and insurance against standard VA and conventional","Pull COE (for CalVet/VA) and credit","Submit through a CalVet-approved originator","Disclose CalVet fees and insurance premiums","Order appraisal","CalVet underwriting and approval","Lock CalVet rate per program rules","Enroll in CalVet insurance coverage","Close through CalVet; CalVet holds title under the contract","Post-close: payments to CalVet and annual insurance review"],"incomeExample":{"title":"Cost comparison: CalVet/VA vs standard VA for disaster coverage, Escondido","steps":["Purchase $700,000, both programs zero down; first-use funding fee 2.15% = $15,050 on each","Standard VA: veteran must buy separate earthquake policy (CEA) estimated $1,600/year = $133/month","CalVet: disaster indemnity included with deductible; CalVet premium assumed $90/month (verify)","CalVet origination fee 1% = $7,000 vs lender fees on standard VA, say $4,500","Difference: CalVet extra $2,500 upfront; saves about $43/month on insurance","Breakeven = $2,500 / $43 = 58 months"],"result":"CalVet becomes cheaper after about 5 years if insurance savings hold; rates and fees must be compared at application."},"scenarios":[{"t":"Earthquake coverage in North County","who":"Jose, 48, Marine veteran and HVAC technician, Escondido","situation":"Jose is buying a $680,000 home and private earthquake quotes came in around $1,500/year with a high deductible. He plans to stay 10+ years. His COE shows full entitlement.","structure":"CalVet/VA zero-down purchase with CalVet disaster indemnity coverage","numbers":"VA funding fee 2.15% ($14,620) unless exempt; CalVet origination 1% ($6,800) (verify)","why":"Built-in disaster coverage can beat stand-alone quake insurance over a long hold","alternatives":"Standard VA purchase plus CEA policy","watch":"Compare total fees at application; understand land-sale contract and deductible"},{"t":"Peacetime veteran short of VA minimums","who":"Sandra, 54, Army veteran (served 20 months in early 1990s), Riverside","situation":"Sandra was told her service may not meet VA's minimum for a COE. She has $18,000 saved and a 690 score. She wants a $520,000 home near her job.","structure":"CalVet 97 (non-VA guaranteed, 3% down)","numbers":"Down $15,600; CalVet funding fee and origination per current schedule (verify)","why":"Veteran-specific program with broader eligibility","alternatives":"FHA 3.5% down; conventional 97 with MI","watch":"Confirm CalVet's current service definition; compare MI-free CalVet cost vs FHA MIP"},{"t":"Manufactured home in a 55+ park","who":"Walter, 70, Navy veteran, Hemet","situation":"Walter sold his house and wants a newer manufactured home in a 55+ park on leased land. Chattel lenders quoted much higher costs. He has $40,000 down.","structure":"CalVet manufactured home in park loan (verify current program terms)","numbers":"Home $150,000; down $40,000; financed $110,000","why":"Bond-funded rate and veteran program can undercut chattel financing","alternatives":"Chattel lender; cash purchase","watch":"Park lease length and rent increases; CalVet park approval"},{"t":"Roof replacement for an existing CalVet borrower","who":"Grace, 63, Air Force veteran, Santee","situation":"Grace has owned through CalVet since 2012 and needs a $32,000 roof. She doesn't want to refinance her low existing rate. She has limited savings.","structure":"CalVet Home Improvement loan (verify current availability and limits)","numbers":"$32,000 at CalVet terms","why":"Keeps existing CalVet contract intact","alternatives":"HELOC (would require subordination to CalVet's title position)","watch":"CalVet approval of contractor and scope"},{"t":"Young sailor wanting zero down plus disaster coverage","who":"Nate, 26, Navy Petty Officer Second Class, Chula Vista","situation":"Nate is on shore duty for three years and wants to buy a condo. He has $8,000 saved. He likes CalVet's built-in coverage because the condo HOA's master policy excludes earthquake.","structure":"CalVet/VA zero-down condo purchase","numbers":"Price $520,000; VA fee 2.15% unless exempt","why":"Covers a gap in HOA insurance","alternatives":"Standard VA purchase; FHA","watch":"Condo must meet VA and CalVet approval; deployment occupancy rules"}],"qa":[{"q":"Can I refinance out of CalVet later?","a":"Yes, you can refinance with another lender at any time."},{"q":"Is there a funding fee?","a":"CalVet/VA loans use the VA funding fee unless exempt; CalVet 97 has its own fee (verify)."},{"q":"Can I rent out a CalVet home?","a":"Not without CalVet's approval; it must be your residence."},{"q":"Can a mortgage broker originate CalVet?","a":"Yes, through CalVet-approved lenders and brokers (verify Patriot Pacific's status)."},{"q":"Is CalVet's rate better than VA?","a":"Sometimes; CalVet rates move with bond funding, so compare on the same day."},{"q":"Who owns the house under CalVet?","a":"CalVet holds title under a land-sale contract until payoff; the veteran has equitable ownership."},{"q":"Is CalVet only for wartime veterans?","a":"No, peacetime veterans can qualify under current law (verify specifics)."},{"q":"Does CalVet include disaster insurance?","a":"Yes, coverage including flood and earthquake indemnity with a deductible (verify)."}],"aeQuestions":["Is Patriot Pacific approved to originate CalVet?","Current CalVet loan limit?","Current CalVet origination fee?","Insurance premium and deductible?","Turn times?","CalVet 97 credit standards?","Mobile home park requirements?","Construction loan availability?"],"redFlags":["Veteran unaware CalVet holds title under a land-sale contract until payoff","Plans to rent the home without CalVet approval","Short expected hold erodes the 1% origination fee and funding fee value","Borrower misunderstands disaster coverage deductible or assumes it replaces all private coverage","Property outside California or not eligible type for the chosen CalVet program","Originator not approved for CalVet submissions","Comparing CalVet's bond-funded rate to a market quote from a different day"],"pricing":"CalVet rates come from bond funding and don't follow daily market pricing, so they can lag market moves up or down. Origination and funding fees plus insurance premiums must be compared with standard VA. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["County Veterans Service Offices","CalVet events","Veteran content on earthquake coverage","Peacetime veteran outreach","55+ park veteran outreach"],"checklist":["COE / DD-214","CalVet application","Credit","Income","Assets","Appraisal","Insurance enrollment","Purchase contract","Funding fee","Land-sale contract docs"],"updated":"2026-11"},
"a_fha_purchase":{"matrix":[["Min FICO","HUD: 580+ for 3.5% down; 500-579 requires 10% down. Common wholesale overlays 580-640; some allow sub-580 only with TOTAL approve (lender-specific)"],["Max LTV/CLTV","96.5% LTV; CLTV can exceed 100% with HUD-allowed government or nonprofit DPA seconds such as CalHFA or county programs (lender-specific)"],["Loan limits","2026 floor $541,287 for 1 unit (65% of $832,750); high-cost ceiling about $1,249,125 (verify); San Diego and Riverside County limits differ (verify HUD lookup)"],["DTI/AUS","TOTAL Scorecard Accept often allows back-end ratios into the mid-50s; manual UW 31/43 base, up to 37/47 or 40/50 with documented compensating factors"],["MIP","UFMIP 1.75%; annual 0.55% for base loan up to $726,200 with LTV over 95% (0.50% at or below 95%); above $726,200: 0.75%/0.70%. Life of loan when LTV over 90%, 11 years when 90% or less (ML 2023-05; verify no 2026 change)"],["Reserves","None for 1-2 units with TOTAL Accept; 3 months PITI for 3-4 units; manual UW needs reserves as compensating factor"],["Waiting periods","Ch. 7 BK 2 years from discharge; Ch. 13 after 12 months of on-time plan payments with trustee approval; foreclosure, deed-in-lieu and short sale 3 years (extenuating circumstances may shorten)"],["Residency","U.S. citizens and lawful permanent residents only; non-permanent residents ineligible for case numbers assigned on or after May 25, 2025 (ML 2025-09); SSN card alone does not prove status"],["Property types","1-4 units owner-occupied, FHA-approved condo projects or single-unit approval, PUDs, manufactured homes as real property"],["Occupancy","Primary residence occupied within 60 days and for at least one year; one FHA loan at a time with limited exceptions"],["Appraisal","FHA roster appraiser; minimum property standards (peeling paint pre-1978, roof, safety, utilities); appraisal valid 180 days and transferable"],["Flipping rule","Seller-acquired within 90 days: ineligible; 91-180 days with price 100%+ above acquisition: second appraisal required"],["Concessions","Seller may contribute up to 6% of sales price toward closing costs, prepaids, UFMIP and discount points"],["States","CA, IL, NV, FL, AZ all eligible; county limits and DPA programs vary by state"]],"walkthrough":["Confirm citizenship or lawful permanent resident status first; non-permanent residents are no longer eligible","Pull tri-merge and run TOTAL through DU or LPA; note any refer requiring manual UW","Check the county FHA limit for the target area and the 2-4 unit limits if relevant","Explain UFMIP and annual MIP, including life-of-loan MIP at 96.5% LTV","Layer down payment assistance if needed (CalHFA, county or city programs) and confirm lender acceptance","Issue pre-approval with a payment that includes MIP, taxes, HOA and Mello-Roos","Coach the buyer's agent on FHA repair items and the 6% concession cap","Order case number and appraisal; check flipping rule on seller's acquisition date","Clear conditions: gift letters with transfer trail, VOEs, explanation letters","Review CD: UFMIP financed, MIP monthly, DPA second terms","Close, fund, and track FHA insurance endorsement","Calendar a 210-day streamline review and an annual equity check for a conventional refinance to drop MIP"],"incomeExample":{"title":"FHA MIP and DTI, El Cajon purchase","steps":["Purchase $620,000; 3.5% down $21,700; base loan $598,300","UFMIP 1.75% = $10,470; total loan $608,770","Annual MIP 0.55% x $598,300 / 12 = $274/month","PITI: illustrative P&I $3,840 + taxes $646 + insurance $150 + MIP $274 = $4,910","Gross income $9,800/month; other debts $450","Front-end ratio $4,910 / $9,800 = 50.1%; back-end ($4,910 + $450) / $9,800 = 54.7%","Manual UW maximum with two compensating factors is 40/50, so this requires TOTAL Accept"],"result":"Works only with an automated Accept; lowering price to about $540,000 brings back-end near 48% for a safer file."},"scenarios":[{"t":"First-time buyer with a 612 score","who":"Alyssa, 28, dental assistant, Chula Vista","situation":"Alyssa has a 612 middle score after a medical collection and a past late car payment. She has $24,000 saved and earns $5,900/month. She wants a townhome near work and is renting at $2,300/month.","structure":"FHA purchase, 3.5% down, seller credit toward closing costs","numbers":"Price $470,000; down $16,450; base loan $453,550; UFMIP $7,937; MIP about $208/month","why":"FHA pricing is far less sensitive to a 612 score than conventional MI and LLPAs","alternatives":"Conventional 97 (MI expensive at 612); CalHFA FHA with DPA","watch":"Townhome HOA must be FHA-approved or eligible for single-unit approval"},{"t":"Military spouse preserving VA entitlement","who":"Brianna, 31, teacher and Marine spouse, Murrieta","situation":"Her husband has a VA loan on a rental in Jacksonville NC that uses most of his entitlement. Brianna qualifies on her own income. Her parents are gifting $20,000.","structure":"FHA purchase in Brianna's name with documented gift","numbers":"Price $560,000; down $19,600; gift covers down plus part of costs","why":"Keeps the couple's remaining VA entitlement free and avoids subsequent-use fee","alternatives":"VA second-tier with down payment; conventional 95%","watch":"Gift letter, donor bank statement and transfer trail; spouse's debts count in community property states for FHA"},{"t":"Duplex house hack","who":"Victor, 35, union electrician, Escondido","situation":"Victor wants to live in one unit and rent the other for $2,300. He has $40,000 saved and a 680 score. He has never been a landlord.","structure":"FHA 2-unit purchase","numbers":"Price $850,000 (must be under the 2-unit county limit; verify); down $29,750; rental income at 75% of market rent = $1,725","why":"3.5% down on a 2-unit is rare; rental income offsets payment","alternatives":"Conventional 2-4 unit at 5% down (needs higher score); VA if eligible","watch":"Self-sufficiency test applies only to 3-4 units; repairs per FHA MPS"},{"t":"Two years after Chapter 7","who":"Kim, 42, ER nurse, Las Vegas NV","situation":"Kim's Chapter 7 discharged 26 months ago after a divorce. She has re-established credit with two secured cards and a car loan paid on time. Her score is 655.","structure":"FHA purchase","numbers":"Price $420,000; down $14,700","why":"FHA's 2-year wait vs 4 years for conventional","alternatives":"Wait for conventional","watch":"Letter of explanation and re-established credit; no new derogatories"},{"t":"Lawful permanent resident","who":"Lucia, 37, staff accountant, National City","situation":"Lucia received her green card in 2024. She rents and has $30,000 saved. Her coworker told her FHA no longer works for immigrants.","structure":"FHA purchase documenting LPR status with green card","numbers":"Price $650,000 (above floor, verify San Diego limit); down $22,750","why":"LPRs remain eligible; only non-permanent residents were removed","alternatives":"Conventional (allows non-permanent residents with work authorization)","watch":"Card must be unexpired or with valid extension; SSN card alone is not proof"},{"t":"Non-permanent resident redirected to conventional","who":"Arjun, 33, software engineer on an H-1B visa, San Marcos","situation":"Arjun pre-qualified for FHA in early 2025, but his lender could not get a case number after May 25, 2025 because he is a non-permanent resident. He has 8% down and a 740 score. His employer has sponsored his green card, which is still pending.","structure":"Conventional purchase at 92% LTV with BPMI","numbers":"Price $700,000; down $56,000; loan $644,000","why":"Fannie and Freddie still allow lawful non-permanent residents with valid work authorization, and at 740 conventional MI is competitive","alternatives":"Non-QM foreign national program (costlier); wait for green card then FHA","watch":"Visa and EAD expiration dates; lender continuance policy"}],"qa":[{"q":"Can non-permanent residents still get FHA?","a":"No. Case numbers assigned on or after May 25, 2025 require U.S. citizenship or lawful permanent residency."},{"q":"How long do I pay MIP?","a":"For the life of the loan if you put under 10% down; 11 years with 10% or more. Many borrowers later refinance to conventional to remove it."},{"q":"What is UFMIP?","a":"An upfront premium of 1.75% of the base loan, usually financed into the loan."},{"q":"How much can the seller pay?","a":"Up to 6% of the price toward closing costs, prepaids, UFMIP and points."},{"q":"Can I buy a fixer?","a":"Only if it meets minimum property standards; otherwise look at 203(k)."},{"q":"What credit score do I need?","a":"HUD allows 580 for 3.5% down; most lenders want 580-640."},{"q":"Can family gift the down payment?","a":"Yes, with a gift letter and documented transfer."},{"q":"Can a parent co-sign who won't live there?","a":"Yes, a non-occupant co-borrower relative can be added; max LTV may be limited on 2-4 units."},{"q":"Is FHA assumable?","a":"Yes, with credit qualification of the buyer."},{"q":"Can I have two FHA loans?","a":"Generally no, except relocation, family size or co-borrower departure exceptions."}],"aeQuestions":["Minimum FICO for TOTAL Accept and for manual UW?","Maximum DTI you'll accept with Accept?","Which DPA seconds do you fund in San Diego and Riverside?","Do you do FHA single-unit condo approvals?","How do you verify LPR status and handle expiring cards?","Non-occupant co-borrower limits on 2-4 units?","Do you require repairs completed before closing or allow escrow holdbacks?","Turn time on case number to clear-to-close?","How do you handle the 91-180 day flip rule?","Do you price FHA 2-4 units differently?"],"redFlags":["Borrower is a non-permanent resident (ineligible after May 25, 2025)","Seller acquired the property within 90 days","Gift funds without a transfer trail","Condo project not approved and HOA unresponsive","Peeling paint on a pre-1978 home (lead-based paint repair)","Occupancy doubts, such as a long commute or second FHA loan","Undisclosed child support or IRS payment plan","Large deposits not sourced"],"pricing":"FHA rates are often competitive because Ginnie Mae execution is strong, but the all-in cost includes 1.75% UFMIP and annual MIP for life at 96.5% LTV. Credit-score adjusters are milder than conventional LLPAs, which is why FHA often wins below roughly 680. Compare lender-paid credit options against the 6% seller concession cap. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["First-time buyer workshops with HUD-approved housing counselors","CalHFA and county DPA explainer content","Agent lunch-and-learns on FHA repair items and flip rules","Credit-rebuild partnerships with nonprofit counselors (no referral fees)","Spanish-language education where Steve or team can serve compliantly","Content clarifying the 2025 residency change for green card holders"],"checklist":["Government ID","Green card if LPR (citizenship confirmation otherwise)","Tri-merge credit","30 days paystubs and 2 years W-2s","2 months bank statements","Gift letter and transfer evidence","Purchase contract and addenda","FHA case number assignment","FHA appraisal with MPS review","Amendatory clause and Real Estate Certification","DPA program documents","Homeowners insurance","Letters of explanation for credit events","VOE (verbal) prior to closing"],"updated":"2026-11"},
"a_fha_203k_std":{"matrix":[["Min FICO","HUD 580 for 96.5%; most 203(k) lenders overlay 620-660 for Standard (lender-specific)"],["Max LTV","96.5% of the lesser of (a) as-is value or price plus rehab costs or (b) 110% of after-improved value; refinance uses existing debt + costs"],["Loan limits","Total mortgage including rehab must fit the FHA county limit (2026 floor $541,287; verify county)"],["Minimum repair","At least $5,000 in eligible repairs; no maximum other than county limit"],["Consultant","HUD-approved 203(k) consultant required: feasibility study, work write-up, draw inspections"],["Eligible work","Structural repairs, additions, room conversions, foundation, roof, major systems, accessibility, energy, lead/asbestos; no luxury items like new pools"],["Contingency reserve","10-20% of repair costs required (20% when utilities aren't operable or older structures)"],["Mortgage payment reserve","Up to 6 months PITI may be financed when the home cannot be occupied during rehab"],["Timeline","Work generally completed within 6 months; draws per consultant inspection; 203(k) holdback account"],["MIP","Same as FHA purchase: 1.75% UFMIP and annual MIP on total loan"],["Property types","1-4 units; condos limited to interior work in approved projects; mixed-use allowed with limits; demolition with existing foundation remaining"],["Occupancy","Primary residence; investors not allowed (except HUD nonprofit exceptions)"],["Residency","Citizens and lawful permanent residents only (ML 2025-09)"],["States","All of Steve's states; CA permitting timelines drive schedule risk"]],"walkthrough":["Confirm citizenship/LPR and credit fit for 203(k) lender overlays","Select a HUD-approved consultant and schedule feasibility walk-through before contract or during option period","Obtain contractor bids matching the consultant's work write-up; verify CSLB license and insurance","Compute maximum mortgage using both value tests","Order as-is and after-improved appraisal (subject-to based on write-up)","Underwrite borrower, contractor and scope","Structure contingency and payment reserve","Close; rehab funds go to escrow/holdback account","Contractor starts within 30 days; consultant performs draw inspections","Change orders approved by lender and consultant","Final inspection, final draw, title update","Unused contingency applied to principal","Issue final release and confirm FHA endorsement"],"incomeExample":{"title":"203(k) Standard maximum mortgage, Lemon Grove","steps":["Price $560,000; repairs $95,000 (kitchen, roof, foundation work); consultant fee $1,200; permits $3,500; contingency 15% of $95,000 = $14,250","Total rehab costs = $95,000 + $1,200 + $3,500 + $14,250 = $113,950","Test A: price + rehab = $673,950 x 96.5% = $650,362","Test B: after-improved value $720,000 x 110% = $792,000 x 96.5% = $764,280","Base loan = lesser = $650,362 (must be under San Diego FHA limit; verify)","UFMIP 1.75% = $11,381; total loan $661,743","Cash needed: $673,950 - $650,362 = $23,588 down plus closing costs"],"result":"Base mortgage about $650k, with $23.6k down; contingency unused at completion pays down principal."},"scenarios":[{"t":"1960s fixer with a failing roof","who":"Daniel, 33, Navy veteran and machinist, Lemon Grove","situation":"Daniel found a 1960s ranch with an original kitchen, a roof at end of life and some foundation cracking. His wife's 625 score makes conventional renovation pricing poor, and VA renovation lenders are scarce. They have $32,000 saved and rent at $2,600 nearby.","structure":"FHA 203(k) Standard with consultant, 15% contingency","numbers":"Price $560,000; total rehab $113,950; base loan $650,362; down about $23,600","why":"Buys and fixes in one closing with one FHA payment","alternatives":"VA renovation (limited lenders); Fannie HomeStyle (needs better credit pricing)","watch":"Foundation item needs engineer letter; choose a contractor experienced with draws"},{"t":"Junior ADU for a parent","who":"Elena, 45, ICU nurse, Chula Vista","situation":"Elena wants to convert an attached garage into a junior ADU so her mother can move in. The home is in fair condition otherwise. Her score is 640 and she has $35,000 saved.","structure":"203(k) Standard financing conversion and permits","numbers":"Price $690,000 (verify county limit); rehab $120,000 with contingency; max mortgage via lesser-of tests","why":"Room conversions and additions are eligible Standard work","alternatives":"HomeStyle or CHOICERenovation (ADU-friendly, better above 700 credit)","watch":"Appraiser must support after-improved value; total loan must fit FHA limit"},{"t":"Foundation settling buyers walked away from","who":"Tom, 50, HVAC technician, Hemet","situation":"The listing has had two buyers cancel after inspections showed foundation settlement. The seller dropped the price. Tom has a 660 score and $20,000 saved.","structure":"203(k) Standard with structural engineer scope","numbers":"Price $395,000; rehab $62,000 incl. contingency; base loan about $441,000","why":"Structural repairs are allowed only on Standard, not Limited","alternatives":"Cash or hard money (expensive); seller repair credit (not large enough)","watch":"Engineer report drives scope; contingency at 20% if unknowns remain"},{"t":"Fire-damaged home in the backcountry","who":"Rita, 39, teacher, Ramona","situation":"Rita is buying a home with partial fire damage at a discount. It can't be lived in for several months. She will keep renting during rehab.","structure":"203(k) Standard with up to 6 months of mortgage payment reserve financed","numbers":"Price $430,000; rehab $180,000; payment reserve 6 x $3,500 = $21,000","why":"Payment reserve prevents double housing cost during rebuild","alternatives":"Hard money plus refinance (two closings); conventional HomeStyle","watch":"Insurance availability in high fire-risk zones (CA FAIR Plan); permitting timeline"},{"t":"Accessibility remodel with a VA grant","who":"Gary, 58, disabled Army veteran, Temecula","situation":"Gary uses a wheelchair and is buying a single-story home that needs a ramp, wider doors and a roll-in shower. He qualifies for a VA Specially Adapted Housing grant but the grant timing is uncertain. He prefers FHA because his VA entitlement is tied up.","structure":"203(k) Standard for accessibility work; coordinate with SAH grant","numbers":"Price $540,000; rehab $78,000; grant may reimburse or reduce financed scope (verify)","why":"Accessibility items are eligible and can be completed right after closing","alternatives":"VA purchase with SAH grant only; HomeStyle","watch":"Grant and draw coordination; avoid double funding the same work"}],"qa":[{"q":"What is the minimum repair amount?","a":"$5,000 in eligible repairs for Standard."},{"q":"Do I need a 203(k) consultant?","a":"Yes. The consultant writes the scope, estimates costs and inspects draws."},{"q":"Can I do the work myself?","a":"Rarely; lenders require licensed contractors and HUD self-help is narrow."},{"q":"How long can rehab take?","a":"Generally up to 6 months; lenders track progress through draws."},{"q":"Can I live elsewhere during the work?","a":"Yes, and up to 6 months of mortgage payments can be financed if the home is uninhabitable."},{"q":"Can I add a room or ADU?","a":"Yes, additions and conversions are eligible Standard work."},{"q":"Can I add a pool or outdoor kitchen?","a":"No, luxury items are ineligible."},{"q":"What happens if costs run over?","a":"Contingency covers overruns first; beyond that the borrower pays."},{"q":"What happens to unused contingency?","a":"It is applied to principal or used for additional eligible work per lender approval."},{"q":"Can I refinance into a 203(k)?","a":"Yes, an owner can do a 203(k) refinance to fund repairs."}],"aeQuestions":["Minimum FICO and max DTI for 203(k) Standard?","Do you have an approved consultant roster for San Diego and Riverside?","Contractor requirements: years licensed, insurance, references?","How many draws and how fast are draw payments?","Max loan amount and supplemental origination fee?","Do you allow ADU additions and garage conversions?","Will you finance mortgage payment reserves?","How are change orders approved?","Can permits be pending at closing?","Do you allow 2-4 unit Standard 203(k)?"],"redFlags":["Contractor lacks a CSLB license or adequate insurance","Bid far below consultant estimate","Permits not obtainable or slow jurisdiction","Borrower plans to do much of the work themselves","After-improved appraisal does not support value","Unrealistic completion timeline","Property in an area where insurance is hard to obtain","Scope includes ineligible luxury items"],"pricing":"203(k) Standard usually prices above a standard FHA purchase and carries a supplemental origination fee (greater of $350 or 1.5% of rehab costs), consultant fees and draw inspection fees. UFMIP and annual MIP apply to the full mortgage including rehab. Compare total cost against HomeStyle or CHOICERenovation when credit is strong, since conventional MI can drop off later. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Fixer-upper buyer workshops with listing agents of older homes","Licensed contractor education on draw processes (no referral payments)","Agent content on how to write offers on homes that won't pass standard FHA","Older-home neighborhoods: Lemon Grove, La Mesa, Spring Valley, Hemet","Veteran accessibility content with SAH grant coordination"],"checklist":["Consultant feasibility","Work write-up","Contractor bid","Contractor license/insurance","Appraisal as-is and ARV","Max mortgage worksheet","Contingency calc","Rehab agreement","Draw schedule","Permits","Income docs","Assets"],"updated":"2026-11"},
"a_fha_203k_ltd":{"matrix":[["Min FICO","HUD 580 for 96.5%; overlays 600-640 common (lender-specific)"],["Max LTV","96.5% of the lesser of (as-is value or price plus rehab costs) and 110% of after-improved value (verify current HUD 4000.1 method)"],["Rehab cap","Up to $75,000 in total rehab costs including contingency (raised from $35,000 by ML 2024-13; verify)"],["Loan limits","Total loan must fit FHA county limit; 2026 floor $541,287 (verify county)"],["Eligible work","Non-structural: kitchens, baths, flooring, paint, roof replacement, HVAC, windows, water heaters, accessibility, energy items, minor remodel"],["Ineligible work","Structural alterations, additions, room moves, landscaping/luxury, work needing more than 2 draws beyond limits, anything requiring architectural exhibits"],["Consultant","Not required; lender may still require one when cost exceeds a threshold (lender-specific)"],["Contingency","Not required by HUD but often required by lenders at 10% (lender-specific)"],["Draws","Up to 2 draws typical; 50% upfront to contractor permitted for materials in some cases (verify)"],["Timeline","Work to start within 30 days and finish within 6 months (lender-specific tighter windows common)"],["MIP","Standard FHA 1.75% UFMIP plus annual MIP on total loan"],["Occupancy","Primary residence; must be habitable at closing (no payment reserve available)"],["Residency","Citizens and lawful permanent residents only (ML 2025-09)"],["States","All of Steve's licensed states"]],"walkthrough":["Walk the property with the buyer and a contractor to confirm scope is non-structural","Get licensed contractor bid(s) with line-item costs","Check total rehab including contingency and fees fits $75,000","Calculate maximum mortgage with both value tests","Order subject-to appraisal using the bid","Underwrite borrower and contractor","Sign rehab loan agreement and homeowner/contractor agreement","Close; rehab funds held in escrow","First draw (materials/deposit per lender policy)","Contractor completes work","Final inspection by appraiser or lender inspector","Final draw paid, title endorsement, lien releases","Unused funds applied to principal"],"incomeExample":{"title":"203(k) Limited max mortgage, Santee condo-to-house upgrade","steps":["Price $585,000; contractor bid $48,000 (kitchen, flooring, HVAC); 10% contingency (lender-required) $4,800; permit $1,200","Total rehab = $54,000, under $75,000 cap","Price + rehab = $639,000 x 96.5% = $616,635","After-improved value $660,000 x 110% = $726,000 x 96.5% = $700,590","Base loan = lesser = $616,635 (verify San Diego limit)","UFMIP 1.75% = $10,791; total loan $627,426","Down payment = $639,000 - $616,635 = $22,365"],"result":"Buyer brings about $22.4k down and finances $54k of updates into the FHA loan."},"scenarios":[{"t":"Dated kitchen and floors","who":"Monica, 30, pharmacy tech, Santee","situation":"Monica found a solid house with a 1980s kitchen and stained carpet. She'd rather update before moving in than live through a remodel later. She has $28,000 saved and a 648 score.","structure":"203(k) Limited with $54,000 scope","numbers":"Price $585,000; base loan $616,635; down $22,365","why":"Updates financed at mortgage cost, no consultant needed","alternatives":"Cash-flow remodel later with personal loans; HomeStyle","watch":"Contractor scheduling within 30 days of closing"},{"t":"Roof and HVAC on a Hemet home","who":"Luis, 41, warehouse lead, Hemet","situation":"Inspection showed a 25-year-old roof and failing AC. The seller won't credit more than $5,000. Luis's budget can't absorb $30,000 of repairs.","structure":"203(k) Limited for roof and HVAC","numbers":"Rehab $32,000; price $410,000","why":"Gets safety and comfort items done immediately","alternatives":"Seller repair credit (limited); FHA repair escrow","watch":"Appraiser must confirm roof life after work; insurance carriers often require newer roofs"},{"t":"Accessibility for aging parent","who":"Grace, 47, Navy veteran and admin officer, Oceanside","situation":"Her father is moving in and needs grab bars, a walk-in shower and a ramp. She's keeping her VA entitlement for a future PCS-related purchase. Score 690.","structure":"203(k) Limited accessibility scope","numbers":"Rehab $28,000","why":"Accessibility work is eligible","alternatives":"VA purchase with separate improvements","watch":"Ramp may need permit; keep scope non-structural"},{"t":"Energy upgrades in Las Vegas","who":"Darnell, 36, casino security supervisor, North Las Vegas NV","situation":"The house has single-pane windows and old ducts. Summer bills were $450 in the prior owner's history. He wants to fix at purchase.","structure":"203(k) Limited windows, duct sealing, heat pump","numbers":"Rehab $26,000","why":"Lower bills and better appraisal","alternatives":"FHA EEM (smaller amounts)","watch":"Choose items that appraise; EEM may stack in some cases (verify)"},{"t":"Paint and lead remediation","who":"Hannah, 29, teacher, National City","situation":"A 1955 home with peeling paint fails FHA standards as-is. She loves the location. She has 3.5% down only.","structure":"203(k) Limited covering lead-safe paint stabilization and repairs","numbers":"Rehab $18,000","why":"Cures MPS deficiencies through the loan","alternatives":"Seller cures (seller refused)","watch":"Lead-safe certified contractor required (EPA RRP)"}],"qa":[{"q":"How much can I finance in repairs?","a":"Up to $75,000 total rehab costs under current HUD rules (verify)."},{"q":"Is a consultant required?","a":"No, though some lenders still require one for larger scopes."},{"q":"Can I move walls?","a":"Not load-bearing; structural work requires Standard 203(k)."},{"q":"Can I live in the house during work?","a":"Yes; Limited requires the home be habitable."},{"q":"Can I do the work myself?","a":"Generally no; licensed contractors."},{"q":"Can I finance a new roof?","a":"Yes, roof replacement is eligible."},{"q":"How long does the work take?","a":"Usually must finish within 6 months; lenders may require faster."},{"q":"What if bids come in over $75,000?","a":"Move to Standard 203(k) or reduce scope."},{"q":"Is MIP charged on repair dollars?","a":"Yes, on the total loan."}],"aeQuestions":["Is your Limited cap $75,000 including contingency and fees?","Do you require a consultant above a threshold?","How many draws and upfront materials deposit?","Contractor approval process?","Min FICO for Limited?","Do you allow 2-4 units?","Final inspection by whom?","Can permits be outstanding at closing?","Required contingency percent?"],"redFlags":["Scope includes structural changes","Bid lacks line items","Contractor wants full payment upfront","Home not habitable at closing","Total costs exceed cap after fees","Pre-1978 paint work without RRP-certified contractor","Appraisal ARV doesn't support scope"],"pricing":"Limited 203(k) usually prices slightly above standard FHA and may include a supplemental origination fee and inspection/draw fees. MIP applies to the total including rehab. Compare cost of financing repairs against seller credits and personal loans over the expected hold period. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Listing agent outreach on dated homes sitting on market","Contractor education sessions","Content: 'make an older home FHA-ready'","First-time buyers who lose bidding wars on turnkey homes","Accessibility remodel partners"],"checklist":["Contractor bid with line items","Contractor license, insurance, W-9","Rehab cost worksheet","Max mortgage worksheet","Subject-to appraisal","Homeowner/contractor agreement","Rehabilitation loan agreement","Draw request forms","Final inspection","Lien releases","Income and asset docs","LPR or citizenship confirmation"],"updated":"2026-11"},
"a_fha_streamline":{"matrix":[["Min FICO","No HUD minimum for non-credit-qualifying; lenders commonly overlay 580-640 and pull credit for payment history (lender-specific)"],["Max LTV","No appraisal required; new base loan = unpaid principal + interest + MIP due - UFMIP refund + new UFMIP (cannot add closing costs except via premium pricing)"],["Loan limits","Can exceed current county limit only if the original loan did; generally capped at existing balance math"],["Credit qualifying","Non-credit-qualifying allowed unless removing a borrower in certain cases or payment increases 20%+"],["Seasoning","At least 210 days from closing of current loan, 6 payments made, and first payment due at least 210 days ago"],["Net tangible benefit","Fixed to fixed: combined rate (note + annual MIP) drops by at least 0.5%; other paths per HUD table (ARM to fixed, term reduction)"],["Payment history","0x30 in last 3 months and no more than 1x30 in prior 9 months (verify HUD 4000.1)"],["MIP","New 1.75% UFMIP minus refund (refund declines over 36 months); annual 0.55% for most; loans endorsed before June 1, 2009 get 0.01% UFMIP and 0.55% annual (verify)"],["Occupancy","Owner-occupied or investment allowed without appraisal (investment needs no-appraisal path; verify)"],["Cash","Maximum $500 cash back"],["Residency","Non-permanent residents with existing FHA loans cannot streamline after May 25, 2025 (ML 2025-09)"],["States","All licensed states"]],"walkthrough":["Confirm existing loan is FHA and get the case number","Verify seasoning dates and payment history","Pull UFMIP refund from FHA Connection based on months since endorsement","Calculate new base loan and new UFMIP","Run combined-rate NTB test","Decide credit-qualifying vs non-credit-qualifying","Disclose; no appraisal","Lock with lender credit to cover costs if wanted","Order title and payoff","Close; rescission if primary and not same lender (verify)","Confirm MIP adjusted on new loan","Set review reminder"],"incomeExample":{"title":"FHA streamline NTB and UFMIP refund, Spring Valley","steps":["Current base $430,000, note rate R + annual MIP 0.55%; combined = R + 0.55","Proposed note rate 0.75 point lower, annual MIP still 0.55%; combined drop 0.75 (meets 0.5 minimum)","Original UFMIP paid $7,700; 14 months since endorsement; refund factor (verify HUD chart) about 58% = $4,466","New UFMIP 1.75% x $430,000 = $7,525; net new UFMIP = $7,525 - $4,466 = $3,059","Base loan stays $430,000 (payoff); net UFMIP $3,059 is added, so total loan = $433,059","Monthly P&I savings illustrative $210"],"result":"Passes the 0.5 combined-rate test; refund makes the new UFMIP only about $3,000."},"scenarios":[{"t":"2024 FHA buyer stepping down","who":"Maria, 32, medical assistant, Vista","situation":"Maria bought in 2024 with FHA at a higher rate than today's market. She has made 18 on-time payments and her score is unchanged. She wants a smaller payment without paying for an appraisal or re-documenting income.","structure":"FHA streamline, non-credit-qualifying, lender credit covering closing costs","numbers":"Base $455,000; combined rate drops 0.75; P&I falls about $220/month (illustrative); UFMIP refund offsets part of new UFMIP","why":"No appraisal or income docs, and refund lowers the new upfront premium","alternatives":"Conventional rate/term (needs equity and appraisal to drop MI); wait for a larger drop","watch":"Last 3 months must be 0x30; closing costs can't be added to the loan"},{"t":"Grandfathered pre-June 2009 endorsement","who":"Earl, 66, retired postal worker, Escondido","situation":"Earl's FHA loan was endorsed in 2007 and has about $180,000 left. He is on a fixed pension and wants the lowest payment possible. He does not need cash.","structure":"FHA streamline using the reduced premium for loans endorsed before June 1, 2009 (verify current schedule)","numbers":"UFMIP 0.01% and annual MIP per grandfathered schedule; P&I savings depend on rate","why":"Lower upfront premium makes the streamline nearly cost-free","alternatives":"HECM reverse mortgage (eliminates payment but uses equity)","watch":"Confirm endorsement date in FHA Connection"},{"t":"Removing an ex-spouse","who":"Tasha, 38, bank teller, Moreno Valley","situation":"Tasha's divorce decree awarded her the home, but her ex-husband is still on the FHA loan. She has paid the mortgage alone for 12 months from her own account. She wants him released and a lower rate.","structure":"Credit-qualifying FHA streamline removing the ex-spouse","numbers":"Base $362,000; Tasha qualifies alone at 44% DTI","why":"Releases the ex without an appraisal","alternatives":"Conventional refinance (needs equity and higher credit); assumption with release","watch":"Evidence she made the last 6 payments alone; decree and quitclaim"},{"t":"Former home now a rental","who":"Omar, 44, Marine veteran and project manager, Murrieta","situation":"Omar took a job in Irvine and kept his Murrieta FHA home as a rental. Rent covers PITI with little margin. He wants a lower payment but can't use VA IRRRL because the loan is FHA.","structure":"FHA streamline on non-owner-occupied property without appraisal","numbers":"Base $398,000 (no closing costs financed); payment drops about $190 (illustrative)","why":"Only streamline path allowed for investment FHA loans is no-appraisal","alternatives":"DSCR refinance (higher pricing); conventional investment refi","watch":"Investment streamlines cannot include costs in loan and may face lender overlays"},{"t":"Non-permanent resident blocked","who":"Mei, 35, biomedical engineer on H-1B, San Diego","situation":"Mei bought with FHA in 2023 when non-permanent residents were eligible. She assumed a streamline would be simple. Her status has not changed to permanent residency.","structure":"Not eligible for FHA streamline under ML 2025-09; conventional rate/term refinance instead","numbers":"Conventional at 85% LTV with MI; appraisal required","why":"Fannie and Freddie still accept lawful non-permanent residents with valid work authorization","alternatives":"Wait for green card and revisit FHA","watch":"Work authorization expiration dates; MI cost vs current MIP"}],"qa":[{"q":"Do I need an appraisal?","a":"No, the standard FHA streamline is a no-appraisal refinance."},{"q":"Can I take cash out?","a":"No, cash back is limited to $500."},{"q":"How soon can I streamline?","a":"After 210 days from closing, with 6 payments made."},{"q":"Do I get any MIP refund?","a":"Yes, a partial UFMIP refund if refinancing within 3 years of endorsement, applied to the new UFMIP."},{"q":"Will the streamline remove my MIP?","a":"No; refinancing to conventional with enough equity removes it."},{"q":"Can closing costs be rolled in?","a":"Not into the loan; use lender credit or pay them."},{"q":"Will my credit be pulled?","a":"Usually, for payment history; full qualifying only in certain cases."},{"q":"Can I streamline a rental?","a":"Yes, without an appraisal and without financing costs."},{"q":"Can I remove a borrower?","a":"Sometimes, with credit qualifying and proof the remaining borrower made recent payments."},{"q":"I'm a non-permanent resident; can I streamline?","a":"Not after May 25, 2025; consider conventional."}],"aeQuestions":["Minimum FICO for non-credit-qualifying streamline?","Do you offer investment-property streamlines?","Do you ever require an appraisal on streamlines?","How much lender credit is available to cover costs?","Borrower removal policy?","Payment history overlay beyond HUD?","How do you pull the UFMIP refund?","Turn time application to funding?","Will you streamline a loan endorsed before June 2009 at reduced MIP?"],"redFlags":["Fewer than 6 payments or under 210 days","A 30-day late in the last 3 months","Combined rate reduction under 0.5","Borrower is a non-permanent resident","Borrower expects cash out","Costs being disguised as financed items","Solicitation promising skipped payments as savings"],"pricing":"Streamlines often price close to FHA purchase pricing, but because closing costs cannot be financed, the lender credit available at each rate is the key comparison. The UFMIP refund lowers the effective new premium when refinancing within 3 years. Annual MIP stays on the new loan, so compare against a conventional refinance once equity reaches about 20%. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Annual review letters to past FHA clients","Agent partners' past-client lists (with consent)","Education on UFMIP refunds and 210-day timing","Content comparing streamline vs conventional refi to drop MIP","Credit union and employer financial wellness talks"],"checklist":["Current mortgage statement","FHA case number","12-month payment history","UFMIP refund printout","Net tangible benefit worksheet","Title report","Payoff letter","Homeowners insurance","Government ID","Citizenship or LPR documentation","Lease (if investment)","Divorce decree (if removing borrower)"],"updated":"2026-11"},
"a_fha_cashout":{"matrix":[["Min FICO","HUD 500 technically with 80% LTV, but most lenders overlay 580-640 for cash-out (lender-specific)"],["Max LTV","80% of appraised value; no CLTV allowance above that for new subordinate financing"],["Loan limits","County FHA limit (2026 floor $541,287; verify county)"],["DTI/AUS","TOTAL Accept; manual UW limits 31/43 to 40/50 with compensating factors"],["MIP","UFMIP 1.75%; annual 0.50% at LTV 95% or less (base up to $726,200), MIP for 11 years when LTV 90% or less"],["Ownership seasoning","Owner-occupied as primary residence for previous 12 months"],["Payment history","All mortgage payments in the prior 12 months on time (0x30), or since origination if less than 12 months is impossible (needs 6 months ownership; verify)"],["Reserves","None for 1-2 units on Accept; 3 months for 3-4 units"],["Property types","1-4 unit owner-occupied; condos must be FHA approved or single-unit eligible"],["Free-and-clear","Allowed; cash-out on a property owned free and clear for 12 months"],["Rescission","3-day right of rescission for primary residence"],["Residency","Citizens and lawful permanent residents only after May 25, 2025"],["States","All licensed states; CA high appraisal volatility in some markets"]],"walkthrough":["Confirm 12 months owner occupancy and 12 months on-time payments","Estimate value and 80% LTV ceiling; verify FHA county limit","Compare cash-out vs conventional cash-out vs HELOC on total cost","Pull credit and run TOTAL","Order FHA appraisal","Calculate payoff of liens and debts at closing","Disclose MIP impact (new 1.75% UFMIP, annual 0.50%)","Underwrite; collect LOEs for derogatory items","Lock","Sign with 3-day rescission","Fund and disburse; pay off creditors directly where required","Calendar a 12-month review to refinance into conventional when equity and credit improve"],"incomeExample":{"title":"FHA cash-out at 80% LTV, Moreno Valley","steps":["Appraised value $560,000; max base loan 80% = $448,000","Existing first mortgage $290,000; credit cards $24,000; auto $18,000","Closing costs about $8,500","Cash available = $448,000 - $290,000 - $8,500 = $149,500; pay off $42,000 debts leaves $107,500","UFMIP 1.75% x $448,000 = $7,840 added; total loan $455,840","Annual MIP 0.50% x $448,000 / 12 = $187/month for 11 years (LTV 90% or less)","Payments removed: cards $720 + auto $510 = $1,230; mortgage payment rises illustrative $1,050 including MIP","Net monthly cash flow +$180 plus $107,500 liquidity"],"result":"Cash-out works when credit blocks conventional pricing; MIP for 11 years must be weighed against conventional cash-out with no MI at 80%."},"scenarios":[{"t":"Credit too low for conventional cash-out","who":"Rosa, 46, school bus driver, Moreno Valley","situation":"Rosa's score fell to 615 after a divorce, and conventional cash-out pricing at 615 is very expensive. She has $270,000 of equity and $42,000 in card and auto debt. She needs relief now and wants to keep her house.","structure":"FHA cash-out at 80% LTV paying debts at closing","numbers":"Value $560,000; base loan $448,000; MIP $187/month","why":"FHA's credit pricing is gentler than conventional LLPAs at 615","alternatives":"HELOC (likely declined at her score); conventional cash-out (heavy LLPAs)","watch":"Do not reload the cards; revisit conventional once score passes 680"},{"t":"Veteran without VA eligibility on this home","who":"Darius, 52, Army veteran and corrections officer, Victorville","situation":"Darius used his VA benefit on a home he lost in 2012 and VA paid a claim he never repaid. His current home has an FHA loan. He needs $60,000 for his daughter's tuition.","structure":"FHA cash-out","numbers":"Value $420,000; max $336,000; existing $250,000; cash about $78,000 before costs","why":"Works while VA entitlement is blocked by the old claim debt","alternatives":"VA cash-out after repaying the claim; HELOC","watch":"12 months of on-time payments required; tuition alternatives like federal loans may be cheaper"},{"t":"Free-and-clear home","who":"Helen, 69, retired nurse, El Cajon","situation":"Helen owns her home outright and wants to fund a roof and help her grandson. She has pension and Social Security income. She doesn't want a reverse mortgage.","structure":"FHA cash-out on a free-and-clear property","numbers":"Value $650,000 (check county limit); borrow $150,000","why":"Fixed payment she can afford with steady income","alternatives":"HECM (no payment), HELOC (variable)","watch":"Age-related income continuance: pension and SS are fine; investment withdrawals need 3 years continuance"},{"t":"Buyout of family member","who":"Ernesto, 40, landscaper, Escondido","situation":"Ernesto and his brother inherited their mother's house. Ernesto wants to buy his brother's half. He has lived there for 3 years.","structure":"FHA cash-out (or rate/term buyout where allowed; verify)","numbers":"Value $700,000; buyout $280,000 plus existing $60,000","why":"Keeps family home","alternatives":"Conventional cash-out","watch":"Title vesting and occupancy history; self-employed income averaging"},{"t":"Medical debt and a duplex","who":"Jamal, 39, Navy veteran and port worker, National City","situation":"Jamal lives in one unit of a duplex and rents the other. Medical bills after a surgery pushed card balances up. His score is 630.","structure":"FHA 2-unit cash-out at 80%","numbers":"Value $900,000 (verify 2-unit limit); new loan $720,000","why":"Uses rental income to qualify","alternatives":"VA cash-out (he has entitlement; could compare)","watch":"Compare VA cash-out first, since it avoids MIP and may allow higher LTV"}],"qa":[{"q":"How much can I take out?","a":"Up to 80% of appraised value minus existing liens and costs."},{"q":"How long must I have lived there?","a":"12 months as your primary residence."},{"q":"Do I need perfect payment history?","a":"Generally no 30-day lates on the mortgage in the last 12 months."},{"q":"Is there mortgage insurance?","a":"Yes: 1.75% upfront and annual MIP for 11 years at 80% LTV."},{"q":"Is FHA better than conventional for cash-out?","a":"Often only when credit is under about 680 or DTI is high."},{"q":"Can I cash out a rental?","a":"No, FHA cash-out is owner-occupied only."},{"q":"Can I cancel after signing?","a":"Yes, the 3-day right of rescission applies."},{"q":"What can I use the cash for?","a":"Any lawful purpose; payoff of debts can be required to qualify."},{"q":"Can I do it if my home is paid off?","a":"Yes."}],"aeQuestions":["Minimum FICO for FHA cash-out?","Do you overlay below 80% LTV?","Do you require debts paid at closing to qualify?","Manual UW allowed on cash-out?","2-4 unit cash-out policy and reserves?","Turn time for appraisal and endorsement?","Non-occupant co-borrower allowed on cash-out?","How do you treat recent late payments on non-mortgage debt?"],"redFlags":["Fewer than 12 months owner occupancy","Any 30-day mortgage late in last 12 months","Borrower is a non-permanent resident","Cash used to cover an unsustainable budget gap","VA cash-out would be cheaper but not considered","Appraisal value inflated by recent unpermitted additions","Property listed for sale recently"],"pricing":"FHA cash-out pricing usually carries a modest add-on versus rate/term, but the real cost is 1.75% UFMIP plus 11 years of annual MIP. For borrowers above about 680, a conventional cash-out at 80% (no MI) or a HELOC often costs less overall. For veterans, a VA cash-out can beat both. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Debt-consolidation education with nonprofit credit counselors","Past FHA buyers who now have equity","Content: FHA vs conventional vs VA vs HELOC for cash-out","Divorce mediator and family law attorney education","Senior homeowner workshops on cash-out vs reverse mortgage"],"checklist":["12-month mortgage payment history","Proof of 12 months occupancy","FHA appraisal","Payoff statements for all liens","Debt payoff list and creditor addresses","Income documentation","Asset statements","Rescission notice","LPR or citizenship documentation","Homeowners insurance","Title report","Letters of explanation"],"updated":"2026-11"},
"a_fha_eem":{"matrix":[["Min FICO","Follows underlying FHA loan: 580 for 96.5%; overlays 600-640 (lender-specific)"],["Max EEM amount","Lesser of the cost of improvements or 5% of the lowest of: (a) property value, (b) 115% of area median price for a 1-unit home, or (c) 150% of the national conforming limit (verify HUD formula)"],["LTV","EEM amount added to the base loan after LTV calculation; can push total above county limit (EEM is not counted toward the limit; verify)"],["Loan limits","Base loan must fit 2026 county FHA limit (floor $541,287); EEM may be added on top"],["Energy assessment","Required: home energy assessment or HERS rating identifying cost-effective improvements; savings over useful life must exceed cost"],["Qualifying","EEM funds not included when qualifying; projected savings not added to income"],["MIP","UFMIP and annual MIP apply to the total loan including EEM"],["Escrow","Funds held in escrow and released after completion, typically within 90 days (lender-specific)"],["Eligible items","Insulation, HVAC, heat pumps, windows, solar PV (owned), water heaters, duct sealing; leased solar ineligible"],["Transactions","Purchase, rate/term refinance, streamline (with limits; verify), combined with 203(k) in some cases"],["Property types","1-2 unit existing and new construction (verify for new builds)"],["Residency","Citizens and lawful permanent residents only (ML 2025-09)"],["States","All licensed states; strongest use in Inland Empire, desert NV/AZ and older CA housing"]],"walkthrough":["Confirm the lender funds FHA EEM; many do not","Order an energy assessment by a qualified assessor (HERS rater)","Identify improvements with savings over useful life greater than cost","Compute the EEM cap with HUD's formula","Add EEM to the base mortgage after LTV is determined","Disclose UFMIP and MIP on the EEM portion","Underwrite on the base loan","Close with EEM funds in escrow","Contractor completes work","Assessor or inspector confirms completion","Release escrow; lien releases","Keep receipts for any available energy tax incentives (verify; several federal credits ended after 2025)"],"incomeExample":{"title":"FHA EEM cap calculation, Riverside County purchase","steps":["Value $500,000; 115% of area median price (illustrative) $620,000; 150% of national conforming limit = 1.5 x $832,750 = $1,249,125","Lowest of the three = $500,000; 5% = $25,000 cap","Assessment-recommended package: heat pump $11,000, attic insulation $3,200, duct sealing $1,800 = $16,000","EEM = lesser of $16,000 and $25,000 = $16,000","Base loan (96.5% of $500,000) = $482,500 + EEM $16,000 = $498,500; UFMIP 1.75% = $8,724; total $507,224","Added P&I on $16,000 at an illustrative payment factor of 0.0065 = $104/month; projected savings $120/month"],"result":"EEM of $16,000 fits the 5% cap and pays for itself monthly per the assessment."},"scenarios":[{"t":"Inland Empire cooling costs","who":"Andrea, 34, preschool teacher, Perris","situation":"Andrea is buying a 1989 home with an inefficient AC and thin attic insulation. The seller's summer bills averaged $380/month. She has only her 3.5% down and can't fund upgrades later.","structure":"FHA purchase plus $16,000 EEM","numbers":"Base $482,500 + EEM $16,000; added P&I about $104 vs projected savings $120","why":"Upgrades financed at mortgage cost without affecting qualifying","alternatives":"Seller credit (capped at 6%); utility rebate programs","watch":"Escrow release requires completion and assessor sign-off"},{"t":"Owned solar on an older home","who":"Marcus, 41, Navy veteran and electrician, Lake Elsinore","situation":"Marcus is using FHA because his VA entitlement is tied up in a rental. He wants owned solar sized to his EV charging. The energy assessment shows the system is cost-effective even under NEM 3.0 export rates.","structure":"FHA purchase plus EEM for owned PV and battery (verify battery eligibility)","numbers":"EEM capped at 5% of value: $24,000 on a $480,000 home","why":"Ownership adds value and avoids a 20-year lease","alternatives":"Solar loan with UCC filing; lease/PPA","watch":"Battery eligibility and realistic savings estimate"},{"t":"Streamline plus windows","who":"Patricia, 59, hospital administrator, Las Vegas NV","situation":"Patricia is doing an FHA streamline and her single-pane windows leak. She wants to add replacements without cash. Her lender allows EEM on streamlines (verify).","structure":"FHA streamline with EEM","numbers":"Windows $9,500","why":"Combines rate reduction and efficiency upgrade","alternatives":"Pay cash","watch":"Lender support for EEM on streamline is rare"},{"t":"Desert home with swamp cooler","who":"Ruben, 37, Marine veteran and corrections officer, Yucca Valley","situation":"Ruben's purchase has a swamp cooler and wall heaters. Summer and winter extremes make a heat pump valuable. He's using FHA due to a 600 score.","structure":"FHA purchase plus EEM for ducted heat pump","numbers":"EEM $14,000","why":"Comfort and energy savings in extreme climate","alternatives":"VA EEM (limited to $6,000 easily)","watch":"Ductwork installation scope; electrical panel upgrade cost"},{"t":"Duplex with two old water heaters","who":"Linda, 45, nurse, Phoenix AZ","situation":"Linda is buying a duplex and both units have aging water heaters and poor insulation. She will live in one unit. Energy assessment shows strong savings.","structure":"FHA 2-unit purchase plus EEM","numbers":"EEM $9,800","why":"Improves rental unit too","alternatives":"Conventional with personal financing","watch":"2-unit EEM cap uses same formula; landlord utility arrangements"}],"qa":[{"q":"How much can EEM add?","a":"The lesser of improvement costs or 5% of the lowest of value, 115% of area median price, or 150% of the national conforming limit."},{"q":"Do I have to qualify for the EEM amount?","a":"No, qualifying is on the base loan."},{"q":"Is an energy assessment required?","a":"Yes, to show improvements are cost-effective."},{"q":"Does MIP apply to the EEM?","a":"Yes, both UFMIP and annual MIP."},{"q":"Can EEM pay for leased solar?","a":"No, only owned improvements."},{"q":"Can I use EEM with a 203(k)?","a":"Often yes; lender-specific."},{"q":"Can I use EEM on new construction?","a":"Sometimes, for improvements beyond code (verify)."},{"q":"How fast must the work be done?","a":"Typically within 90 days; lender-specific."}],"aeQuestions":["Do you fund FHA EEM?","Which assessors do you accept (HERS raters)?","Escrow release timing and process?","EEM on streamlines?","EEM combined with 203(k)?","Battery storage eligible?","Does EEM count toward county limit in your system?","Draw/inspection fees?"],"redFlags":["Lender doesn't actually offer EEM","Energy assessment missing or out of date","Leased solar presented as owned","Savings estimate unrealistic","Contractor wants full payment upfront","Work needed for MPS treated as EEM"],"pricing":"EEM generally doesn't change base pricing but adds UFMIP and MIP on the extra principal, plus assessment and escrow inspection fees. Compare the added monthly payment against projected savings and against seller credits. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Inland Empire and desert climate content","HERS rater education partnerships","Solar installer education on owned systems","First-time buyer workshops covering energy costs","Veteran buyers with tied-up VA entitlement"],"checklist":["Energy assessment / HERS report","Contractor bids","EEM cap worksheet","Escrow agreement","Completion certification","Lien releases","Base FHA loan file","UFMIP calc including EEM","Insurance","LPR or citizenship docs"],"updated":"2026-11"},
"a_fha_mfg":{"matrix":[["Min FICO","Title II follows FHA (580 for 96.5%); manufactured overlays 620-660 common (lender-specific); Title I lenders few and often 620+"],["Max LTV","Title II: 96.5% purchase; Title I: up to 90-95% depending on home only vs home and lot (verify)"],["Loan limits","Title II: county FHA limit (2026 floor $541,287). Title I: statutory limits indexed annually, roughly $69,678 home only, $23,226 lot, $92,904 home and lot under older figures (verify current)"],["Construction date","Built after June 15, 1976 to HUD Code with HUD certification labels (data plate and tags)"],["Foundation","Title II: permanent foundation per HUD Permanent Foundations Guide (PFGMH) with engineer certification"],["Real property","Title II requires home and land classified as real property, chassis permanently attached, title surrendered (CA: HCD 433A recorded; verify)"],["Size","At least 400 sq ft of gross living area"],["Moved homes","Title II generally ineligible if the home was moved from its original installation site"],["Term","Title II 30-year; Title I up to 20 years home only, 25 for lot and home (verify)"],["MIP","Title II: standard UFMIP 1.75% and annual MIP; Title I: separate insurance premium structure (verify)"],["Occupancy","Primary residence"],["Land lease","Title I may finance homes in qualifying parks with long-term leases; Title II needs land ownership or acceptable leasehold"],["Residency","Citizens and LPRs only after May 25, 2025 for Title I and II"],["States","CA (HCD), NV, AZ, FL have strong manufactured markets; IL less common"]],"walkthrough":["Identify Title I (chattel-like, park/lot) vs Title II (real property) path","Verify HUD tags and data plate exist or order IBTS label verification letter","Confirm build date after June 15, 1976","Check whether the home was ever moved","Engineer inspection and foundation certification (PFGMH)","Confirm real property conversion (CA HCD 433A) and title surrender","Run credit and AUS","Order appraisal with manufactured comps","Clear title: no chattel liens outstanding","Close; record foundation cert and affidavit of affixation","Fund","Ensure insurance written as real property dwelling"],"incomeExample":{"title":"Title II manufactured purchase with foundation cert, Hemet","steps":["Price $340,000 for 2002 double-wide on owned 0.25-acre lot","Down 3.5% = $11,900; base loan $328,100","UFMIP 1.75% = $5,742; total loan $333,842","Annual MIP 0.55% x $328,100 / 12 = $150/month","Illustrative P&I $2,150 + taxes $354 + insurance $110 + MIP $150 = $2,764","Borrower income $6,400; debts $300; DTI = $3,064 / $6,400 = 47.9% (AUS Accept needed)","Foundation engineer certification $650; tag verification $200 (if needed)"],"result":"Qualifies with TOTAL Accept; engineer cert and real property conversion must be in file."},"scenarios":[{"t":"Double-wide on owned land","who":"Teresa, 44, CNA, Hemet","situation":"Teresa found a 2002 double-wide on a quarter-acre lot that is already converted to real property. Her score is 640 and she has $15,000 saved. Site-built homes nearby cost $150,000 more.","structure":"FHA Title II purchase with foundation certification","numbers":"Price $340,000; base loan $328,100; MIP $150/month","why":"Lowest-cost path to owning land and home together","alternatives":"Conventional MH (Fannie standard MH) needs better credit; chattel loan more expensive","watch":"Must confirm HUD tags and that the home was never moved"},{"t":"Retiree in a 55+ park","who":"Gene, 71, retired Navy Chief, Lake Elsinore","situation":"Gene wants a newer manufactured home in a 55+ park on leased land. He has pension and VA compensation. Chattel lenders quoted high costs.","structure":"FHA Title I home-only loan (if a Title I lender available; verify)","numbers":"Home $85,000; Title I limit may cap loan (verify)","why":"Insured financing alternative to chattel","alternatives":"CalVet mobile home loan; cash","watch":"Park lease must meet Title I term requirements; few active Title I lenders"},{"t":"Missing HUD tags","who":"Lori, 50, cashier, Desert Hot Springs","situation":"The home's HUD tags were painted over and the seller can't find them. Lori has a 600 score and FHA is her only option. The data plate inside the kitchen cabinet survived.","structure":"FHA Title II with IBTS label verification letter","numbers":"Price $260,000","why":"Verification letter cures missing tags","alternatives":"Cash buyer (seller's alternative)","watch":"Allow 2-4 weeks for IBTS letter"},{"t":"Converting a chattel home to real property","who":"Ramon, 38, mechanic, Apple Valley","situation":"Ramon bought a manufactured home and lot years ago with a chattel loan. He wants to refinance into FHA to lower the rate and convert to real property. The home sits on piers, not a permanent foundation.","structure":"FHA Title II rate/term after foundation upgrade","numbers":"Foundation retrofit $9,000; refinance $210,000","why":"Real property status improves value and financing options","alternatives":"Keep chattel loan","watch":"Foundation work must be complete and certified before closing"},{"t":"Arizona veteran buyer with FHA","who":"Cheryl, 47, Air Force veteran and dispatcher, Kingman AZ","situation":"Cheryl's VA entitlement is tied up in a Las Vegas home she rents out. She wants a manufactured home on 1 acre near family. She has 3.5% down.","structure":"FHA Title II purchase","numbers":"Price $265,000","why":"Keeps VA entitlement tied to rental","alternatives":"VA second-tier (could compare)","watch":"Well and septic inspection; acreage comparables"}],"qa":[{"q":"What is the difference between Title I and Title II?","a":"Title II is a mortgage on a home and land as real property; Title I can finance a home alone or a lot, often in parks."},{"q":"Does the home have to be built after 1976?","a":"Yes, after June 15, 1976 to HUD Code."},{"q":"What if the HUD tags are missing?","a":"Order a label verification letter from IBTS."},{"q":"Does it need a permanent foundation?","a":"Yes for Title II, certified by an engineer."},{"q":"Can the home have been moved?","a":"Generally no for Title II."},{"q":"Is there a minimum size?","a":"400 sq ft."},{"q":"Can I buy in a mobile home park?","a":"Title I may work; Title II generally requires land ownership or approved leasehold."},{"q":"Is MIP the same as a site-built FHA loan?","a":"For Title II, yes."},{"q":"Are many lenders doing Title I?","a":"Few; check availability."}],"aeQuestions":["Do you lend on Title II manufactured homes?","Minimum FICO for manufactured?","Do you offer Title I?","Single-wide allowed?","Max acreage?","Engineer cert requirements?","Do you accept IBTS letters?","CA real property conversion documentation required?","Age-of-home overlay?"],"redFlags":["Home built before June 15, 1976","Home was moved from original site","HUD tags missing without IBTS letter","Not converted to real property","Foundation not certified","Open chattel lien","Additions without permits"],"pricing":"Title II manufactured loans often carry a pricing adjustment or overlay compared with site-built FHA. Title I is rare and priced individually. Compare against Fannie MH Advantage or standard MH if credit and down payment allow. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Manufactured home communities with owned lots","MH retailers and dealers (education; no referral fees)","Rural Inland Empire and high desert outreach","Retiree and veteran MH buyers","Content on real property conversion in CA"],"checklist":["HUD data plate and tags or IBTS letter","Foundation engineer certification","Real property conversion docs (HCD 433A in CA)","Title showing no chattel lien","Appraisal with MH comparables","Well/septic reports if applicable","Credit and income docs","Assets","Insurance as real property","LPR/citizenship docs"],"updated":"2026-11"},
"a_fha_gnnd":{"matrix":[["Eligibility","Full-time law enforcement officers, pre-K-12 teachers, firefighters and EMTs serving the community where the home is located"],["Discount","50% off HUD's list price; discount secured by a silent second mortgage and note to HUD"],["Occupancy","Must live in the home as sole residence for 36 months; annual occupancy certifications"],["Properties","HUD-owned single-family homes (REO) in designated revitalization areas listed on HUDHomestore for the GNND program, typically 7-day listing"],["Selection","Random lottery when multiple eligible bids are submitted"],["Financing","FHA with $100 down for eligible GNND buyers; also conventional, VA or cash"],["Min FICO","FHA rules with lender overlays 580-640 (lender-specific)"],["Loan amount","Based on full sales price (the discounted price), with FHA 203(b) or 203(k) for repairs"],["Prior ownership","Cannot have owned a home in the prior 12 months at time of bid submission"],["MIP","Standard FHA UFMIP and annual MIP on loan amount"],["Repairs","HUD homes are as-is; FHA 203(k) commonly paired for repairs"],["Residency","FHA path requires citizen or LPR after May 25, 2025"],["Availability","Inventory is thin and sporadic; Southern California listings are rare (verify current HUDHomestore)"],["States","Program is national; usable in CA, IL, NV, FL, AZ when listings exist"]],"walkthrough":["Confirm occupation eligibility and service area match","Confirm no homeownership in last 12 months","Set alerts on HUDHomestore for GNND listings in target areas","Pre-approve with FHA (or 203(k) if repairs needed)","Partner with a HUD-registered selling broker to submit the bid","Bid at full list price during the 7-day GNND window","Await lottery result","Sign HUD second mortgage and note for discount","Order FHA appraisal; review as-is condition","Close within HUD's deadline","Move in within 30 days and certify occupancy annually for 36 months","Track annual certifications to avoid repayment demand"],"incomeExample":{"title":"GNND discount and second mortgage math","steps":["HUD list price $380,000; GNND buyer pays 50% = $190,000","Silent second to HUD for discount = $190,000; forgiven after 36 months occupancy","FHA loan on $190,000 with $100 down: base loan $189,900; UFMIP 1.75% = $3,323; total $193,223","Annual MIP 0.55% x $189,900 / 12 = $87/month","Illustrative P&I $1,230 + taxes (on assessed value, verify) $400 + insurance $120 + MIP $87 = $1,837","Teacher income $6,000; DTI = $1,837 / $6,000 = 30.6%"],"result":"Payment is roughly half what a full-price purchase would require, provided the 36-month occupancy is met."},"scenarios":[{"t":"Teacher winning a lottery bid","who":"Sophia, 29, 4th-grade teacher, Victorville","situation":"Sophia teaches in the Victor Elementary district and watches HUDHomestore weekly. A GNND home appeared in a revitalization area near her school. She has $3,000 saved and a 660 score.","structure":"GNND bid at list price, FHA with $100 down","numbers":"List $340,000; price $170,000; FHA base loan $169,900","why":"Halves the purchase price and payment","alternatives":"FHA standard purchase at full price","watch":"Must live there 36 months; repairs as-is"},{"t":"Firefighter with repair needs","who":"Derek, 35, municipal firefighter, Barstow","situation":"The HUD home needs a roof and flooring. Derek wants to finance repairs too. He works for the city fire department serving the area.","structure":"GNND with FHA 203(k) Limited","numbers":"Price $160,000; rehab $30,000","why":"Discount plus repair financing","alternatives":"Cash repairs later","watch":"Lender must handle both 203(k) and GNND"},{"t":"Police officer in Phoenix","who":"Angela, 41, police officer, Phoenix AZ","situation":"Angela's department serves the revitalization area where a HUD home is listed. She owned a condo until 2024 but sold it 14 months ago. She qualifies on the 12-month rule.","structure":"GNND FHA purchase","numbers":"List $300,000; price $150,000","why":"Large discount","alternatives":"Conventional","watch":"Prior ownership date proof"},{"t":"EMT using VA instead","who":"Jose, 32, Marine veteran and EMT, Las Vegas NV","situation":"Jose wants zero down with no MIP. He's eligible as an EMT and a veteran. The HUD home is in a revitalization area.","structure":"GNND with VA financing","numbers":"Price $175,000 after discount","why":"Zero down and no MIP","alternatives":"FHA with $100 down","watch":"VA appraisal MPRs on an as-is HUD home"},{"t":"Moving out before 36 months","who":"Karen, 38, high school teacher, Riverside","situation":"Karen won a GNND home in 2024 and has lived there 26 months. She received a job offer in Oregon starting in 2026. She asks what happens to the 50% discount if she moves now.","structure":"Review HUD second mortgage terms: discount is reduced over the occupancy period and the unearned portion is repayable on early sale or move (verify formula)","numbers":"Discount $160,000; 10 months remaining; repayment estimated on unearned share (illustrative)","why":"Avoids a surprise repayment demand at sale","alternatives":"Delay the move until 36 months; rent elsewhere temporarily is not allowed","watch":"Failing occupancy certification can trigger repayment and potential fraud review"}],"qa":[{"q":"Who qualifies for GNND?","a":"Full-time law enforcement, pre-K-12 teachers, firefighters and EMTs serving the community."},{"q":"How big is the discount?","a":"50% off HUD's list price."},{"q":"Do I pay back the discount?","a":"Not if you live there 36 months; a silent second secures it."},{"q":"How are winners chosen?","a":"Random lottery among eligible bids."},{"q":"Can I use FHA with $100 down?","a":"Yes, for GNND buyers."},{"q":"Can I have owned a home before?","a":"Not in the 12 months before bidding."},{"q":"Are the homes move-in ready?","a":"Sold as-is; many need repairs."},{"q":"Where are listings posted?","a":"HUDHomestore.gov."},{"q":"Are there many in San Diego?","a":"Very few; most listings are in lower-cost markets (verify)."}],"aeQuestions":["Do you close GNND transactions?","Will you pair GNND with 203(k)?","How do you handle the HUD second mortgage?","Minimum FICO for $100 down?","Turn times vs HUD closing deadline?","Will you accept VA for GNND?","Escrow and title requirements?","Can extensions be requested?"],"redFlags":["Occupation not serving the property's community","Ownership within prior 12 months","Plans to rent the home","Missing annual certifications","Lender unfamiliar with GNND second","Repair needs ignored"],"pricing":"GNND pricing follows standard FHA, VA or conventional pricing; the value comes from the 50% discount. Factor in repair costs and whether 203(k) pricing adds cost. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Teacher unions and school district HR (education only)","Fire and police department wellness programs","EMT associations","HUD-registered selling brokers","Content explaining GNND and lottery process"],"checklist":["Employment verification letter showing role and service area","Certification of no ownership in prior 12 months","HUD GNND bid documents","HUD second mortgage and note","FHA appraisal","203(k) docs if repairs","Income docs","Asset docs","Insurance","Annual occupancy certification calendar"],"updated":"2026-11"},
"a_sec184":{"matrix":[["Eligibility","Members of federally recognized tribes and Alaska Natives (and tribes, TDHEs); tribal enrollment documentation required"],["Min FICO","No HUD minimum score; lenders overlay 580-640 (lender-specific); non-traditional credit allowed"],["Max LTV","97.75% for loans over $50,000 and 98.75% for $50,000 or less (verify under the 2024 final rule)"],["Loan limits","Section 184 area loan limits published by HUD ONAP, generally tied to FHA limits (verify 2026 schedule)"],["Guarantee fee","Upfront 1% (financeable); annual 0.25% (verify current); no traditional MI"],["DTI/underwriting","Manual underwriting common; ratios around 41% with compensating factors (lender-specific)"],["Eligible areas","Tribal trust land, reservation land and approved Section 184 areas; California is broadly eligible statewide (verify)"],["Occupancy","Primary residence; 1-4 units"],["Property","Single-family 1-4 units, manufactured on permanent foundation; new construction and rehab allowed"],["Trust land","Requires BIA lease approval and Title Status Report"],["Lender approval","Only HUD Section 184-approved lenders; Steve brokers through approved wholesale lenders if available (verify)"],["Program changes","Final rule modernized program in 2024-2025 (lender requirements, underwriting standards); verify current Section 184 Processing Guidelines"],["States","All of Steve's states have approved areas (verify specific counties)"]],"walkthrough":["Confirm tribal enrollment and obtain documentation","Confirm property is in an approved Section 184 area","Identify an approved Section 184 lender channel","Pull credit; consider non-traditional credit if thin","Pre-approve with upfront and annual guarantee fee included","For trust land: initiate BIA lease approval and TSR","Order appraisal","Underwrite (manual typical)","Submit to HUD ONAP for guarantee","Close","Record and file guarantee","Post-close: explain refinancing options later"],"incomeExample":{"title":"Section 184 purchase, guarantee fee and DTI, Temecula area","steps":["Price $450,000; down 2.25% = $10,125; base loan $439,875","Upfront guarantee fee 1% = $4,399; total loan $444,274","Annual fee 0.25% x $439,875 / 12 = $92/month","Illustrative P&I $2,850 + tax $470 + ins $120 + annual fee $92 = $3,532","Income $8,600; debts $380; DTI = $3,912 / $8,600 = 45.5%"],"result":"Lower ongoing guarantee fee vs FHA MIP; DTI above 41% needs compensating factors."},"scenarios":[{"t":"Off-reservation buyer in Temecula","who":"Nicole, 33, enrolled tribal member and HR coordinator, Temecula","situation":"Nicole is an enrolled member of a federally recognized tribe and wants a single-family home in Temecula, off reservation. She has $12,000 saved and a 660 score. FHA's annual MIP would cost noticeably more each month.","structure":"Section 184 purchase with 2.25% down","numbers":"Price $450,000; annual fee about $92/month vs FHA MIP about $200","why":"Lower ongoing cost than FHA with a similar down payment","alternatives":"FHA; conventional 97","watch":"Approved-lender availability and manual underwriting timelines"},{"t":"Trust land construction","who":"Eli, 46, tribal government employee, Pala","situation":"Eli wants to build on trust land assigned by his tribe. A construction-to-permanent Section 184 loan is offered by a few lenders. He has 3% for down payment.","structure":"Section 184 construction on trust land with BIA lease","numbers":"Construction cost $380,000","why":"Few other programs lend on trust land","alternatives":"VA NADL if he is a veteran","watch":"BIA lease and TSR; builder approval"},{"t":"Navy veteran choosing 184 over VA","who":"Marcus, 39, Navy veteran and electrician, San Jacinto","situation":"Marcus is enrolled in a federally recognized tribe and also has a COE, but his entitlement is tied up in a rental. He compares Section 184 to FHA. He wants to keep the rental.","structure":"Section 184 purchase","numbers":"Price $420,000; 2.25% down","why":"Lower annual fee than FHA MIP","alternatives":"VA second-tier with down payment; FHA","watch":"Compare total cost including 1% upfront fee"},{"t":"Thin credit with rent and utility history","who":"Rachel, 27, hospitality supervisor, Valley Center","situation":"Rachel has only one credit card and no scored history long enough for most programs. She has paid rent, phone and utilities on time for four years. She has $10,000 saved and wants a modest home near her job.","structure":"Section 184 with non-traditional credit verification","numbers":"Price $380,000; 2.25% down $8,550","why":"Section 184 allows alternative credit where many lenders would decline","alternatives":"FHA manual underwriting with non-traditional credit","watch":"Need 12+ months of documented rent and utility payments; lender overlays"},{"t":"Refinancing FHA into Section 184","who":"Thomas, 52, enrolled tribal member and teacher, Phoenix AZ","situation":"Thomas bought with FHA in 2022 and pays life-of-loan MIP. He learned Section 184 refinances are available for eligible borrowers. His home value is up and his credit is 700.","structure":"Section 184 rate/term refinance","numbers":"Loan $310,000; annual guarantee fee about $65/month vs current MIP about $142","why":"Lower ongoing insurance cost","alternatives":"FHA streamline (keeps MIP); conventional refinance at 80% LTV","watch":"Weigh 1% upfront fee against monthly savings"}],"qa":[{"q":"Who is eligible for Section 184?","a":"Enrolled members of federally recognized tribes, Alaska Natives, and certain tribal entities."},{"q":"Do I have to buy on a reservation?","a":"No; many off-reservation areas are approved, including broad areas of California (verify)."},{"q":"What is the down payment?","a":"2.25% for loans over $50,000 (verify current rule)."},{"q":"Is there mortgage insurance?","a":"A 1% upfront guarantee fee and a 0.25% annual fee instead."},{"q":"Can I build a home?","a":"Yes, with an approved lender."},{"q":"Can I refinance into 184?","a":"Yes, rate/term and some cash-out options."},{"q":"Do I need a perfect credit score?","a":"No minimum by HUD; lenders set overlays."},{"q":"Can a non-Native spouse be on the loan?","a":"Generally yes as a co-borrower if the eligible borrower is on the loan."}],"aeQuestions":["Are you an approved Section 184 lender and do you accept brokered loans?","Minimum FICO?","Do you lend on trust land?","Construction-to-permanent available?","Non-traditional credit allowed?","Max DTI?","Current loan limits in San Diego and Riverside?","Turn time for HUD guarantee?"],"redFlags":["Enrollment documentation missing","Property outside approved area","Trust land without BIA lease","Lender not Section 184 approved","Builder not approved for construction","Borrower confusion between 184 and NADL"],"pricing":"Section 184 pricing varies by lender; the guarantee fee structure is cheaper than FHA MIP for many borrowers. Compare total cost against FHA and VA. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Tribal housing departments","Native community events (with tribal permission)","Content comparing Section 184, VA NADL and FHA","Native veteran outreach","Tribal employers"],"checklist":["Tribal enrollment documentation","Approved area confirmation","Credit report","Income docs","Asset docs","Appraisal","BIA lease and TSR if trust land","Construction contract if applicable","Guarantee fee calc","Insurance"],"updated":"2026-11"},
"a_usda_purchase":{"matrix":[["Min FICO","No USDA minimum; GUS streamlined credit typically at 640+; below 640 manual UW; lender overlays 620-640 (lender-specific)"],["Max LTV","100% of appraised value plus financed 1% guarantee fee (can exceed 100%)"],["Loan limits","No fixed loan limit for Guaranteed; limited by repayment ability and household income limit"],["Income limit","Household income at or below 115% of area median; 2026 limits updated by RD (some reports cite $122,800 for 1-4 member and $162,100 for 5-8 member base areas, higher in high-cost counties; verify by county)"],["DTI/AUS","GUS; 29/41 guideline ratios, with GUS Accept allowing higher; manual waivers with compensating factors"],["Guarantee fee","1.00% upfront and 0.35% annual (verify FY2026)"],["Reserves","Not required; can be compensating factor"],["Waiting periods","Ch. 7 BK 3 years; Ch. 13 12 months of plan payments; foreclosure 3 years (verify)"],["Property eligibility","Located in USDA-eligible rural area per RD map; must be modest, non-income producing, 1 unit"],["Occupancy","Primary residence; no other adequate housing owned in commuting distance"],["Residency","U.S. citizens, non-citizen nationals or qualified aliens; temporary 2022 authority for some non-citizens with EADs terminated March 2025 (verify current HB-1-3555)"],["Appraisal","Standard appraisal with HUD 4000.1 property standards via RD (verify)"],["Property types","Single-family, PUD, approved condos, manufactured new on permanent foundation"],["States","Eligible rural areas in CA (e.g., parts of Ramona, Valley Center, Julian, Alpine, Anza, Aguanga; verify map), NV, AZ, FL, IL"]],"walkthrough":["Check property address on USDA eligibility map","Compute total household income (all adults) vs county limit","Confirm citizenship/qualified alien status","Pull credit; run GUS","Calculate guarantee fees","Pre-approve with fee and payment","Agent coaching: USDA requires property standards","Order appraisal","Submit to RD for conditional commitment","Clear conditions","Close","Post-close: set reminder for Streamlined-Assist eligibility after 12 months"],"incomeExample":{"title":"USDA household income eligibility test, Valley Center","steps":["Borrower salary $68,000; spouse part-time $22,000; adult son living at home earns $26,000","Total household income = $116,000 (son counts even though not on the loan)","Deductions: 2 minor children x $480 = $960; childcare $6,000","Adjusted household income = $116,000 - $960 - $6,000 = $109,040","San Diego County limit for 5-8 member household (illustrative) $180,000 (verify)","Eligible: $109,040 is below limit","Qualifying income (borrowers only) = $90,000; DTI computed on that"],"result":"Household passes the income test; qualifying uses only borrower income."},"scenarios":[{"t":"Ramona family while VA entitlement is blocked","who":"Kyle, 36, Navy veteran and diesel mechanic, Ramona","situation":"Kyle's VA entitlement is reduced by an old foreclosure claim he is still repaying. His household of five earns $112,000 including a working 19-year-old son. The home he likes sits in a USDA-eligible part of the Ramona area (verify map).","structure":"USDA Guaranteed purchase, 0% down, 1% fee financed","numbers":"Price $640,000; fee $6,400; annual 0.35% about $187/month; qualifying on Kyle and spouse income only","why":"Zero down with lower monthly insurance than FHA","alternatives":"FHA 3.5% down; VA after the claim is repaid","watch":"Son's income counts toward the household limit; well and septic inspections if applicable"},{"t":"Anza first-time buyers with little cash","who":"Lupe, 31, and Mateo, 33, ranch and vineyard workers, Anza","situation":"They earn $78,000 combined with steady seasonal-to-year-round history over three years. They have $5,000 saved and rent a small house for $1,900. Homes on modest lots in Anza are typically USDA eligible.","structure":"USDA purchase with seller paying closing costs (no USDA concession cap, but lender limits apply)","numbers":"Price $420,000; loan $424,200 with fee; payment about $2,900 illustrative","why":"Zero down lets them buy now rather than save for years","alternatives":"FHA with CalHFA DPA","watch":"Seasonal income documentation; acreage and outbuildings must be incidental"},{"t":"Over the household income limit","who":"Brandon, 40, aerospace engineer, Alpine","situation":"Brandon and his wife earn $205,000 combined with two children. The Alpine home they want is in an eligible area. Their adjusted income exceeds the county limit even after deductions.","structure":"Not USDA eligible; VA purchase (Brandon is an Air Force veteran) or conventional","numbers":"Adjusted household income $203,000 vs limit (illustrative) $180,000","why":"Eligibility depends on income, not just location","alternatives":"VA zero down; conventional 95%","watch":"Do not reduce reported income to fit; document deductions accurately"},{"t":"New manufactured home on owned land","who":"Tina, 45, certified nursing assistant, Aguanga","situation":"Tina owns a 2-acre lot from her late father and wants a new manufactured home installed. Her income is $58,000 and her score is 655. USDA allows new manufactured homes on permanent foundations.","structure":"USDA Guaranteed for a new manufactured unit with land equity","numbers":"Home and site work $290,000; land value supports LTV","why":"Zero down using land as part of the value","alternatives":"FHA Title II; chattel loan","watch":"New units only; dealer must meet RD requirements; foundation certification"},{"t":"Nevada buyer outside Las Vegas","who":"Derek, 29, Army veteran and warehouse lead, Pahrump NV","situation":"Derek wants to save his VA entitlement for a future move back to California. His income is $64,000 and Pahrump addresses are commonly eligible. He has $8,000 saved for closing costs.","structure":"USDA purchase in Nye County","numbers":"Price $330,000; fee 1% $3,300; annual about $96/month","why":"Keeps VA entitlement free while buying with zero down","alternatives":"VA purchase now","watch":"USDA requires no other adequate housing; long-term plan to relocate is fine"}],"qa":[{"q":"Is there a USDA loan limit?","a":"Not for Guaranteed loans; you're limited by household income and ability to repay."},{"q":"Whose income counts for the limit?","a":"All adult household members, even those not on the loan."},{"q":"Do I need to be a first-time buyer?","a":"No, but you can't own adequate housing nearby."},{"q":"Is the funding fee financed?","a":"Yes, the 1% upfront guarantee fee can be financed."},{"q":"Can the seller pay my costs?","a":"Yes; USDA allows seller contributions toward closing costs per lender limits."},{"q":"Can I buy a home with acreage?","a":"Yes if the land is typical for the area and not income-producing."},{"q":"Are non-citizens eligible?","a":"Citizens, non-citizen nationals and qualified aliens; a 2022 temporary authority for some EAD holders ended in March 2025 (verify)."},{"q":"How long does approval take?","a":"GUS approval plus RD conditional commitment; timing varies by state office."},{"q":"Can I refinance later?","a":"Yes, including USDA Streamlined-Assist after 12 months."}],"aeQuestions":["Minimum FICO for GUS Accept and manual?","How long is your RD conditional commitment turn time in CA?","Do you allow manufactured homes?","Max DTI with GUS Accept?","Seller concession limit?","How do you document household income for non-borrowers?","Do you require well/septic inspections?","Condo approval process?","How do you verify qualified alien status?"],"redFlags":["Address outside eligible area","Household income over limit when all adults are counted","Borrower owns adequate housing nearby","Income-producing property features (barn rentals, crops)","Non-citizen status unclear after March 2025 change","Pool or luxury features may need review (verify)","Funding fee not disclosed"],"pricing":"USDA pricing is usually competitive with FHA and VA; the 1% upfront and 0.35% annual guarantee fees are lower than FHA MIP. Compare the monthly fee difference over the expected hold period. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Rural North County San Diego and Riverside County agent partners","Agricultural and winery workers associations","Content: 'USDA isn't just farms' with eligible map examples","Veterans saving entitlement for later","First-time buyer workshops in eligible areas"],"checklist":["USDA eligibility map printout (property)","Household income worksheet","Income docs for all household adults","Credit report","GUS findings","Appraisal","RD conditional commitment","Purchase contract","Citizenship/qualified alien docs","Well/septic reports if applicable","Insurance","Guarantee fee calc"],"updated":"2026-11"},
"a_usda_streamassist":{"matrix":[["Existing loan","Must be a USDA Section 502 Guaranteed or Direct loan"],["Min FICO","No credit score requirement by USDA; no credit review besides mortgage history; lenders may overlay (lender-specific)"],["Payment history","Current loan at least 12 months old with on-time payments for prior 12 months (verify 180-day lookback specifics)"],["Net tangible benefit","New total monthly payment (PITI + annual fee) at least $50 lower than current"],["Appraisal","Not required"],["DTI","Not calculated"],["Income limit","Household income must still be within the moderate-income limit (115% AMI) for the area"],["Loan amount","Existing principal + accrued interest + guarantee fee + eligible closing costs; no cash out"],["Guarantee fee","1% upfront and 0.35% annual on new loan (verify FY2026)"],["Borrowers","Borrowers can be removed but not added (except spouse in some cases; verify)"],["Occupancy","Primary residence"],["Residency","Applies citizenship/qualified alien rules; refinances may carry forward original rules (verify)"],["States","All USDA-eligible areas in licensed states"]],"walkthrough":["Confirm current loan is USDA Guaranteed or Direct","Check 12-month payment history","Verify household income under current limit","Compute $50 monthly payment reduction","Disclose; no appraisal or DTI","Order title and payoff","Underwrite via GUS or manual (per lender)","Submit to RD for guarantee","Close","Fund","Confirm new annual fee in escrow","Review in 12 months"],"incomeExample":{"title":"Streamlined-Assist $50 net tangible benefit test","steps":["Current payment: P&I $2,175 + taxes $380 + insurance $120 + annual fee $105 = $2,780","Option A: finance $4,500 costs; new loan $360,000 + $4,500 + 1% fee $3,645 = $368,145; illustrative P&I $2,190; annual fee $107; total $2,797","Option A fails: $2,797 is higher than $2,780","Option B: lender credit covers costs; new loan $360,000 + 1% fee $3,600 = $363,600; illustrative P&I $2,110; annual fee $106","Option B total = $2,110 + $380 + $120 + $106 = $2,716","Reduction = $2,780 - $2,716 = $64, which meets the $50 minimum"],"result":"Passes only when the rate drop is meaningful and costs are covered by lender credit; always run both structures."},"scenarios":[{"t":"2023 USDA buyer in Valley Center","who":"Ashley, 34, Navy spouse and dental hygienist, Valley Center","situation":"Ashley and her husband bought with USDA in 2023 at a higher rate. They have 30 on-time payments. Their home value may have dipped, which would block a conventional refinance, but Streamlined-Assist needs no appraisal.","structure":"USDA Streamlined-Assist with lender credit covering costs","numbers":"Payment drops about $110/month (illustrative)","why":"No appraisal, no DTI calculation and no credit score requirement","alternatives":"Conventional rate/term (needs appraisal and equity)","watch":"Household income must still be under the limit; a recent promotion could push it over"},{"t":"Removing a departed co-borrower","who":"Ricardo, 42, irrigation technician, Hemet","situation":"Ricardo and his ex-partner bought with USDA in 2021. She moved out and signed a quitclaim. He wants her removed from the loan and a lower rate.","structure":"Streamlined-Assist removing one borrower","numbers":"Illustrative payment drop $70/month","why":"Can remove a borrower without full re-qualification","alternatives":"Full USDA refinance with income and credit review","watch":"Title, quitclaim and RD rules on borrower changes"},{"t":"Direct 502 borrower with payment assistance","who":"Gloria, 58, school cafeteria worker, Blythe","situation":"Gloria has a USDA Direct loan with payment assistance that lowers her effective rate. She asks about refinancing into a Guaranteed loan through Streamlined-Assist. Losing the subsidy and possible recapture could raise her costs.","structure":"Compare staying in Direct vs Streamlined-Assist into Guaranteed (verify recapture rules)","numbers":"Net payment change depends on lost subsidy (illustrative)","why":"May only make sense if her subsidy has already ended","alternatives":"Stay in the Direct program with assistance","watch":"Subsidy recapture due at refinance or sale"},{"t":"Household income now above the limit","who":"Kevin, 40, union lineman, Ramona","situation":"Kevin's overtime income now pushes household income above the USDA limit. He has a USDA loan from 2022 and hoped to streamline. Streamlined-Assist still applies the income test.","structure":"Not eligible; conventional rate/term refinance instead","numbers":"Household income over the county limit (illustrative)","why":"Income test still applies on Streamlined-Assist","alternatives":"Conventional; FHA refinance","watch":"Document income honestly and include all household adults"},{"t":"Recent 30-day late","who":"Dana, 37, retail manager, Lake Havasu City AZ","situation":"Dana had a 30-day late 8 months ago due to a bank error. She wants to streamline now. The program requires a clean recent payment history.","structure":"Wait until the 12-month window is clean, then Streamlined-Assist","numbers":"Re-check eligibility in about 4 months","why":"Avoids a declined file","alternatives":"Conventional refinance if she has equity","watch":"A bank error letter may not cure the late (verify)"}],"qa":[{"q":"Do I need an appraisal?","a":"No, Streamlined-Assist does not require an appraisal."},{"q":"Is my credit score checked?","a":"USDA doesn't require a score or credit review beyond mortgage history; lenders may overlay."},{"q":"How much must my payment drop?","a":"At least $50 per month including the annual guarantee fee."},{"q":"Can I take cash out?","a":"No, only payoff, eligible costs and the guarantee fee can be financed."},{"q":"Do I still have to be under the income limit?","a":"Yes, household income must still be within the moderate-income limit."},{"q":"Can I remove a borrower?","a":"Yes in most cases, with documentation."},{"q":"Can I add a borrower?","a":"Generally no (verify spouse exception)."},{"q":"How long must I have the loan?","a":"At least 12 months with on-time payments."}],"aeQuestions":["Do you offer USDA Streamlined-Assist?","Credit score overlay?","How do you compute the $50 benefit (PITI including fee)?","Can costs be financed?","Borrower removal policy?","Direct-to-Guaranteed refinances?","RD turn time?","Income verification process?"],"redFlags":["Payment reduction under $50","Late payments within 12 months","Household income above limit","Adding borrowers","Cash-out expectations","Direct loan subsidy recapture overlooked"],"pricing":"Streamlined-Assist pricing is close to USDA purchase pricing; because savings must exceed $50, lender credit often decides eligibility. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Past USDA clients after 12 months","Rural agent partners' client lists","Content on no-appraisal refinance","Direct loan borrowers in rural areas","Annual review emails"],"checklist":["Current USDA loan statement","12-month payment history","Household income docs","$50 benefit worksheet","Title report","Payoff","Insurance","RD guarantee submission","ID","Quitclaim if removing borrower"],"updated":"2026-11"},
"a_usda_504":{"matrix":[["Lender","USDA Rural Development direct program; brokers do not originate; Steve refers only"],["Eligibility","Very low income (below 50% of area median); owner-occupant; unable to obtain affordable credit elsewhere"],["Loans","Up to $40,000 (verify) at 1% fixed, 20-year term"],["Grants","Up to $10,000 (verify) for homeowners 62+ who can't repay a loan; lifetime cap"],["Combined","Loan and grant up to $50,000 (verify)"],["Purpose","Repair, improve, modernize, or remove health and safety hazards"],["Property location","Eligible rural area"],["Security","Loans over $25,000 require real estate mortgage; title evidence (verify)"],["Grant recapture","Grant repaid if property sold within 3 years"],["Application","Year-round through RD state office; funding availability varies"],["Residency","Citizenship/qualified alien requirements"],["States","All licensed states with rural eligible areas"]],"walkthrough":["Confirm age, income and rural location","Refer to RD local office","Collect repair estimates","RD reviews income and need","Approve loan/grant","Contractor performs work","RD inspects","Funds released","Steve follows up for future needs"],"incomeExample":{"title":"Section 504 very-low-income test and payment","steps":["Household: widow age 72, Social Security $1,850/month = $22,200/year","Very low income limit (illustrative San Diego rural) $55,000 (verify)","Eligible: below 50% AMI","Roof replacement $24,000; grant $10,000 (age 62+) plus loan $14,000","Loan at 1% over 20 years: payment about $64/month","Payment is 3.5% of monthly income"],"result":"Eligible for grant and loan; payment is affordable."},"scenarios":[{"t":"Widow needing a roof","who":"Dorothy, 74, retired school secretary, Julian","situation":"Dorothy lives alone on Social Security and a small pension totaling $2,100/month. Her roof leaks and contractors quote $24,000. She can't afford a conventional loan payment.","structure":"Section 504 grant plus 1% loan (verify limits)","numbers":"Grant $10,000; loan $14,000; payment about $64/month over 20 years","why":"Low cost and grant funds for a senior very-low-income owner","alternatives":"CalVet Home Improvement if a veteran; local nonprofit repair programs","watch":"Grant repayable if she sells within 3 years"},{"t":"Disabled veteran accessibility","who":"Harold, 66, Army veteran, Anza","situation":"Harold uses a walker and needs a ramp and accessible bathroom. His income is $1,700/month. He may also qualify for VA HISA or SAH grants.","structure":"Coordinate a 504 grant with VA grants where eligible","numbers":"504 grant up to $10,000; VA HISA per lifetime limit (verify)","why":"Stacks resources without new debt","alternatives":"Nonprofit veteran home repair groups","watch":"Avoid funding the same work twice"},{"t":"Failed septic with a county notice","who":"Rosa, 63, farmworker, Thermal","situation":"Rosa's septic system failed and the county issued a correction notice. Her income is very low. She needs a fast fix to stay in her home.","structure":"Section 504 loan and grant for health and safety repair","numbers":"Septic replacement $18,000; grant $10,000 + loan $8,000","why":"Health and safety hazard removal is a core purpose","alternatives":"County or utility emergency programs","watch":"RD funding timing vs county deadline"},{"t":"Under 62, loan only","who":"Carlos, 48, disabled warehouse worker, Blythe","situation":"Carlos needs a new water heater and electrical repairs. He's under 62, so he can't get a grant. His income is very low but steady from disability benefits.","structure":"Section 504 loan only","numbers":"Loan $12,000 at 1% for 20 years; payment about $55","why":"Affordable repair financing","alternatives":"Credit card or personal loan (high cost)","watch":"Ability to repay from fixed income"},{"t":"Manufactured home owner","who":"Elena, 70, retired seamstress, Coachella","situation":"Elena owns her manufactured home on her own lot. The windows and roof need repair. She asks whether 504 can help with a manufactured home.","structure":"Section 504 for a manufactured home on owned land (verify eligibility)","numbers":"Repairs $15,000; grant and loan mix","why":"May qualify when home is on owned land","alternatives":"CalVet if a veteran; nonprofit repair","watch":"Real property status and RD property rules"}],"qa":[{"q":"Who qualifies for 504?","a":"Very-low-income rural homeowners; grants for those 62 or older."},{"q":"Can Steve originate a 504 loan?","a":"No, it's a USDA direct program; Steve can refer at no charge."},{"q":"What rate is the loan?","a":"1% fixed for 20 years."},{"q":"How much is the grant?","a":"Up to $10,000 (verify current limit)."},{"q":"Do I have to repay the grant?","a":"Only if you sell within 3 years."},{"q":"What repairs are eligible?","a":"Repairs, improvements, and health/safety hazard removal."},{"q":"Does it take long?","a":"It depends on RD funding and local office volume."},{"q":"Can I combine with VA grants?","a":"Often yes, without duplicating costs."}],"aeQuestions":["(RD local office) Current 504 loan and grant limits?","Funding availability this fiscal year?","Processing time?","Contractor requirements?","Manufactured home eligibility?","Security requirements above $25,000?","Income limits for our county?","Can 504 combine with other programs?"],"redFlags":["Anyone charging a fee for 504 referral","Income above very-low limit","Property not rural","Applicant not owner-occupant","Grant sought by under-62 homeowner","Duplicate funding with other grants"],"pricing":"Section 504 rates are fixed by statute at 1% and grants carry no interest, so there is no market pricing to compare. Steve earns nothing on referrals and should say so clearly; any repair financing he could broker would only be compared if 504 is unavailable. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Area Agencies on Aging","County veteran service officers","Rural senior centers","Faith-based community groups","Content explaining 504 for seniors"],"checklist":["Proof of ownership","Income docs","Age proof for grant","Repair estimates","RD application","Contractor info","Property location eligibility","Title evidence (loans over $25,000)","Insurance","Referral notes"],"updated":"2026-11"},
"a_conv_lowdown":{"matrix":[["Min FICO","Fannie DU: no hard minimum since casefiles created on or after Nov 16, 2025 (SEL-2025-09); Freddie LPA 620 (verify); most lenders still overlay 620 and MI companies may require 620-640 (lender-specific)"],["Max LTV/CLTV","97% LTV 1-unit primary; CLTV up to 105% with Community Seconds/Affordable Seconds"],["Loan limits","Must be at or below baseline $832,750 for 97% (high-balance not eligible for 97%); 1-unit only for 97%"],["Income limit","HomeReady and Home Possible: qualifying income at or below 80% of area median income (AMI) for the property location; Conventional 97 standard has no income limit but requires a first-time buyer"],["DTI/AUS","DU/LPA up to 50%; HomeReady allows boarder income and ADU rental income to help qualify"],["MI","Coverage at 95.01-97%: 25% for HomeReady/Home Possible (vs 35% standard); monthly BPMI cancellable at 80%/78%"],["LLPAs","Upfront LLPAs waived for HomeReady/Home Possible and for first-time buyers at or below 100% AMI (120% in high-cost areas) per FHFA (verify current)"],["Reserves","Usually none on 1-unit with DU approve"],["First-time buyer","Conventional 97 standard: at least one borrower a first-time buyer (no ownership in 3 years); HomeReady/Home Possible: not required, but homeownership education required when all are first-time buyers"],["Down payment sources","Gifts, grants, Community Seconds, and employer assistance allowed; no minimum borrower contribution on 1-unit"],["Special credits","Fannie and Freddie have offered $2,500 credits for very-low-income purchasers at or below 50% AMI (verify active status in 2026)"],["Credit score models","VantageScore 4.0 now permitted for GSE loans in addition to Classic FICO, with lender adoption varying; same model for all borrowers (verify)"],["Residency","Lawful permanent and non-permanent residents with valid work authorization are eligible (unlike FHA after May 2025)"],["States","Nationwide; AMI varies by census tract"]],"walkthrough":["Look up AMI for the property address in Fannie's or Freddie's AMI tool","Compare qualifying income to 80% AMI for HomeReady/Home Possible","Check first-time buyer status for standard Conventional 97","Run both DU and LPA to compare findings and MI","Quote MI with reduced 25% coverage for HomeReady/Home Possible","Schedule homeownership education (Framework or CreditSmart)","Layer DPA (CalHFA, Community Seconds) if needed","Issue pre-approval with full PITI including MI","Order appraisal or confirm value acceptance","Clear conditions including gift and DPA documents","Close and fund","Calendar MI removal review at 80% LTV"],"incomeExample":{"title":"HomeReady 80% AMI income limit test, Chula Vista","steps":["Property census tract AMI (illustrative) $128,000; 80% limit = $102,400 (verify in AMI lookup)","Borrower base salary $72,000 + co-borrower part-time $24,000 = $96,000 qualifying income","Boarder income (borrower's brother pays $700/month for 12 months documented) used to qualify but counted toward the limit (verify treatment)","Total counted = $96,000 + $8,400 = $104,400 exceeds $102,400","Option: exclude boarder income; $96,000 under limit; recompute DTI without boarder","Purchase $560,000 at 97%; loan $543,200; MI coverage 25%"],"result":"Eligible for HomeReady if boarder income is excluded and DTI still works; otherwise use Conventional 97 standard."},"scenarios":[{"t":"Military spouse under 80% AMI","who":"Jessica, 30, military spouse and preschool teacher, Chula Vista","situation":"Jessica's husband is a Navy E-5 on sea duty; they want to save his VA entitlement for a larger home later. Her income is $58,000 and his base pay is $42,000 (BAH counted as income may push them over AMI). They have $12,000 saved and a $10,000 gift.","structure":"HomeReady 97% with reduced MI coverage; qualify on Jessica's income alone or both if under AMI","numbers":"Price $520,000; 3% down $15,600; loan $504,400; MI coverage 25%","why":"Lower MI and LLPA relief compared to standard 97","alternatives":"VA purchase (zero down, no MI); FHA","watch":"Count all qualifying income against AMI including BAH if used"},{"t":"First-time buyer above AMI","who":"Daniel, 32, software QA analyst, San Marcos","situation":"Daniel earns $135,000, above 80% AMI, so HomeReady is out. He has $25,000 and a 760 score. He's never owned.","structure":"Conventional 97 standard (first-time buyer)","numbers":"Price $640,000; down $19,200; loan $620,800","why":"Strong credit pricing; no income limit","alternatives":"FHA (MIP costs more at 760)","watch":"Loan must be under baseline $832,750"},{"t":"Boarder income helps","who":"Maribel, 38, dental office manager, Escondido","situation":"Maribel's cousin has lived with her for 2 years and pays $800/month. She needs that income to hit 50% DTI. Her income is under 80% AMI.","structure":"HomeReady using boarder income (up to 30% of total income)","numbers":"Boarder income $9,600/year","why":"HomeReady is the conventional program that allows boarder income","alternatives":"FHA (no boarder income)","watch":"Document 12 months of payments and shared residency"},{"t":"Community Second with CalHFA","who":"Andre, 27, Marine Corps veteran and apprentice electrician, Oceanside","situation":"Andre has a 680 score and $6,000. He wants to use CalHFA's Dream For All or MyHome assistance (verify availability). His VA eligibility is pending service record correction.","structure":"HomeReady first with CalHFA second","numbers":"Price $500,000; CLTV up to 105%","why":"Combines assistance with low MI","alternatives":"VA once COE issued","watch":"DPA program funding windows"},{"t":"Non-permanent resident","who":"Priya, 34, nurse on H-1B, La Mesa","situation":"Priya can't use FHA after May 2025. Her income is $98,000, under AMI in her tract. She has $20,000.","structure":"HomeReady 97% with non-permanent residency documentation","numbers":"Price $480,000","why":"GSEs still allow non-permanent residents with valid EAD/visa","alternatives":"Non-QM","watch":"Visa expiration and employer continuance"}],"qa":[{"q":"What is the minimum down payment?","a":"3% on 1-unit primary residences."},{"q":"What is the income limit for HomeReady and Home Possible?","a":"80% of area median income for the property location."},{"q":"Do I need to be a first-time buyer?","a":"For standard Conventional 97, yes; for HomeReady/Home Possible, no."},{"q":"Is homeownership education required?","a":"Yes, when all borrowers are first-time buyers."},{"q":"Can I use gift funds for everything?","a":"Yes on 1-unit, with documentation."},{"q":"Is there a minimum credit score now?","a":"Fannie DU no longer has a hard 620 minimum, but lenders and MI companies often still require 620+."},{"q":"Can I remove MI later?","a":"Yes, at 80% LTV on request or 78% automatically."},{"q":"Can I buy a condo with 3% down?","a":"Yes if the project is warrantable."},{"q":"Does boarder income count?","a":"With HomeReady, yes, if documented."},{"q":"Can a non-permanent resident use HomeReady?","a":"Yes with valid status and work authorization."}],"aeQuestions":["Do you overlay a 620 minimum despite DU changes?","Which MI companies and rate cards do you use for 25% coverage?","Do you accept VantageScore 4.0 yet?","Which DPA seconds do you accept with HomeReady?","Do you allow boarder and ADU income?","Do you allow 97% on condos?","Appraisal waiver availability?","How do you verify AMI?","Non-permanent resident documentation requirements?"],"redFlags":["Income above 80% AMI for HomeReady","Loan amount above baseline for 97%","No first-time buyer on standard Conventional 97","Gift funds without transfer evidence","MI company score floor not met","Non-warrantable condo","Undisclosed debts"],"pricing":"HomeReady and Home Possible often beat standard 97 because of reduced MI coverage and LLPA waivers for qualifying incomes. Compare MI rate cards since monthly MI differs by company and credit score. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["First-time buyer classes with HUD-approved counselors","Military spouse employment networks","Employer housing benefit programs","CalHFA and Community Second partners","Content on 3% down vs FHA 3.5% down"],"checklist":["AMI lookup printout","Income docs","Credit","Homeownership education certificate","Gift letter","DPA docs","Purchase contract","Appraisal or waiver","MI certificate","Boarder income docs","Residency docs","Insurance"],"updated":"2026-11"},
"a_conv_purchase":{"matrix":[["Min FICO","Fannie DU no hard minimum (Nov 2025); Freddie LPA 620 (verify); lenders overlay 620-640 (lender-specific)"],["Max LTV","97% for first-time buyers (1-unit, baseline limit); 95% for others; 95% for 2-4 units primary (verify current)"],["Loan limits","2026 baseline $832,750 (1-unit); high-cost up to $1,249,125"],["DTI/AUS","DU/LPA up to 50%; manual 36-45% with reserves"],["MI","Required above 80% LTV; BPMI cancellable"],["LLPAs","FICO/LTV grid plus attribute LLPAs (condo, investment, cash-out)"],["Reserves","DU-determined; 2-4 units more"],["Waiting periods","BK7 4 years (2 with extenuating); BK13 2 years from discharge or 4 from dismissal; foreclosure 7 years (3 with extenuating); short sale/deed-in-lieu 4 years"],["Property types","1-4 units, condos (warrantable), PUDs, co-ops, manufactured"],["Occupancy","Primary, second home, investment"],["Appraisal","Appraisal, value acceptance (waiver) or value acceptance + property data when eligible"],["Credit score models","Classic FICO and VantageScore 4.0 (2026) permitted; lender adoption varies (verify)"],["Residency","Citizens, LPRs and non-permanent residents with valid status"],["States","Nationwide"]],"walkthrough":["Collect income, asset and credit documents; identify self-employment, rental or variable income early","Run DU and LPA side by side; note reserve and documentation differences","Decide credit score model the lender uses (Classic FICO or VantageScore 4.0) and keep it consistent for all borrowers","Price LLPAs at several down-payment levels (5%, 10%, 15%, 20%) to find cliffs","Get MI quotes from at least two MI companies or the lender's rate-card engine","Issue pre-approval with full PITI including MI, HOA and Mello-Roos","Check seller concession limits (3%/6%/9% by LTV for primary) when writing the offer","Order appraisal or confirm value acceptance eligibility after contract","Review condo project eligibility early if applicable","Clear conditions; re-verify employment","Lock strategy discussed in writing; CD three business days before consummation","Close and calendar MI removal review at 80% of original value"],"incomeExample":{"title":"Conventional 95% purchase: MI plus DTI, San Marcos","steps":["Price $750,000; 5% down $37,500; loan $712,500","MI factor (illustrative, 740 FICO, 30% coverage) 0.40% annual = $238/month","P&I illustrative $4,560; tax $781; ins $150; HOA $90; MI $238; total $5,819","Income $13,500; debts $600; DTI = $6,419 / $13,500 = 47.5%","DU approve likely with reserves"],"result":"Works with DU; MI drops at 78% scheduled LTV."},"scenarios":[{"t":"Retired Chief with used entitlement","who":"Chris, 41, retired Navy Chief and defense contractor, Santee","situation":"Chris used his VA entitlement on a Chula Vista home he now rents out for $3,200. He has $80,000 for a down payment and a 780 score. A second VA loan would carry the 3.30% subsequent-use funding fee on the gap structure, and he dislikes that cost.","structure":"Conventional 90% purchase with monthly BPMI","numbers":"Price $780,000; down $78,000; loan $702,000; MI at 780/90% is modest (illustrative $90-$130/month)","why":"No funding fee, cancellable MI, and strong credit pricing","alternatives":"VA second-tier with 10% down (1.25% fee); FHA (not competitive at 780)","watch":"Rental income needs lease and 75% vacancy factor; reserves for two financed properties"},{"t":"Self-employed with two strong years","who":"Nina, 37, salon owner, Encinitas","situation":"Nina's last two tax returns show rising net income averaging $165,000. Her score is 720 and she has 15% down plus 12 months of reserves. A non-QM loan officer quoted her a bank statement loan.","structure":"Conventional 85% full-documentation purchase with DU","numbers":"Price $820,000; down $123,000; loan $697,000","why":"Full-doc agency pricing is usually far cheaper than bank statement non-QM","alternatives":"Non-QM bank statement; 20% down to avoid MI","watch":"Year-to-date P&L may be requested; declining income would change averaging"},{"t":"Just below a credit tier","who":"Tony, 35, Marine veteran and union carpenter, Murrieta","situation":"Tony's middle score is 698 and LLPA plus MI pricing improve materially at 700 and 720. He has a card at 85% utilization. He'd rather use conventional to save his VA benefit for a future home in Idaho.","structure":"Rapid rescore after paying the card to under 30%, then conventional 95%","numbers":"Pay down $3,200; potential score lift to 715-725 (not guaranteed); loan $570,000","why":"Better pricing tier saves money every month","alternatives":"VA purchase now; FHA","watch":"Rescore is lender-ordered; never pay for 'credit repair' promises"},{"t":"Condo buyer in a warrantable project","who":"Ellie, 29, travel nurse turned staff RN, Mission Valley","situation":"Ellie wants a 2-bedroom condo near the trolley. She has 10% down and a 745 score. The HOA has a healthy reserve study and no litigation.","structure":"Conventional 90% condo purchase with full or limited project review","numbers":"Price $560,000; loan $504,000","why":"Lower MI and LLPA than FHA at her credit; no FHA condo approval needed","alternatives":"FHA (project not FHA approved)","watch":"HOA questionnaire, insurance (master policy and HO-6), special assessments"},{"t":"Gift of equity from parents","who":"Kevin, 33, Air Force veteran and paramedic, Temecula","situation":"Kevin's parents are retiring to Arizona and selling him their home for $630,000 when it appraises around $700,000. The $70,000 difference is a gift of equity. Kevin wants to keep his VA entitlement free for later.","structure":"Conventional purchase with gift of equity as the down payment","numbers":"Value $700,000; price $630,000; loan $630,000 = 90% of value; MI applies","why":"Gift of equity can satisfy down payment without cash","alternatives":"VA (would use entitlement); FHA (allows gift of equity too)","watch":"Non-arm's-length transaction rules; gift letter and CD must show gift of equity"}],"qa":[{"q":"What is the minimum down payment?","a":"3% for qualifying first-time buyers on 1-unit; 5% otherwise."},{"q":"When does MI come off?","a":"On request at 80% of original value with good payment history, automatically at 78% of scheduled balance, or at loan midpoint."},{"q":"Is there still a 620 minimum score?","a":"Fannie DU removed its hard minimum for casefiles created on or after Nov 16, 2025; Freddie and most lenders still use 620 or higher (verify)."},{"q":"How much can the seller pay?","a":"For a primary residence: 3% above 90% LTV, 6% from 75.01-90%, 9% at 75% or less."},{"q":"When is conventional better than FHA?","a":"Usually above about 700 credit, or when the borrower can put 5-10% down."},{"q":"Will lenders use VantageScore 4.0?","a":"The GSEs now permit it, but each lender decides when to adopt it."},{"q":"Can gifts cover the full down payment?","a":"On a 1-unit primary residence, yes."},{"q":"Can I buy a condo?","a":"Yes, in projects that meet agency eligibility."},{"q":"Do I need reserves?","a":"DU/LPA decide; more for 2-4 units and multiple financed properties."},{"q":"How long after bankruptcy?","a":"4 years after Chapter 7 discharge (2 with extenuating circumstances)."}],"aeQuestions":["Do you overlay a minimum score on DU loans after the Nov 2025 change?","Have you adopted VantageScore 4.0, and for which loan types?","Which MI companies are on your rate-card engine?","Appraisal waiver/value acceptance policy?","Condo review: limited vs full, and turn time?","Max DTI with DU approve?","Gift of equity and non-arm's-length policy?","Do you price LLPAs at FICO cliffs differently from the GSE grid?","How do you handle rental income on retained departing residence?","Lock extension costs?"],"redFlags":["Score sitting just under an LLPA or MI tier","Non-warrantable condo discovered late","Undisclosed liabilities or new credit inquiries","Unsourced large deposits","Non-arm's-length transaction not disclosed","Occupancy misrepresentation","Seller concessions above LTV-based limits"],"pricing":"Conventional pricing stacks GSE LLPAs (credit score by LTV, plus attributes like condo, cash-out, investment) with MI premiums that also step down by score and LTV. Small changes in score or down payment can cross a tier, so price at multiple scenarios. Compare MI cost against the alternative of FHA MIP or VA funding fee for eligible borrowers. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Agent partnerships with listing-side education on conventional offers","Retired military with entitlement in use","Self-employed professionals and their CPAs","Credit education workshops through nonprofits","Move-up buyer seminars"],"checklist":["Income documents (W-2s, paystubs, returns as required)","Asset statements (2 months)","Tri-merge credit","DU/LPA findings","Purchase contract","Appraisal or value acceptance","MI certificate","Gift letter and donor evidence","Condo questionnaire and master insurance","Homeowners insurance","Title commitment","Verbal VOE"],"updated":"2026-11"},
"a_conv_highbal":{"matrix":[["Definition","Loan amount above the 2026 baseline $832,750 (1-unit) and at or below the county's high-cost limit (ceiling $1,249,125)"],["County limits","San Diego, Orange, Los Angeles and others set annually by FHFA; San Diego 2026 limit (verify); Riverside generally baseline (verify)"],["Min FICO","DU: no hard minimum since Nov 2025 but high-balance often overlays 660-700 (lender-specific); LPA 620 (verify)"],["Max LTV purchase","Fannie: 95% 1-unit primary, 85% 2-unit, 75% 3-4 unit (verify); Freddie super conforming similar (verify)"],["Max LTV cash-out","80% 1-unit primary; 75% 2-4 (verify)"],["Second home/investment","Second home 90%; investment 85% purchase 1-unit, 75% cash-out (verify)"],["ARMs","Allowed; high-balance ARMs may have lower max LTV (e.g., 90%) (verify)"],["DTI/AUS","DU/LPA approval required; manual underwriting generally not permitted for high-balance (verify)"],["LLPAs","Additional high-balance LLPAs for ARMs and cash-out (verify current grid)"],["MI","Required above 80%; MI premiums slightly higher for larger loans in some cards"],["Reserves","DU-determined; often higher due to loan size"],["Appraisal","Value acceptance possible but less common at high balances"],["States","CA high-cost counties most common; some FL, NV counties not high-cost (verify)"]],"walkthrough":["Look up the 2026 county limit for the property and unit count","Confirm whether the loan amount lands above $832,750 (high-balance) or can be structured at baseline","Compare structures: larger down payment, piggyback second, or high-balance with MI","Run DU or LPA; high-balance generally requires AUS approval","Price high-balance LLPAs for fixed vs ARM and purchase vs cash-out","Quote MI from multiple companies if over 80% LTV","Issue pre-approval with Mello-Roos and HOA included","Order appraisal; prepare comparable support in coastal markets","Clear conditions including reserves","Lock with written explanation of pricing adjustments","Close and record","Calendar MI removal at 80% of original value"],"incomeExample":{"title":"Stay conforming vs go high-balance, Carlsbad","steps":["Price $1,000,000; 10% down gives loan $900,000 (high-balance)","To stay at baseline $832,750, down payment must be $167,250 (16.7%)","High-balance LLPA (illustrative 0.25% on fixed purchase, verify) = $2,250 extra","Option: 80/10/10 with $800,000 first (baseline), $100,000 HELOC second, 10% down; no MI","Compare MI at 90% LTV on $900,000 (illustrative $230/month) vs HELOC payment on $100,000","Choose based on total monthly cost and rate risk"],"result":"High-balance with MI is simpler; piggyback avoids MI but adds variable-rate second."},"scenarios":[{"t":"Navy officer buying in Point Loma","who":"Megan, 36, Navy Lieutenant Commander, Point Loma","situation":"Megan has $150,000 saved from a prior home sale and wants to keep her VA entitlement for a future PCS to Hawaii. The home is $1,050,000. Her husband is a civilian architect and they have a 790 score.","structure":"High-balance conventional at about 86% LTV with BPMI","numbers":"Down $150,000; loan $900,000 (above baseline, below San Diego limit; verify)","why":"Keeps VA entitlement free and avoids funding fee","alternatives":"VA jumbo (fee 1.25%-2.15% unless exempt); 80/10/10 piggyback","watch":"Confirm San Diego 2026 limit; MI cancellation timeline"},{"t":"Orange County move-up","who":"Henry, 48, retired Marine Gunnery Sergeant and engineer, Irvine","situation":"Henry is selling a condo and buying a single-family home for $1,350,000. He'll put 20% down from proceeds. Loan $1,080,000 is within the OC ceiling.","structure":"High-balance 80% fixed, no MI","numbers":"Loan $1,080,000 vs ceiling $1,249,125","why":"Agency pricing beats jumbo for many profiles","alternatives":"Jumbo (may price close); VA jumbo","watch":"Bridge timing on condo sale; contingent offer"},{"t":"2-unit in North Park","who":"Rafael, 40, chef and restaurant owner, San Diego","situation":"Rafael wants a duplex for $1,300,000 and will live in one unit. High-balance 2-unit max LTV is lower (85%). He has $200,000 to put down.","structure":"High-balance 2-unit at 85% LTV","numbers":"Loan $1,105,000 vs 2-unit high-cost limit (verify)","why":"Agency financing on a 2-unit beats DSCR pricing","alternatives":"FHA 2-unit (lower limit); VA (not eligible)","watch":"2-unit high-cost limit; rental income 75%"},{"t":"Cash-out on a Carlsbad home","who":"Judy, 57, retired Navy Captain, Carlsbad","situation":"Judy wants $250,000 cash for a vacation home down payment. Home worth $1,600,000 with $700,000 owed. High-balance cash-out at 80% max.","structure":"High-balance cash-out at 59% LTV","numbers":"New loan $950,000","why":"Large cash available at agency pricing","alternatives":"HELOC; VA cash-out","watch":"Cash-out LLPA and high-balance adjustments"},{"t":"ARM to manage payment","who":"Tom, 45, Navy Commander, Coronado","situation":"Tom plans to PCS in 6 years. He wants a 7/6 ARM to lower initial payment. Loan $1,000,000 high-balance.","structure":"High-balance 7/6 ARM (verify LTV limits)","numbers":"Loan $1,000,000 at 85% LTV","why":"Initial payment savings vs fixed","alternatives":"VA jumbo fixed","watch":"ARM caps and adjustment risk if PCS is delayed"}],"qa":[{"q":"What is a high-balance loan?","a":"A conforming loan above the $832,750 baseline but within the county's high-cost limit, up to $1,249,125 for 1-unit."},{"q":"Is pricing worse than a baseline loan?","a":"Sometimes slightly, due to high-balance adjustments, especially on ARMs and cash-out."},{"q":"Can I put 5% down?","a":"Often yes on a 1-unit primary residence with AUS approval (verify lender)."},{"q":"Can I do a cash-out refinance?","a":"Yes, up to 80% LTV on a 1-unit primary (verify)."},{"q":"Is it better than a jumbo loan?","a":"Often, but some jumbo lenders price competitively at 20% down, so compare."},{"q":"Can I use high-balance for a 2-4 unit?","a":"Yes, with higher unit-count limits but lower maximum LTV."},{"q":"Do I need more reserves?","a":"DU often requires more because of loan size."},{"q":"Can I use an ARM?","a":"Yes, though high-balance ARMs may have lower LTV caps and added LLPAs."}],"aeQuestions":["High-balance max LTV by unit count and product?","FICO overlays for high-balance?","High-balance LLPAs on fixed vs ARM?","Do you allow high-balance 2-4 units?","Value acceptance on high-balance?","Do you allow piggyback seconds behind high-balance firsts?","Reserve requirements?","Do you allow manual underwriting on high-balance (usually not)?"],"redFlags":["Loan amount exceeds the county limit for the unit count","Wrong county limit used (Riverside vs San Diego)","ARM LTV above high-balance ARM cap","Cash-out above 80% LTV","2-4 unit LTV above high-balance caps","Reserves too thin for DU","Piggyback second not approved by first-lien lender"],"pricing":"High-balance loans carry added LLPAs in some cases and price differently by investor; compare against jumbo and VA jumbo. Small changes in loan amount can move a file between baseline and high-balance pricing. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Coastal San Diego agent partnerships","Officer and senior civilian buyers","Move-up sellers","2-4 unit urban buyers","CPAs and financial planners"],"checklist":["County limit printout","Income","Assets","Reserves","Credit","DU/LPA","Appraisal","MI cert if applicable","Purchase contract","Insurance","Title","Piggyback docs if any"],"updated":"2026-11"},
"a_conv_cashout":{"matrix":[["Min FICO","DU no hard minimum (Nov 2025) but cash-out LLPAs are steep below 680; lenders overlay 620-660 (lender-specific)"],["Max LTV","Primary 1-unit 80%; primary 2-4 units 75%; second home 75%; investment 1-unit 75%, 2-4 units 70% (verify current matrix)"],["Loan limits","Baseline $832,750; high-cost up to $1,249,125 (high-balance cash-out limits may be lower; verify)"],["Seasoning","Existing first lien must be at least 12 months old (note date to note date) to be paid off with cash-out (Fannie 2023 change; verify Freddie); 6 months on title unless exception"],["Delayed financing","Cash purchases can be refinanced within 6 months under delayed financing exception with documented source of funds"],["DTI/AUS","DU/LPA up to 50%"],["LLPAs","Cash-out LLPA grid by FICO and LTV applies on top of base grid; significant at 75-80% LTV"],["Reserves","DU-determined; more for investment"],["Property types","1-4 units, condos, PUDs; listed properties must be off-market before application"],["Occupancy","Primary, second home, investment"],["Appraisal","Typically required; value acceptance sometimes available for lower LTV"],["Rescission","3-day right for primary residence"],["States","Texas has special rules (not in Steve's states); CA, IL, NV, FL, AZ standard"]],"walkthrough":["Clarify purpose and exact cash needed","Confirm existing first lien seasoning (12 months note to note) and 6 months on title","Compare cash-out against HELOC and against keeping the current low rate","Price cash-out LLPAs at 70%, 75% and 80% LTV","Run DU or LPA","Order appraisal","Compute cash to borrower after payoffs and costs","Disclose; deliver rescission notice for primary residence","Lock at the chosen LTV","Sign; wait out the 3-day rescission","Fund and pay creditors directly where required","Follow up on use of proceeds and future refinance options"],"incomeExample":{"title":"Cash-out vs HELOC comparison, Poway","steps":["Value $1,000,000; current first $420,000 at a low rate from 2021","Cash-out at 75% LTV: new loan $750,000; cash $330,000 minus costs $9,000 = $321,000","Illustrative new P&I $4,800 vs current P&I $1,770; increase $3,030/month","HELOC alternative: $320,000 draw at a variable rate; illustrative interest-only payment $2,400","HELOC keeps the low first-lien rate; total monthly $1,770 + $2,400 = $4,170 vs $4,800","Cash-out LLPA at 75% LTV (illustrative, verify) on $750,000 adds cost"],"result":"HELOC costs less monthly while rates on the first remain low; cash-out wins if the existing rate is near market."},"scenarios":[{"t":"Retiree funding an ADU","who":"Linda, 63, retired Navy Senior Chief, Poway","situation":"Linda wants $300,000 to build a detached ADU for her son's family. Her current first is a 2021 low-rate loan of $420,000. She has pension and VA compensation income and a 760 score.","structure":"Compare HELOC vs conventional cash-out; HELOC likely wins because the first-lien rate is low","numbers":"Value $1,000,000; HELOC $320,000 keeps first intact","why":"Preserves a low-rate first mortgage","alternatives":"VA cash-out (would replace the low rate); construction loan","watch":"Variable HELOC rate risk; ADU permitting timelines"},{"t":"Consolidating debt at 80% LTV","who":"Marcus, 45, logistics manager, Temecula","situation":"Marcus has $65,000 in credit card and personal loans after a failed business. His mortgage rate is close to current market. Score 705.","structure":"Conventional cash-out at 80% LTV","numbers":"Value $700,000; new loan $560,000; existing $430,000; cash about $122,000 after costs","why":"Lowers total monthly payments substantially","alternatives":"FHA cash-out (MIP); HELOC","watch":"Cash-out LLPA at 80% and 705 FICO is meaningful; compare 75% LTV pricing"},{"t":"Delayed financing after cash purchase","who":"Ana, 52, physician, La Jolla","situation":"Ana bought a condo with cash 3 months ago to win the deal. She wants to recoup funds into investments. Delayed financing exception allows it.","structure":"Cash-out under delayed financing","numbers":"Price $900,000; new loan up to 80% = $720,000 (or original purchase price limits)","why":"Recovers cash quickly","alternatives":"Wait 6 months","watch":"Must document source of cash and HUD-1/CD"},{"t":"Investment property cash-out","who":"Rob, 50, Marine veteran and realtor, Oceanside","situation":"Rob owns a rental duplex with large equity. He wants funds for another down payment. Max 70% LTV on 2-4 unit investment.","structure":"Investment cash-out at 70%","numbers":"Value $1,200,000; new loan $840,000 (verify 2-unit limit)","why":"Uses equity to grow portfolio","alternatives":"DSCR cash-out","watch":"Reserves for multiple financed properties"},{"t":"Too soon for cash-out","who":"Kayla, 31, Navy veteran and dental hygienist, Santee","situation":"Kayla bought 9 months ago and wants $50,000 to redo the kitchen. Fannie requires the existing first lien to be at least 12 months old before a cash-out refinance can pay it off. Her home has gained value.","structure":"Wait to the 12-month mark, use a HELOC now, or use a renovation refinance","numbers":"HELOC $50,000 now vs cash-out in 3 months","why":"Avoids an ineligible file and keeps her low purchase rate","alternatives":"VA cash-out (210-day/6 payment seasoning if her loan is VA); HomeStyle refinance","watch":"Seasoning measured note date to note date (verify)"}],"qa":[{"q":"How much cash can I take?","a":"Up to 80% LTV on a 1-unit primary, 75% on 2-4 unit primary and second homes, 75%/70% on investment (verify)."},{"q":"How long must I own the home first?","a":"The existing first lien generally must be 12 months old and you need 6 months on title, with exceptions."},{"q":"Is cash-out better than a HELOC?","a":"If your current first-mortgage rate is low, a HELOC often costs less overall."},{"q":"Can I cash out a rental?","a":"Yes, up to 75% on a 1-unit and 70% on 2-4 units (verify)."},{"q":"What is delayed financing?","a":"A way to recover cash used to buy a home within 6 months."},{"q":"Are there extra fees for cash-out?","a":"Yes, cash-out LLPAs that increase with LTV and lower credit."},{"q":"Can I cancel after signing?","a":"Yes, the 3-day right of rescission applies on a primary residence."},{"q":"Do I need an appraisal?","a":"Usually; value acceptance is sometimes offered at lower LTVs."}],"aeQuestions":["Cash-out LLPAs at 75% vs 80%?","12-month seasoning interpretation?","Delayed financing documentation?","Max cash-out amount caps?","Investment cash-out reserves?","Appraisal waiver availability?","High-balance cash-out LTV?","Turn times?"],"redFlags":["Existing first lien less than 12 months old","Property listed for sale in the last 6 months","Cash purpose unclear or speculative","Replacing a very low first-lien rate without comparing a HELOC","Investment property presented as primary","LTV above product limits","Unpaid tax liens or judgments surfacing on title"],"pricing":"Cash-out carries a separate LLPA grid that can add more than a point at 75-80% LTV with mid-tier credit; dropping LTV by 5% can save materially. Compare blended cost with HELOC options. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Homeowner equity reviews for past clients","ADU builder education","Debt consolidation content with credit counselors","Investor meetups","Retirees planning major projects"],"checklist":["Mortgage statement and note date","Title showing 6 months ownership","Appraisal","Income docs","Asset docs","Payoff letters","Rescission notice","Insurance","Delayed financing docs if applicable","Debt payoff list"],"updated":"2026-11"},
"a_conv_rateterm":{"matrix":[["Min FICO","DU no hard minimum (Nov 2025); LPA 620 (verify); lender overlays 620-640 (lender-specific)"],["Max LTV","97% 1-unit primary when Fannie (or Freddie) owns the existing loan (verify); 95% otherwise; 2-4 units 95% (verify)"],["Cash back","Fannie: lesser of 2% of new loan or $2,000; Freddie: greater of 1% or $2,000 (verify)"],["Eligible payoffs","First lien, purchase-money seconds, HELOCs without draws over $2,000 in last 12 months (verify), co-owner buyout per divorce (Fannie allows as limited cash-out)"],["Seasoning","No seasoning for rate/term in general; title seasoning only for certain cases"],["DTI/AUS","DU/LPA up to 50%"],["LLPAs","Standard purchase/rate-term LLPA grid (lower than cash-out)"],["MI","Required above 80%; new BPMI on new loan"],["Appraisal","Value acceptance often available for rate/term"],["Occupancy","Primary, second home, investment"],["Property types","1-4 units, condos, PUDs"],["States","All"]],"walkthrough":["Gather mortgage statements and determine who owns the loan (Fannie/Freddie lookup)","Decide goal: lower rate, remove MI, remove borrower, change term, combine first and purchase-money second","Check payoff eligibility of second liens and HELOC draw history","Run DU/LPA; check value acceptance","Price at different LTVs","Order appraisal if needed","Disclose; compute recoupment for client","Lock","Close","Calendar MI removal"],"incomeExample":{"title":"Refinance to remove FHA MIP via conventional rate/term","steps":["Current FHA balance $480,000; annual MIP 0.55% = $220/month","New appraised value $640,000; LTV = 75%","Conventional rate/term at 75% LTV: no MI","Illustrative P&I change: +$40/month (similar rate) but MIP removed: net savings $180/month","Closing costs $5,500; breakeven = $5,500 / $180 = 30.6 months"],"result":"Removing MIP pays back in about 2.5 years even without rate improvement."},"scenarios":[{"t":"Dropping FHA MIP after appreciation","who":"Jasmine, 34, Navy veteran and paralegal, Santee","situation":"Jasmine bought with FHA in 2022 before she knew she was VA eligible. Her home has appreciated and her LTV is now about 75%. She pays $220/month in MIP for the life of the loan.","structure":"Conventional rate/term at 75% LTV with no MI","numbers":"Balance $480,000; net savings about $180/month; costs $5,500; breakeven about 31 months","why":"Eliminates life-of-loan MIP at similar rate","alternatives":"VA Type I refinance (no MI, fee exempt if rated)","watch":"Appraisal must support value; compare VA option if disability rated"},{"t":"Combining a first and purchase-money HELOC","who":"Mike, 42, firefighter, Temecula","situation":"Mike bought with an 80/10/10 in 2023 and the HELOC has had no draws since closing. The HELOC rate has stayed high and he wants one fixed payment. His value supports 90% LTV.","structure":"Rate/term refinance combining the first and the purchase-money HELOC","numbers":"First $560,000 + HELOC $70,000 = $630,000 at 90% LTV with BPMI","why":"A purchase-money second payoff stays rate/term, avoiding cash-out pricing","alternatives":"Keep the HELOC and pay it down aggressively","watch":"HELOC draws over $2,000 in the last 12 months would make it cash-out (verify)"},{"t":"Divorce equity buyout as limited cash-out","who":"Sandra, 46, labor and delivery nurse, Escondido","situation":"Sandra's final divorce decree awards her the house and requires a $150,000 equity payment to her former husband. Both are on title and the existing loan. Fannie allows a buyout of a co-owner's equity under a divorce decree to be treated as a limited cash-out refinance (verify).","structure":"Fannie limited cash-out refinance paying the ex-spouse through escrow","numbers":"Value $800,000; payoff $350,000; buyout $150,000; new loan about $505,000 (63% LTV)","why":"Avoids cash-out LLPAs and cash-out LTV limits","alternatives":"Conventional cash-out; VA cash-out if Sandra were a veteran","watch":"Decree must be final and specify the buyout; both parties must have been on title"},{"t":"High-LTV refinance on a Fannie-owned loan","who":"Victor, 31, Marine Sergeant, Oceanside","situation":"Victor bought a condo in 2023 with 3% down using a conventional loan instead of VA. Values in his complex dipped and his LTV is now about 96%. Fannie owns his loan, and rates have dropped about 0.75 point.","structure":"Rate/term refinance up to 97% LTV allowed when Fannie owns the existing loan (verify)","numbers":"Loan $520,000; MI continues; illustrative P&I savings $230/month","why":"Lets him refinance despite thin equity","alternatives":"VA Type I refinance (no MI, uses his entitlement); wait for values to recover","watch":"Confirm Fannie ownership via the loan lookup tool; condo project must still be eligible"},{"t":"Shortening term toward retirement","who":"Linda, 55, retired Navy Chief and GS employee, Murrieta","situation":"Linda has $380,000 left on a 30-year conventional loan. She wants to be debt-free by full federal retirement. Her Navy pension and GS salary easily support a higher payment.","structure":"Rate/term refinance to a 15-year fixed","numbers":"Loan $380,000; payment rises but total interest drops sharply (illustrative)","why":"Matches her retirement timeline","alternatives":"Keep 30-year and prepay; 20-year term","watch":"Closing costs vs flexibility of voluntary prepayment"}],"qa":[{"q":"How much cash can I get on a rate/term refinance?","a":"Fannie allows the lesser of 2% of the new loan or $2,000; Freddie the greater of 1% or $2,000 (verify)."},{"q":"Can I pay off a HELOC?","a":"Yes if it was used to buy the home or had limited draws in the last 12 months (verify)."},{"q":"Can I remove MI by refinancing?","a":"Yes, if the new LTV is 80% or less."},{"q":"Do I need an appraisal?","a":"Sometimes; value acceptance (appraisal waiver) may be offered."},{"q":"Can I remove a borrower?","a":"Yes, if the remaining borrower qualifies alone."},{"q":"Is there a waiting period?","a":"Generally no seasoning for a rate/term refinance."},{"q":"Can I refinance to 97% LTV?","a":"Possibly, if Fannie or Freddie owns your current loan (verify)."},{"q":"Should I refinance FHA to conventional?","a":"Often when LTV is 80% or below, to drop MIP."}],"aeQuestions":["Max LTV if Fannie owns loan?","HELOC draw lookback treatment?","Divorce buyout policy?","Value acceptance eligibility?","LLPAs for rate/term?","MI quotes on 90-97% refi?","Turn times?","Second lien subordination?"],"redFlags":["HELOC draws make the file cash-out","Cash back exceeds rate/term limits","Value too low to remove MI","Recoupment of costs too long for the borrower's plans","Second lien not subordinated","Person on title not on the loan without proper documentation"],"pricing":"Rate/term LLPAs are lower than cash-out, so classify correctly. Compare breakeven of costs vs monthly savings. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["FHA borrowers with appreciation","Past clients with MI","Divorce professionals","Annual mortgage reviews","Agent past-client lists"],"checklist":["Mortgage statements","Loan ownership lookup","HELOC draw history","Appraisal or waiver","Income docs","Assets","Divorce decree if buyout","Title","Payoffs","Insurance"],"updated":"2026-11"},
"a_homestyle":{"matrix":[["Min FICO","DU no hard minimum (Nov 2025); renovation lenders overlay 640-680 (lender-specific)"],["Max LTV","97% 1-unit primary purchase (HomeReady or first-time buyer standard); 95% otherwise; 85% second home; 85% investment purchase (verify)"],["Renovation cap","Purchase: renovation costs up to 75% of the lesser of (price + renovation) or as-completed value; refinance: 75% of as-completed value; manufactured homes 50% of as-completed value or $50,000 (verify)"],["Loan limits","Baseline $832,750 / high-cost up to $1,249,125"],["Eligible work","Any renovation that is permanently affixed and adds value: kitchens, additions, ADUs, pools, landscaping, energy, disaster repairs; luxury allowed"],["Contingency","Up to 15% of costs may be financed; required for older homes or structural (lender-specific)"],["Payment reserve","Up to 6 months PITI when home is uninhabitable"],["Completion","Work completed within 15 months of closing (verify)"],["Consultant/inspector","HUD consultant not required; lender may require inspector or consultant for larger projects"],["DIY","Limited DIY up to 10% of as-completed value for 1-unit (verify)"],["Occupancy","Primary, second home, investment (1-unit)"],["MI","Standard conventional MI based on LTV"],["Appraisal","As-completed value based on plans and specs"],["States","All"]],"walkthrough":["Define scope with contractor and get detailed bids","Confirm renovation cap (75% rule)","Run DU with total loan","Order as-completed appraisal","Approve contractor","Set contingency and payment reserve","Close; renovation funds held in custodial account","Draw schedule with inspections","Change orders approved","Completion certificate","Final draw and title update","Remove MI later when LTV drops"],"incomeExample":{"title":"HomeStyle max loan, Clairemont","steps":["Price $850,000; renovation $180,000 (kitchen, ADU conversion); contingency 10% = $18,000","Total cost = $1,048,000","As-completed value $1,150,000","75% renovation cap test: $198,000 / $1,048,000 = 18.9% (OK)","Max LTV 95% (not first-time) x lesser of $1,048,000 and $1,150,000 = $995,600","Must be within San Diego high-balance limit (verify); down payment $52,400"],"result":"Loan of about $995,600 fits if under the county limit; renovation share is far below 75%."},"scenarios":[{"t":"Clairemont kitchen and garage ADU","who":"Aaron, 38, Navy Commander, Clairemont","situation":"Aaron is buying a dated 1958 home near MCAS Miramar and wants to convert the garage into an ADU for rental income later. He has used his VA entitlement on a home in Virginia. He has $120,000 saved and a 770 score.","structure":"Fannie HomeStyle purchase with renovation, 95% LTV","numbers":"Price $850,000; renovation $198,000 incl. contingency; loan about $995,600 (verify county limit)","why":"One loan for purchase and renovation including ADU; luxury and ADU work allowed","alternatives":"FHA 203(k) Standard (FHA limit too low); VA renovation (entitlement in use)","watch":"ADU permits in San Diego; appraiser's as-completed value"},{"t":"Pool and drought-tolerant landscaping","who":"Rebecca, 44, dentist, Escondido","situation":"Rebecca is buying a 1990s home with a bare backyard and wants a pool and drought-tolerant landscaping. FHA 203(k) does not allow pools. She has 20% down and a 790 score.","structure":"HomeStyle purchase with pool and landscaping scope","numbers":"Price $900,000; renovation $95,000; as-completed value supports total","why":"Luxury items like pools are eligible under HomeStyle","alternatives":"HELOC after closing; cash","watch":"Appraiser must support value added by the pool"},{"t":"Wildfire hardening for insurability","who":"Jim, 58, retired Marine and general contractor, Julian","situation":"Jim's insurer warned it will non-renew unless he adds ember-resistant vents, a Class A roof and defensible space work. He has strong equity. He prefers one fixed loan over a HELOC.","structure":"HomeStyle refinance funding resiliency work","numbers":"Value as-completed $700,000; renovation $60,000","why":"Resiliency upgrades are eligible and may preserve insurability","alternatives":"CHOICERenovation; HELOC","watch":"Insurance market in high fire-risk zones; contractor must be licensed even though Jim is a contractor (DIY limits)"},{"t":"First-time buyer at 97% with updates","who":"Lena, 29, special education teacher, Lemon Grove","situation":"Lena qualifies for HomeReady and wants to update a bathroom and replace flooring before moving in. She has 3% down and a 705 score. Turnkey homes are out of her budget.","structure":"HomeStyle with HomeReady at 97% LTV","numbers":"Price $520,000; renovation $45,000 including contingency","why":"Low down payment with reduced MI coverage","alternatives":"FHA 203(k) Limited","watch":"Contractor reliability and draw timing"},{"t":"Refreshing a rental before leasing","who":"Paul, 50, Navy veteran and investor, Vista","situation":"Paul is buying a dated single-family home to rent out. It needs paint, flooring and a kitchen refresh before it can command market rent. Hard money would mean two closings and higher cost.","structure":"HomeStyle investment purchase at 85% LTV","numbers":"Price $600,000; renovation $70,000","why":"One closing for purchase and rehab at agency pricing","alternatives":"Hard money then refinance; DSCR","watch":"Investment LLPAs; rent schedule based on as-completed condition"}],"qa":[{"q":"What can I renovate?","a":"Almost anything permanently attached that adds value, including pools, landscaping and ADUs."},{"q":"How much can renovation costs be?","a":"Up to 75% of the lesser of price plus renovation or as-completed value."},{"q":"Do I need a HUD consultant?","a":"No, though lenders may require inspections or a consultant on larger projects."},{"q":"How long do I have to finish?","a":"Generally 15 months from closing (verify)."},{"q":"Can I do some work myself?","a":"Limited DIY may be allowed on 1-unit homes with lender approval."},{"q":"Can I use HomeStyle on a rental?","a":"Yes, on 1-unit investment properties."},{"q":"Is MI required?","a":"Yes above 80% LTV, based on the total loan."},{"q":"Can I refinance with HomeStyle?","a":"Yes, renovation can be added to a rate/term refinance."},{"q":"Can I combine with HomeReady?","a":"Yes, for 97% LTV on eligible 1-unit primaries."}],"aeQuestions":["Min FICO for HomeStyle?","Do you allow ADU construction?","Draw process and fees?","Contingency requirements?","Consultant required above what amount?","High-balance HomeStyle allowed?","DIY policy?","Investment property allowed?"],"redFlags":["Contractor unlicensed or uninsured","Renovation scope exceeds the 75% cap","Permits not obtainable in the borrower's timeline","Borrower overextended by total payment after renovation","Completion timeline unrealistic for scope","As-completed value depends on unpermitted work"],"pricing":"HomeStyle carries renovation pricing adjustments and administration fees; MI follows LTV. Compare with FHA 203(k) for lower credit and with HELOC for small projects. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Architects and designers","ADU builders (no referral fees)","Agents with dated listings","Wildfire hardening contractors","Investor groups"],"checklist":["Plans and specs","Contractor bid","Contractor license/insurance","As-completed appraisal","Renovation contract","Draw schedule","Contingency calc","Permits","Income docs","Assets","Insurance","Completion certificate"],"updated":"2026-11"},
"a_choicereno":{"matrix":[["Min FICO","LPA 620 (verify); renovation overlays 660-700 (lender-specific)"],["Max LTV","97% 1-unit primary with Home Possible/HomeOne; 95% standard; second homes and investment lower (verify)"],["Renovation cap","Purchase: up to 75% of the lesser of (price + renovation) or as-completed value; refinance: 75% of as-completed value"],["CHOICEReno eXPress","Smaller projects: up to 10% of as-completed value (15% in Duty-to-Serve high-needs rural areas) with simpler documentation (verify)"],["Eligible work","Remodels, additions, ADUs, disaster resiliency (fire-hardening, seismic retrofit), energy upgrades, luxury items"],["Completion","Generally within 365 days (verify)"],["Contingency","Lender-specific, often 10-15%"],["Payment reserve","Allowed if uninhabitable (verify)"],["DIY","Limited"],["Loan limits","Baseline/high-cost limits"],["MI","Standard conventional MI"],["Occupancy","Primary, second home, investment"],["States","All"]],"walkthrough":["Decide between full CHOICERenovation and CHOICEReno eXPress based on scope size","Get detailed licensed contractor bids with line items, schedule and lien-waiver process","Compute the renovation cap: 75% of the lesser of price plus renovation or as-completed value (10%/15% for eXPress)","Run LPA with the total loan amount and confirm Home Possible or HomeOne eligibility for 97%","Order an as-completed appraisal from plans and specs","Approve the contractor and renovation contract with the lender","Set contingency and, if needed, payment reserves","Close; renovation funds go to a custodial account","Process draws with inspections and conditional lien waivers","Approve change orders in writing before work proceeds","Final inspection and completion certificate within the deadline","Final draw, title date-down and any unused funds applied to principal","Calendar MI removal review based on as-completed value"],"incomeExample":{"title":"CHOICEReno eXPress cap, Riverside","steps":["As-completed value $600,000","eXPress cap 10% = $60,000","Planned work: roof $22,000, flooring $14,000, paint $8,000 = $44,000","Purchase price $540,000 + $44,000 = $584,000; 97% (Home Possible) = $566,480","Down payment $17,520"],"result":"Fits eXPress cap; simpler docs than full CHOICERenovation."},"scenarios":[{"t":"Riverside roof and flooring with eXPress","who":"Daisy, 30, Navy veteran and medical biller, Riverside","situation":"Daisy's VA entitlement is tied up in a rental near Camp Pendleton. The Riverside home she likes needs a roof and new flooring before her insurer will write a policy. She qualifies for Home Possible and has 3% down.","structure":"CHOICEReno eXPress with Home Possible at 97% LTV","numbers":"Price $540,000; work $44,000; loan $566,480; down $17,520","why":"Simpler documentation for a small scope with a low down payment","alternatives":"FHA 203(k) Limited; Fannie HomeStyle","watch":"eXPress cap of 10% of as-completed value; roof must be completed promptly for insurance"},{"t":"Seismic retrofit on a 1925 craftsman","who":"Martin, 47, structural engineer, North Park (San Diego)","situation":"Martin bought a 1925 craftsman on a raised foundation and wants foundation bolting and cripple-wall bracing. His earthquake insurer offers a premium discount after retrofit. He'd rather not use a variable-rate HELOC.","structure":"CHOICERenovation rate/term refinance including resiliency work","numbers":"Value as-completed $1,050,000; renovation $75,000; within San Diego high-balance limit (verify)","why":"Freddie explicitly allows resiliency improvements and one fixed loan covers the work","alternatives":"HomeStyle refinance; HELOC; California Earthquake Brace + Bolt grant for part of cost","watch":"Permits and engineer letter; grant timing if combining"},{"t":"Detached ADU for aging parents","who":"Grace, 52, retired Navy Chief, Chula Vista","situation":"Grace wants to build a detached ADU so her parents can move in from the Philippines. She has substantial equity and a 760 score. The ADU should raise her home's value.","structure":"CHOICERenovation refinance with ADU construction","numbers":"As-completed value $1,100,000; renovation $220,000 including contingency","why":"ADU construction is eligible with as-completed value support","alternatives":"Construction loan then refinance; cash-out refinance","watch":"ADU permit timeline and appraiser's ability to value ADUs in the neighborhood"},{"t":"Hurricane repairs plus shutters in Florida","who":"Ken, 60, retired Navy pilot, Pensacola FL","situation":"Ken's home was damaged in a hurricane and insurance will pay part of the repair. He wants to finance the remainder and add impact windows and shutters. He has good credit and 35% equity.","structure":"CHOICERenovation refinance with resiliency upgrades","numbers":"Renovation $90,000; insurance proceeds $55,000 applied","why":"Combines disaster repair and mitigation in one loan","alternatives":"FHA 203(h) or 203(k) disaster options; SBA disaster loan","watch":"Coordinate insurance proceeds with draws; wind mitigation report may lower premiums"},{"t":"High-needs rural area with eXPress 15%","who":"Lisa, 35, nurse, Brawley","situation":"Lisa is buying in Imperial County where the property may sit in a Duty-to-Serve high-needs rural area. She needs HVAC and windows to survive summer heat. Her income fits Home Possible.","structure":"CHOICEReno eXPress at the 15% cap (verify area eligibility)","numbers":"As-completed $400,000; cap $60,000; planned work $38,000","why":"Higher eXPress cap in high-needs areas","alternatives":"USDA purchase plus Section 504 later; FHA 203(k) Limited","watch":"Verify area designation before quoting the 15% cap"}],"qa":[{"q":"What is CHOICEReno eXPress?","a":"A streamlined version for smaller projects, capped at 10% of as-completed value (15% in certain high-needs rural areas)."},{"q":"Can I build an ADU?","a":"Yes, ADUs are eligible if the appraisal supports the as-completed value."},{"q":"Can I fund disaster resiliency work?","a":"Yes, Freddie specifically supports items like seismic retrofits, fire hardening and wind mitigation."},{"q":"How long do I have to finish?","a":"Generally within a year of closing (verify with lender)."},{"q":"Can I combine with Home Possible for 3% down?","a":"Yes on eligible 1-unit primary residences."},{"q":"Is a renovation consultant required?","a":"Not by Freddie; lenders may require one for large projects."},{"q":"Can I use it to refinance?","a":"Yes, renovation can be added to a rate/term refinance up to 75% of as-completed value."},{"q":"Are luxury items like pools allowed?","a":"Yes, if they are permanently affixed and add value."},{"q":"Who pays the contractor?","a":"The lender releases draws after inspections."}],"aeQuestions":["Do you offer both CHOICERenovation and CHOICEReno eXPress?","Minimum FICO and max DTI for renovation loans?","Do you finance detached ADU construction?","How many draws and how fast are they paid?","Required contingency percentage?","How do you verify Duty-to-Serve high-needs area eligibility?","Completion deadline and extension policy?","Investment and second-home renovations allowed?","Do you require a consultant above a certain amount?"],"redFlags":["Renovation exceeds the 75% cap or the eXPress cap","Contractor lacks a license or adequate insurance","As-completed value doesn't support the loan","Permits not obtainable or jurisdiction backlog","Insurance carrier won't bind until repairs are done","Completion timeline unrealistic for scope","Borrower plans substantial DIY work"],"pricing":"CHOICERenovation pricing includes renovation adjustments and admin fees; eXPress may be simpler and cheaper. Compare with HomeStyle and 203(k). Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Seismic and fire-hardening contractors (education; no referral fees)","ADU builders and architects","Disaster recovery organizations and insurance adjusters","Agents listing dated or damaged homes","First-time buyers open to fixer-uppers"],"checklist":["Contractor bid","License/insurance","As-completed appraisal","Renovation agreement","Draw schedule","Permits","Income","Assets","Insurance","Completion certificate"],"updated":"2026-11"},
"a_choicehome_mha":{"matrix":[["Programs","Fannie MH Advantage and Freddie CHOICEHome: HUD-code factory-built homes with site-built-like features, financed and appraised like site-built homes"],["Min FICO","DU no hard minimum (Nov 2025) / LPA 620 (verify); lenders overlay 620-660 (lender-specific)"],["Max LTV","Up to 97% 1-unit primary (HomeReady/Home Possible or first-time buyer); standard MH loans capped lower (95% Fannie standard MH; verify)"],["Required features","Architectural: roof pitch and eaves, garage or carport, porch, durable siding, energy efficiency; MH Advantage sticker or CHOICEHome certification from manufacturer"],["LLPAs/MI","MH Advantage exempt from the standard manufactured-home LLPA (verify) and receives MI pricing similar to site-built"],["Appraisal","Appraiser may use site-built comparables when MH Advantage/CHOICEHome comps are scarce"],["Foundation/real property","Permanent foundation and titled as real property; land owned or acceptable leasehold"],["Loan limits","Baseline/high-cost conforming limits"],["Occupancy","Primary, second home (verify for MH Advantage)"],["Construction","New homes; single-close construction-to-perm available from some lenders"],["Residency","Non-permanent residents eligible under GSE rules"],["States","Available where certified homes are sold; CA, NV, AZ, FL have active retailers"]],"walkthrough":["Confirm the model is MH Advantage or CHOICEHome certified (sticker or manufacturer certificate)","Confirm land ownership or an acceptable leasehold","Run DU or LPA with HomeReady/Home Possible if income qualifies","Price without the standard MH LLPA and quote site-built-style MI","Coordinate retailer contract, delivery and installer schedule","Arrange single-close construction-to-perm if the home isn't installed yet","Order appraisal; confirm appraiser may use site-built comps if needed","Obtain foundation engineer certification","Complete real property conversion and surrender title","Close and fund (or convert construction loan to permanent)","Final inspection and certificate of occupancy","Calendar MI removal review"],"incomeExample":{"title":"MH Advantage vs standard MH cost comparison, Lake Elsinore","steps":["Home and land $450,000; 5% down; loan $427,500","Standard MH LLPA (illustrative 0.50%, verify) = $2,138","MH Advantage avoids MH LLPA: $0","MI: standard MH MI may be higher; MH Advantage MI similar to site-built","Monthly savings from MI (illustrative) $30"],"result":"MH Advantage saves upfront LLPA and some monthly MI cost."},"scenarios":[{"t":"New factory-built home on family land","who":"Rosa, 41, school counselor, Aguanga","situation":"Rosa inherited a 2-acre parcel and wants a new factory-built home with a garage and covered porch. The retailer offers an MH Advantage certified model. She has 5% down and a 700 score.","structure":"Fannie MH Advantage with single-close construction-to-permanent financing (lender-specific)","numbers":"Home and site work $380,000; land value $120,000 counts toward equity","why":"Site-built-like pricing and appraisal treatment","alternatives":"FHA Title II; USDA for a new manufactured unit","watch":"Retailer certification sticker and installer schedule"},{"t":"Retired Chief buying in a new factory-built subdivision","who":"Bill, 64, retired Navy Chief, Hemet","situation":"Bill wants a single-story CHOICEHome-certified home on an owned lot in a new subdivision. He has pension and VA compensation income and 20% down. He doesn't want a park with space rent.","structure":"Freddie CHOICEHome at 80% LTV, no MI","numbers":"Price $420,000; loan $336,000","why":"Financed and appraised like site-built, with site-built comps allowed","alternatives":"VA purchase (fee exempt with compensation, 0% down)","watch":"Compare VA fee-exempt option; confirm certification"},{"t":"First-time buyer with 3% down in Arizona","who":"Jade, 28, retail store manager, Bullhead City AZ","situation":"Jade's income is under 80% AMI and she has $10,000 saved. The local retailer sells MH Advantage models on owned lots. She wants to stop paying rising rent.","structure":"MH Advantage at 97% with HomeReady","numbers":"Price $310,000; down $9,300","why":"Low down payment with reduced MI coverage","alternatives":"FHA Title II","watch":"Income must stay under AMI; homeownership education"},{"t":"Home lacks the required features","who":"Ron, 50, diesel mechanic, Hesperia","situation":"Ron picked a manufactured model without eaves, a garage or porch. It doesn't qualify for MH Advantage. He has 5% down.","structure":"Fannie standard manufactured home loan (MH LLPA applies)","numbers":"Price $290,000; loan $275,500","why":"Still conventional financing, just priced as standard MH","alternatives":"Upgrade to an MH Advantage model; FHA Title II","watch":"Standard MH LLPA and MI cost vs upgrade cost"},{"t":"Second home at the lake","who":"Carol, 59, nurse, Lake Havasu City AZ","situation":"Carol owns her primary in Temecula and wants a certified factory-built home near the lake. She has 10% down. She will use it for weekends and vacation.","structure":"MH Advantage as a second home (verify eligibility with lender)","numbers":"Price $350,000; loan $315,000","why":"Site-built pricing treatment if eligible","alternatives":"Conventional standard MH second home; cash","watch":"Second-home occupancy rules and LLPAs"}],"qa":[{"q":"What makes a home MH Advantage or CHOICEHome?","a":"A HUD-code factory-built home with site-built features like eaves, roof pitch, garage or carport and porch, certified by the manufacturer."},{"q":"Is pricing better than a standard manufactured home loan?","a":"Often, because the standard MH LLPA doesn't apply and MI is priced like site-built (verify)."},{"q":"Can I put 3% down?","a":"Yes, with HomeReady, Home Possible or as a first-time buyer on 1-unit primary."},{"q":"Does it need a permanent foundation?","a":"Yes, with an engineer's certification."},{"q":"Do I have to own the land?","a":"Owned land or an acceptable leasehold is required."},{"q":"Can the appraiser use site-built comparables?","a":"Yes, when certified-home comps are scarce."},{"q":"Is CHOICEHome the same as MH Advantage?","a":"CHOICEHome is Freddie Mac's version with similar goals."},{"q":"Can I finance construction and the home together?","a":"Some lenders offer single-close construction-to-permanent financing."}],"aeQuestions":["Do you lend on MH Advantage and CHOICEHome?","Do you offer single-close construction-to-perm?","Minimum FICO overlay for factory-built homes?","Do you allow leasehold land?","Will your appraisers use site-built comparables?","Which MI companies price MH Advantage like site-built?","How do you verify the certification sticker?","Second-home eligibility?"],"redFlags":["Home lacks the MH Advantage sticker or CHOICEHome certification","No permanent foundation or engineer certification","Title not converted to real property","Land lease not acceptable to the lender","Appraiser lacks comparable sales and refuses site-built comps","Retailer delivery and installation delays threaten lock","Chattel lien on a resale home"],"pricing":"MH Advantage/CHOICEHome avoid some MH-specific pricing; compare against FHA and standard MH. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["MH retailers and factory-built subdivision developers (education; no referral fees)","Rural landowners in Riverside and San Bernardino counties","First-time buyers priced out of site-built homes","Veteran retirees seeking single-story homes","Content explaining MH Advantage vs standard MH vs FHA Title II"],"checklist":["Certification sticker","Foundation cert","Real property conversion","Land deed","Appraisal","Income","Assets","Construction docs","Insurance","Title"],"updated":"2026-11"},
"a_refinow":{"matrix":[["Programs","Fannie RefiNow and Freddie Refi Possible: limited cash-out refinances for lower-income owners whose loan is owned by that GSE; still listed by lenders in 2026 (verify current status)"],["Income limit","Qualifying income at or below 100% of AMI for the property location"],["Loan ownership","Existing loan must be owned by Fannie (RefiNow) or Freddie (Refi Possible); not in MBS of the other GSE"],["Min FICO","No minimum credit score (verify); lender overlays may apply"],["Max LTV","97% (verify)"],["DTI","Up to 65% (verify)"],["Benefit test","Rate reduction at least 50 bps and monthly payment reduction at least $50 (P&I plus MI)"],["Payment history","No 30-day lates in prior 6 months and no more than one in 12 months"],["Appraisal credit","$500 credit to borrower if an appraisal is required (verify)"],["LLPA","Upfront 0.50% adverse market fee waived; LLPAs waived for loans up to $300,000 (verify)"],["Seasoning","Existing loan at least 12 months old"],["Occupancy","1-unit primary residence"],["States","All"]],"walkthrough":["Look up loan ownership with Fannie's and Freddie's loan lookup tools","Pull the AMI for the property and compare qualifying income to 100% AMI","Review the last 12 months of mortgage payments (0x30 in 6 months, max 1x30 in 12)","Confirm the existing loan is at least 12 months old","Price the new loan and test rate reduction of at least 50 bps","Test monthly payment reduction of at least $50 (P&I plus MI)","Run DU or LPA; confirm DTI at or under 65%","Order appraisal only if required; apply the $500 appraisal credit if so","Disclose and explain any fee waivers","Lock and close; deliver rescission notice if applicable","Confirm the new payment and escrow with the borrower after first statement"],"incomeExample":{"title":"RefiNow eligibility test, Hemet","steps":["Property AMI (illustrative) $95,000; borrower income $82,000 (under 100%)","Current P&I $2,210; new P&I illustrative $1,990","Rate reduction 0.75 point (meets 0.50 minimum)","Payment reduction $220 (meets $50 minimum)","DTI 58% (under 65% cap)"],"result":"Eligible on income, benefit and DTI tests."},"scenarios":[{"t":"Lower-income owner with high DTI","who":"Carmen, 52, home health aide, Hemet","situation":"Carmen earns $46,000 and her DTI is 58% because of a car loan and medical payments. Her Fannie-owned loan rate is about 0.75 point above market. A standard refinance would fail a 50% DTI limit.","structure":"Fannie RefiNow","numbers":"Current P&I $1,650; new illustrative $1,500; savings $150/month","why":"DTI up to 65% allowed and fees reduced","alternatives":"FHA streamline not available (conventional loan)","watch":"Income under 100% AMI; clean 6-month payment history"},{"t":"Freddie-owned loan, Refi Possible","who":"Jamal, 38, warehouse lead, Moreno Valley","situation":"Jamal's loan is owned by Freddie Mac. His income is under area median and he has 14 months of on-time payments. He needs breathing room after a new baby.","structure":"Freddie Refi Possible","numbers":"Illustrative savings $120/month","why":"Program designed for his loan and income profile","alternatives":"Standard rate/term refinance (higher fees)","watch":"Confirm Freddie ownership with the lookup tool"},{"t":"Appraisal credit offsets cost","who":"Linda, 60, school custodian, El Centro","situation":"Linda's lender's AUS requires an appraisal. Her income is $40,000 and her rate would drop about 0.6 point. She worried the appraisal fee would wipe out savings.","structure":"RefiNow with the $500 appraisal credit (verify)","numbers":"Savings about $90/month; appraisal cost largely offset","why":"Credit reduces out-of-pocket cost","alternatives":"Wait for a larger rate drop","watch":"Payment must still fall at least $50"},{"t":"Recent late payment blocks eligibility","who":"Ray, 44, line cook, Victorville","situation":"Ray had a 30-day late four months ago after a bank account issue. RefiNow requires no 30-day lates in the last six months. Otherwise he meets the income and loan-ownership tests.","structure":"Wait two more months, then RefiNow","numbers":"Eligibility returns after 6 clean months","why":"Avoids a declined application and extra credit pulls","alternatives":"FHA refinance not available without FHA loan; standard refi also needs clean history","watch":"Set an autopay reminder; re-check date eligibility"},{"t":"Income above the limit","who":"Sara, 39, civil engineer, San Diego","situation":"Sara's income of $165,000 exceeds 100% AMI for her tract. Her loan is Fannie-owned. She asked about RefiNow after reading about it online.","structure":"Standard conventional rate/term refinance","numbers":"Compare costs against expected savings and breakeven","why":"Program has an income cap","alternatives":"Wait for larger rate improvement","watch":"Don't misstate income to fit a program"}],"qa":[{"q":"How much must my payment and rate drop?","a":"The rate must drop at least 50 basis points and the monthly payment at least $50."},{"q":"Is there help with the appraisal cost?","a":"If an appraisal is required, the borrower receives a $500 credit (verify)."},{"q":"What is the DTI limit?","a":"Up to 65%, much higher than a standard refinance (verify)."},{"q":"Can I take cash out?","a":"No, it's a limited cash-out refinance with only small incidental cash allowed."},{"q":"Is RefiNow still available in 2026?","a":"Lenders still list it, but availability varies; confirm with the lender before quoting."},{"q":"My loan is owned by Freddie Mac. What then?","a":"Use Freddie Refi Possible, which has similar terms."},{"q":"How long must I have had my loan?","a":"At least 12 months."},{"q":"Does my spouse's income count toward the limit?","a":"Only qualifying income of borrowers on the loan is compared to AMI."}],"aeQuestions":["Do you still offer RefiNow and Refi Possible in 2026?","Any minimum FICO overlay?","Do you allow DTI up to 65%?","How is the $500 appraisal credit applied on the CD?","Which fee waivers apply and at what loan size?","Turn time for these files?","How do you verify GSE ownership?","Do you allow borrower removal on RefiNow?"],"redFlags":["Existing loan is not owned by the matching GSE","Qualifying income over 100% AMI","A 30-day late in the last 6 months","Payment reduction under $50 after costs","Borrower expects cash out","Lender has quietly stopped offering the program"],"pricing":"RefiNow/Refi Possible pricing benefits from waived fees for eligible loans; compare with standard rate/term if income is near the limit. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Nonprofit credit and housing counselors","Past clients with Fannie or Freddie loans and modest incomes","Community organizations in Inland Empire and Imperial County","Content explaining the 100% AMI test and $50 benefit","Employer financial wellness for hourly workforces"],"checklist":["Loan ownership lookup","Income docs","AMI lookup","Payment history","Benefit worksheet","Appraisal or waiver","Title","Insurance","Payoff","ID"],"updated":"2026-11"},
"a_conv_mi":{"matrix":[["When required","Any conventional loan over 80% LTV (GSE charter requirement)"],["Standard coverage","95.01-97%: 35%; 90.01-95%: 30%; 85.01-90%: 25%; 80.01-85%: 12% (HomeReady/Home Possible 25% at 95.01-97 and lower tiers; verify)"],["BPMI (monthly)","Borrower-paid monthly; cancel on request at 80% of original value with good history; automatic at 78% scheduled (HPA); final termination at midpoint"],["LPMI","Lender-paid via higher rate; cannot be cancelled; good for short holds or high-income tax situations (verify deductibility)"],["Single premium","Paid upfront (by borrower, seller or lender credit) or financed; non-refundable (refundable versions rare)"],["Split premium","Partial upfront plus reduced monthly"],["Pricing drivers","FICO, LTV, DTI over 45%, number of borrowers, loan term, property type (condo), investment; each MI company uses rate cards or risk-based engines"],["MI companies","MGIC, Radian, Essent, Enact, Arch, National MI"],["Credit score model","VantageScore 4.0 acceptance by MI companies varies (verify)"],["Removal by appraisal","Borrower can request removal with new appraisal after 2 years at 75% LTV or 5 years at 80% (Fannie servicing; verify)"],["Occupancy","Primary, second home, investment (MI more expensive)"],["States","All"]],"walkthrough":["Quote monthly BPMI from at least two MI companies or risk-based engines","Price the LPMI option (rate increase) at the same lock","Price single premium both borrower-paid and funded by lender or seller credit","Price split premium if available","Compute breakeven months for each option against expected hold","Check seller concession limits for single premium funding","Present options side by side in writing with cancellation rules","Borrower selects; document the choice","Order MI certificate after approval","Close and confirm MI on the CD","Track the 80% request date and 78% automatic termination","Remind borrower when appreciation may allow appraisal-based removal"],"incomeExample":{"title":"Single premium vs BPMI breakeven, Murrieta","steps":["Loan $600,000 at 95% LTV; FICO 740","BPMI illustrative 0.45% annual = $225/month","Single premium illustrative 1.75% = $10,500 upfront","Breakeven = $10,500 / $225 = 46.7 months","If expected to remove MI in 5 years via appreciation or hold < 4 years, BPMI wins"],"result":"Single premium only wins if the borrower keeps the loan and MI would last beyond about 47 months."},"scenarios":[{"t":"Seller-paid single premium","who":"Andrea, 33, Navy veteran and teacher, Murrieta","situation":"Andrea is buying with 5% down because her VA entitlement is tied up in a rental near Camp Lejeune. The seller agreed to a $12,000 credit. She plans to stay at least 7 years.","structure":"Use the seller credit to pay a borrower-paid single premium","numbers":"Loan $600,000; single premium about $10,500 covered by the seller (illustrative)","why":"No monthly MI for the life of the loan at no out-of-pocket cost","alternatives":"Monthly BPMI with the credit applied to closing costs","watch":"Single premium is non-refundable if she refinances or sells early"},{"t":"Short expected hold","who":"Mark, 37, Navy Lieutenant Commander, Coronado","situation":"Mark expects to PCS within 3 years and sell. He has 10% down and a 760 score. A single premium would cost more than 3 years of monthly MI.","structure":"Monthly BPMI","numbers":"About $110/month (illustrative) for an expected 36 months","why":"Pays only while he holds the loan","alternatives":"Single premium (breakeven too long); 20% down (drains reserves)","watch":"If orders slip and he keeps it, request cancellation at 80%"},{"t":"DTI above 45% raises MI","who":"Tara, 29, nurse, Escondido","situation":"Tara's DTI is 48%. Several MI rate cards add cost when DTI exceeds 45%. Her loan officer had only quoted one MI company.","structure":"Shop at least three MI companies or risk-based engines","numbers":"Quote spread of about $40/month between providers (illustrative)","why":"Same loan, lower MI by shopping","alternatives":"Pay down a card to get DTI under 45%; FHA","watch":"Ensure the lender can deliver with the cheaper MI company"},{"t":"Lender-paid MI for a short horizon","who":"Rick, 45, surgeon, La Jolla","situation":"Rick prefers no separate MI line and expects to refinance or sell within 5 years. He has 12% down. He understands LPMI can't be cancelled.","structure":"LPMI built into the rate","numbers":"Rate slightly higher; no monthly MI","why":"Simplicity for a short hold","alternatives":"BPMI (cancellable); single premium","watch":"If he keeps the loan long term, LPMI can cost more"},{"t":"Removing MI with appreciation","who":"Jen, 35, engineer, Temecula","situation":"Jen bought 3 years ago with 5% down and paid down some principal. Home values rose and a broker price opinion suggests about 74% LTV. Her servicer allows removal with a new appraisal after 2 years at 75% LTV (verify).","structure":"Servicer-ordered appraisal for MI removal","numbers":"MI savings about $180/month (illustrative)","why":"Cancels MI without refinancing","alternatives":"Refinance to a new loan at 80% or lower","watch":"Servicer rules, payment history and appraisal cost"}],"qa":[{"q":"When can I remove BPMI?","a":"You can request removal at 80% of original value with a good payment history; it ends automatically at 78% of the original value on the amortization schedule."},{"q":"Can lender-paid MI be cancelled?","a":"No, LPMI is built into the rate for the life of the loan."},{"q":"Can the seller pay my MI?","a":"Yes, a single premium can be paid with seller concessions within limits."},{"q":"Which MI type is cheapest?","a":"It depends on how long you keep the loan and your credit profile; compute the breakeven."},{"q":"Does MI protect me?","a":"No, it protects the lender if you default."},{"q":"Can rising home values remove MI?","a":"Often yes with a new appraisal after a waiting period, per servicer rules."},{"q":"Does a high DTI raise MI cost?","a":"Yes, many rate cards add cost above 45% DTI."},{"q":"Is MI tax deductible?","a":"Rules have changed over time; check current tax law with a tax professional (verify)."},{"q":"Can I pick the MI company?","a":"Usually the lender chooses among approved companies, but brokers can compare."}],"aeQuestions":["Which MI companies and engines do you use?","Can we choose the lowest-cost MI provider?","Do you offer borrower-paid single premium financed?","Is split premium available?","How is LPMI priced relative to BPMI?","Any refundable single premium options?","Do MI companies accept VantageScore 4.0 on your loans?","What is your servicer's appraisal-based MI removal process?"],"redFlags":["Single premium chosen with a short expected hold","LPMI chosen without explaining it can't be cancelled","Only one MI quote obtained","DTI just above a rate-card tier not addressed","Seller concessions exceed limits once single premium is added","Borrower believes MI protects them"],"pricing":"MI is priced by each MI company; comparing two or three can save meaningful dollars. Compute breakeven vs hold time. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["First-time buyer classes covering MI myths","Agents writing offers with seller-paid MI","Content comparing BPMI, LPMI and single premium","Past clients nearing 80% LTV","Military buyers preserving VA entitlement"],"checklist":["MI quotes","Breakeven worksheet","MI certificate","Seller concession calc","Disclosure of cancellation rights","Income","Credit","Appraisal","Purchase contract","Servicer removal request info"],"updated":"2026-11"},
"a_conv_secondhome":{"matrix":[["Min FICO","DU no hard minimum (Nov 2025)/LPA 620 (verify); second-home overlays 680+ common (lender-specific)"],["Max LTV","90% purchase and rate/term; 75% cash-out (verify)"],["Units","1-unit only"],["Occupancy","Borrower occupies part of the year; must be suitable for year-round use; borrower has exclusive control (no rental pools or timeshares)"],["Rental use","May be rented occasionally, but rental income cannot be used to qualify (Fannie); property management agreements that give control to others not allowed"],["Location","Reasonable distance from primary (lender judgment); resort/vacation areas common"],["LLPAs","Second-home LLPAs added by LTV (FHFA 2022 fee schedule; verify current)"],["Reserves","DU-determined; often 2+ months"],["DTI","Both housing payments count"],["MI","Required over 80%"],["Loan limits","Baseline/high-cost"],["States","All"]],"walkthrough":["Confirm the property will be a genuine second home with year-round access","Discuss distance from the primary and planned personal use","Clarify any rental intentions; rental income can't be used to qualify","Run DU or LPA including both housing payments","Price second-home LLPAs at 80%, 85% and 90% LTV","Document reserves for both properties","Order appraisal; check condo or resort project eligibility","Sign the second-home rider and occupancy certification","Bind insurance appropriate for the area (wildfire, wind, flood)","Close and fund","Follow up annually on use and refinance opportunities"],"incomeExample":{"title":"Second home DTI with two mortgages, Big Bear","steps":["Primary PITI $3,800; second home PITI $2,600","Other debts $500","Income $15,000","DTI = ($3,800 + $2,600 + $500) / $15,000 = 46%","Reserves: 2 months each = $12,800"],"result":"Qualifies under 50% DTI with reserves."},"scenarios":[{"t":"Big Bear cabin for a Navy family","who":"Dana, 45, Navy Commander, Coronado","situation":"Dana owns her Coronado home and wants a cabin in Big Bear for weekends and leave periods. She may rent it occasionally when not using it. She has 15% down and strong reserves.","structure":"Conventional second home at 85% LTV","numbers":"Price $650,000; loan $552,500","why":"Second-home pricing beats investment pricing","alternatives":"Investment loan if heavy rental is intended","watch":"Rental income cannot qualify; no management agreement giving control to others"},{"t":"Retirement home bought early","who":"Gary, 60, retired Marine Master Sergeant, Temecula","situation":"Gary will move to Scottsdale in three years when his wife retires. Until then they'll use it for long weekends. They want to lock in a home they like now.","structure":"Second home at 90% LTV","numbers":"Price $550,000; loan $495,000","why":"Lower down payment and better pricing than investment","alternatives":"Wait and buy later as primary","watch":"Both housing payments count in DTI; reserves"},{"t":"Lake Havasu getaway","who":"Kim, 52, general contractor, Murrieta","situation":"Kim wants a lake home for family use and boating. Her self-employed income is strong and she has 20% down. She doesn't plan to rent it.","structure":"Second home at 80%, no MI","numbers":"Price $480,000; loan $384,000","why":"Clean second-home use","alternatives":"Investment loan; HELOC on primary","watch":"Self-employed income documentation"},{"t":"Palm Springs condo in a resort project","who":"Larry, 58, dentist, San Diego","situation":"Larry likes a condo in a resort community. Some projects operate rental pools or hotel services that make them condotels. He has 25% down.","structure":"Second home condo after project eligibility review","numbers":"Price $420,000; loan $315,000","why":"Second-home pricing if project is eligible","alternatives":"Non-QM condotel loan","watch":"Rental pool or mandatory management makes it ineligible"},{"t":"Snowbird home in Florida","who":"Joan, 66, retired Navy nurse, Chula Vista","situation":"Joan wants a winter home near Pensacola close to old Navy friends. She has pension, VA compensation and Social Security. Florida insurance costs are high.","structure":"Second home at 80% (Steve licensed in FL)","numbers":"Price $380,000; loan $304,000","why":"Agency pricing on a seasonal home","alternatives":"Cash purchase; HELOC on primary","watch":"Florida wind and flood insurance costs in DTI"}],"qa":[{"q":"Can I rent my second home?","a":"Occasionally, but rental income can't be used to qualify and you must keep control of the property."},{"q":"How far away must it be?","a":"Far enough to be a credible second home; lenders judge distance and use."},{"q":"What's the max LTV?","a":"90% for purchase and rate/term (verify)."},{"q":"Can it be a 2-unit?","a":"No, second homes are 1-unit only."},{"q":"Are there extra fees?","a":"Yes, second-home LLPAs by LTV."},{"q":"Do I need reserves?","a":"Usually; DU determines amount."},{"q":"Can it be a condo?","a":"Yes if the project is eligible; condotels are not."},{"q":"Can I later turn it into a rental?","a":"Yes, after genuine second-home use."},{"q":"Can VA or FHA finance a second home?","a":"No, both require primary occupancy."}],"aeQuestions":["What distance or use standard do you apply?","Short-term rental policy for second homes?","Second-home LLPAs at 80% vs 90%?","Reserve requirements?","Condo and condotel eligibility process?","Max LTV with DU vs LPA?","Minimum FICO overlay?","Insurance requirements in wildfire or hurricane zones?","Florida and Arizona property-specific overlays?"],"redFlags":["Rental pool or mandatory management agreement","Property too close to primary to be credible","Rental income used to qualify","Investment property disguised as second home","Condotel project","Borrower can't access property year-round"],"pricing":"Second homes carry their own LLPAs that rise with LTV, so 80% vs 90% can be a significant cost decision. If substantial rental use is planned, compare investment pricing honestly rather than misclassifying occupancy. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Military families planning retirement destinations","Agents in Big Bear, Palm Springs, Lake Havasu and Florida panhandle","Financial planners serving retirees","Past clients with strong equity","Content on second home vs investment rules"],"checklist":["Second-home occupancy rider","Distance/use explanation","Income docs","Asset statements","Reserves","Appraisal","Condo questionnaire","Insurance (incl. wind/flood/fire)","Credit report","Purchase contract"],"updated":"2026-11"},
"a_conv_investment":{"matrix":[["Min FICO","DU no hard minimum (Nov 2025) but investment LLPAs are heavy below 720; lenders overlay 640-680 (lender-specific)"],["Max LTV purchase","85% 1-unit; 75% 2-4 units (verify current eligibility matrix)"],["Max LTV refinance","Rate/term 75% (1-unit) and 75% (2-4); cash-out 75% 1-unit, 70% 2-4 (verify)"],["Loan limits","2026 baseline 1-unit $832,750; 2-unit $1,066,250; 3-unit $1,288,800; 4-unit $1,601,750 (verify); high-cost up to 150%"],["Financed properties","Fannie DU up to 10 financed properties (including primary); Freddie similar (verify)"],["Reserves","6 months PITIA on subject; additional 2%-6% of UPB on other financed properties per DU"],["Rental income","75% of lease or market rent (Form 1007/1025) minus PITIA; Schedule E history preferred"],["LLPAs","Investment property LLPA by LTV on top of credit grid; significant cost"],["MI","Required over 80%; investment MI pricing higher"],["DTI/AUS","DU/LPA up to 50%; manual 36-45%"],["Occupancy","Non-owner-occupied; business purpose disclosures"],["Appraisal","Full appraisal with rent schedule"],["States","All"]],"walkthrough":["Confirm property type and investment intent","Determine financed properties count","Compute rental income via lease or rent schedule","Calculate reserves for all properties","Price investment LLPAs at 75%, 80%, 85%","Run DU/LPA","Appraisal with 1007/1025","Underwrite Schedule E","Lock","Close","Insurance (landlord policy)","Portfolio review annually"],"incomeExample":{"title":"Rental income 75% net calculation, Oceanside SFR","steps":["Market rent $3,600 (Form 1007)","75% of $3,600 = $2,700","Proposed PITIA: P&I illustrative $2,950 + tax $560 + ins $180 + HOA $0 = $3,690","Net rental = $2,700 - $3,690 = -$990 (added to liabilities)","Borrower DTI includes the -$990"],"result":"Rental shortfall of $990 counts as debt; most SoCal SFRs won't cash flow at 75%."},"scenarios":[{"t":"Keeping the base house as a rental","who":"Derrick, 44, Navy Senior Chief, Chula Vista to Coronado","situation":"Derrick is promoted and moving closer to base, keeping his Chula Vista home as a rental. He wants to buy a small Oceanside condo as a pure investment too. He has a 770 score and $180,000 in savings and TSP.","structure":"Conventional investment purchase at 75-80% with full reserves","numbers":"Condo price $520,000; 25% down $130,000; loan $390,000; reserves 6 months subject plus a percentage of other balances","why":"Agency pricing usually beats DSCR when income documentation is strong","alternatives":"DSCR non-QM (no personal income needed, higher cost); VA (not allowed for investment)","watch":"Condo project investor concentration; rental income at 75% likely negative"},{"t":"First investment duplex","who":"Ana, 36, ER nurse, Escondido","situation":"Ana owns her primary and wants a duplex as a long-term rental. She has $250,000 for 25% down and reserves. Her W-2 income is $165,000.","structure":"Investment 2-unit at 75% LTV","numbers":"Price $1,000,000; loan $750,000 (within 2-unit baseline $1,066,250, verify); rents $2,600 each","why":"Rents at 75% offset much of PITIA","alternatives":"DSCR (higher pricing); house-hacking with FHA (requires occupancy)","watch":"Investment LLPA at 75% and reserve requirements"},{"t":"Cash-out to fund next down payment","who":"Rob, 50, Marine veteran and realtor, Oceanside","situation":"Rob owns three free-and-clear rentals. He wants to cash out one at 75% to buy a fourth. His self-employed income is strong but variable.","structure":"Investment cash-out at 75% (1-unit)","numbers":"Value $800,000; new loan $600,000","why":"Agency cash-out pricing with full docs","alternatives":"DSCR cash-out; HELOC on investment (rare)","watch":"Count of financed properties and reserves for each"},{"t":"Approaching the financed-property cap","who":"Linda, 58, retired Navy Captain, Carlsbad","situation":"Linda has nine financed properties including her primary. DU allows up to ten. Her reserves are large and her credit is 790.","structure":"Investment purchase as the tenth financed property","numbers":"Reserves include 6% of UPB on other financed properties (verify)","why":"Final agency-eligible purchase at agency pricing","alternatives":"DSCR or portfolio loans for further growth","watch":"Higher minimum credit score may apply for 7-10 financed properties (verify)"},{"t":"Refinancing a departing residence","who":"Mike, 33, Navy Lieutenant, Point Loma","situation":"Mike PCS'd to Norfolk and rents his Point Loma home for $4,200. His current loan is conventional, not VA, so an IRRRL isn't available. He wants a lower rate to improve cash flow.","structure":"Conventional investment rate/term refinance at 75% LTV","numbers":"Value $900,000; loan $600,000; rental income at 75% = $3,150","why":"Lower payment on a long-term rental","alternatives":"DSCR refinance; keep current loan","watch":"Investment LLPAs; remote appraisal access and property manager coordination"}],"qa":[{"q":"How much down do I need?","a":"15% for a 1-unit, 25% for 2-4 units."},{"q":"How is rental income counted?","a":"Usually 75% of lease or market rent, minus PITIA."},{"q":"How many financed properties can I have?","a":"Up to 10 under Fannie DU including your home (verify)."},{"q":"Do I need reserves?","a":"Yes, 6 months for the subject plus a percentage on other financed properties."},{"q":"Why is pricing higher?","a":"Investment LLPAs reflect higher risk."},{"q":"Can I use an LLC?","a":"Agency loans close in personal names; transfer to LLC later may trigger due-on-sale (verify)."},{"q":"Is DSCR better?","a":"DSCR doesn't use personal income but usually costs more."},{"q":"Can I use VA for a rental?","a":"No, VA requires occupancy; keeping a former VA home as a rental is allowed."},{"q":"Can I short-term rent it?","a":"Possibly, but STR income documentation rules are strict."}],"aeQuestions":["Investment LLPA grid at 75%, 80%, 85%?","Minimum FICO for 7-10 financed properties?","How do you count rental income without leases?","Reserve calculation for other properties?","STR income policy?","2-4 unit investment max LTV?","Do you allow vesting in an LLC with personal guarantee (non-agency)?","Appraisal turn times with 1025?"],"redFlags":["Investor claims owner occupancy to get better pricing (occupancy fraud)","Reserves insufficient across portfolio","Rental income overstated","Too many financed properties","Condo with high investor concentration","Unpermitted units in 2-4 unit"],"pricing":"Investment LLPAs add substantial cost on top of the credit-score grid, and they increase with LTV. Dropping from 85% to 75% LTV can save significantly. Compare with DSCR non-QM for borrowers with complex income. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Military homeowners keeping departing residences as rentals","Real estate investor meetups","1031 exchange intermediaries","Property managers","CPAs for real estate investors"],"checklist":["Lease or rent schedule (1007/1025)","Schedule E (2 years)","Reserves for all properties","Mortgage statements for other properties","Income docs","Credit","Appraisal","Landlord insurance","Business purpose disclosure","Entity docs if applicable"],"updated":"2026-11"},
"a_conv_24unit_oo":{"matrix":[["Min FICO","DU no hard minimum (Nov 2025); LPA 620 (verify); 2-4 unit overlays 660-700 common (lender-specific)"],["Max LTV purchase","95% for 2-4 unit owner-occupied: Fannie since Nov 2023 (DU approval required); Freddie raised to 95% via Bulletin 2025-12 with LPA Accept (verify); high-balance 2-unit 85%, 3-4 unit 75%"],["Max LTV cash-out","75% for 2-4 unit primary"],["Loan limits 2026","Baseline: 1-unit $832,750; 2-unit $1,066,250; 3-unit $1,288,800; 4-unit $1,601,750; high-cost areas up to 150% of each (verify FHFA table)"],["Rental income","75% of lease or appraiser's Form 1025 market rent for non-owner units; added to income or offsets PITIA per GSE method"],["Landlord experience","Not required for primary 2-4 under Fannie DU, but some lenders overlay; HomeReady may require landlord education for 2-4 units (verify)"],["Reserves","DU/LPA-determined; Fannie historically required 6 months for 2-4 primary at higher LTVs (verify current); lender overlays common"],["MI","Required above 80%; 2-4 unit MI pricing higher"],["LLPAs","2-4 unit LLPA applies (verify current grid); HomeReady/Home Possible waivers may apply when eligible"],["DTI/AUS","DU/LPA up to 50%"],["Occupancy","Borrower must live in one unit as primary within 60 days"],["Appraisal","Form 1025 small residential income property appraisal with rent schedule"],["Property condition","Legal units only; unpermitted ADUs/units can't be counted and may cause eligibility issues"],["States","All; high-cost San Diego 2-4 unit limits make agency viable on many duplexes and triplexes"]],"walkthrough":["Confirm the borrower will occupy one unit within 60 days","Look up 2026 unit-count loan limit for the county","Compare 5% conventional vs FHA 3.5% vs VA 0% for eligible veterans","Gather existing leases and rent roll; order 1025 with rent schedule","Compute rental income at 75% and DTI","Run DU/LPA; check 95% eligibility and reserves","Price 2-4 unit LLPAs and MI","Verify permits and legal unit count","Issue pre-approval","Order appraisal; review rent schedule","Estoppels/tenant certifications if required","Close and verify occupancy","Landlord insurance and tenant notices","Calendar MI removal and rent review"],"incomeExample":{"title":"Triplex owner-occupant with 75% rental offset, North Park","steps":["Price $1,400,000; 5% down $70,000; loan $1,330,000 (3-unit high-cost limit in San Diego must exceed this; verify)","Two non-owner units rent $2,700 and $2,500 = $5,200; 75% = $3,900","Illustrative PITI: P&I $8,600 + tax $1,458 + insurance $350 + MI $480 = $10,888","Borrower W-2 income $16,000/month + rental $3,900 = $19,900 qualifying income","Other debts $700; DTI = ($10,888 + $700) / $19,900 = 58.2%","Fails 50%; with 20% down ($280,000): loan $1,120,000, PITI about $9,000, DTI = $9,700 / $19,900 = 48.7%"],"result":"5% down doesn't work at this price; 20% down or a lower price brings DTI under 50%."},"scenarios":[{"t":"Duplex house hack with 5% down","who":"Victor, 31, Navy Petty Officer First Class and IT specialist, National City","situation":"Victor has VA entitlement tied up in a home in Washington state that he rents out. He wants a duplex near base and to rent the second unit. He has $55,000 saved and a 735 score.","structure":"Conventional 2-unit at 95% LTV with DU approval","numbers":"Price $950,000; down $47,500; loan $902,500 (under 2-unit baseline $1,066,250); rent $2,500 x 75% = $1,875","why":"5% down on a 2-unit with rental offset, keeping VA tied to the rental","alternatives":"VA second-tier with down payment on gap; FHA 2-unit at 3.5% (MIP for life)","watch":"Reserves; MI on 2-unit; second unit permits"},{"t":"Triplex for multigenerational living","who":"Maria, 46, school principal, Escondido","situation":"Maria wants her parents in one unit and to rent the third. She has $150,000 and her parents won't pay rent formally. Her score is 760.","structure":"Conventional 3-unit at 85-90%","numbers":"Price $1,200,000; loan $1,020,000","why":"Family plus rental income","alternatives":"FHA 3-unit (self-sufficiency test applies)","watch":"Parents' unit has no rent to count"},{"t":"Fourplex beginner investor","who":"Jordan, 29, Marine veteran and electrician, Oceanside","situation":"Jordan wants to live in a fourplex and rent three units. He has 5% down. Rental income from three units is significant.","structure":"Conventional 4-unit at 95% (verify lender) with 75% rental","numbers":"Price $1,600,000 (under 4-unit baseline $1,601,750; verify); rents 3 x $2,200","why":"Strong rental offset","alternatives":"VA 4-unit (requires 6 months reserves, rental income rules); FHA (self-sufficiency)","watch":"Reserves and appraisal rent support"},{"t":"Advertised duplex with an unpermitted unit","who":"Kelly, 38, ER nurse, City Heights","situation":"The listing calls the property a duplex, but the second unit is an unpermitted garage conversion. The appraiser reports it as a single-family home with an unpermitted addition. Kelly was counting on $1,800 of rent to qualify.","structure":"Single-family financing without rental income, or seller legalizes the unit first","numbers":"Price $780,000; qualifying without rent raises DTI","why":"Avoids an ineligible or mis-valued file","alternatives":"Renovation loan to permit the unit after closing; walk away","watch":"Insurance and code enforcement risk; value impact"},{"t":"High-balance 2-unit in Pacific Beach","who":"Brian, 44, Navy Commander, Pacific Beach","situation":"Brian wants a 2-unit near the beach priced at $1,500,000. High-balance 2-unit limits LTV to 85%. He has $250,000.","structure":"High-balance conventional 2-unit at 83%","numbers":"Loan $1,250,000 (must be under San Diego 2-unit high-cost limit; verify)","why":"Agency financing on a high-priced duplex","alternatives":"VA jumbo 2-unit (zero down)","watch":"High-balance LTV caps and LLPAs"}],"qa":[{"q":"Can I buy a 2-4 unit with 5% down?","a":"Yes for owner-occupied under current Fannie and Freddie rules with AUS approval (verify lender)."},{"q":"How is rent from other units counted?","a":"Generally 75% of lease or appraiser's market rent."},{"q":"Do I need landlord experience?","a":"Not under agency rules for owner-occupied, though some lenders overlay."},{"q":"What are 2026 loan limits for 2-4 units?","a":"Baseline $1,066,250 / $1,288,800 / $1,601,750 for 2/3/4 units (verify) and up to 150% in high-cost areas."},{"q":"Do I need reserves?","a":"Usually; DU/LPA decide and lenders may overlay."},{"q":"Can family live in another unit?","a":"Yes, but if they pay no rent there's no rental income."},{"q":"What about unpermitted units?","a":"They can't be counted and may make the property ineligible."},{"q":"Is FHA or VA better?","a":"VA is often best for eligible veterans; FHA allows 3.5% but has MIP and a self-sufficiency test for 3-4 units."},{"q":"Can I do high-balance 2-4 units?","a":"Yes with lower LTV caps."},{"q":"Do I need to live there?","a":"Yes, as your primary residence."}],"aeQuestions":["Do you allow 95% on 2-4 unit primary, and with DU and LPA?","FICO overlays for 2-4 units?","Reserve requirement by unit count?","Do you require landlord experience?","How do you treat vacant units without leases?","High-balance 2-4 unit LTV?","MI pricing for 2-4 units?","Estoppel or tenant certification required?","Permit verification process?","HomeReady 2-4 unit landlord education requirement?"],"redFlags":["Unpermitted units counted as rentable","Tenant leases inconsistent with rent roll","Occupancy intent unclear","Reserves too thin for 2-4 units","Loan exceeds unit-count limit","Rents overstated vs appraisal","Rent control/just-cause rules not understood"],"pricing":"2-4 unit loans carry LLPAs and MI pricing above single-family, and high-balance 2-4 unit loans have lower LTV caps. Comparing 5%, 10%, 15% and 20% down often shows meaningful cost cliffs. For eligible veterans, VA multi-unit financing may beat conventional. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["House-hacking workshops for military members","Agents specializing in small multifamily","Military relocation content","Property managers","Content on 2026 2-4 unit limits"],"checklist":["Rent roll and leases","Form 1025 appraisal with rent schedule","Permit verification","Income docs","Asset and reserve statements","Credit","DU/LPA findings","Occupancy certification","Landlord insurance","MI certificate","Estoppels if required","Purchase contract"],"updated":"2026-11"},
"a_conv_arm":{"matrix":[["Products","5/6, 7/6 and 10/6 SOFR ARMs: fixed for 5, 7 or 10 years, then adjust every 6 months"],["Index","30-day average SOFR; lookback typically 45 days before change date"],["Margin","Lender-set, commonly around 2.75-3.00% (lender-specific)"],["Caps","5/6: 2/1/5 (initial/periodic/lifetime); 7/6 and 10/6: 5/1/5 (verify investor)"],["Qualifying rate","Initial fixed period 5 years or less: greater of note rate + 2% or fully indexed rate; more than 5 years: greater of note rate or fully indexed (verify current guide)"],["Max LTV","95% 1-unit primary (97% not available for ARMs); high-balance ARMs may cap at 90% (verify)"],["Min FICO","DU no hard minimum (Nov 2025)/LPA 620; overlays 660-700 for ARMs (lender-specific)"],["Loan limits","Baseline $832,750; high-cost up to $1,249,125"],["LLPAs","High-balance ARM LLPAs may apply (verify)"],["Conversion","Rarely offered on agency ARMs (lender-specific)"],["Disclosure","CHARM booklet and ARM program disclosure at application"],["Occupancy","Primary, second home, investment"],["States","All"]],"walkthrough":["Clarify expected hold period: PCS window, planned sale, or upsizing","Compare 30-year fixed vs 5/6, 7/6 and 10/6 payments at the same lock date","Explain index (30-day average SOFR), margin and the cap structure for each product","Compute worst-case payment at first adjustment and at lifetime cap","Determine qualifying rate by product and run DU or LPA","Deliver the CHARM booklet and ARM program disclosure at application","Document suitability: why the ARM fits the borrower's plan","Lock and order appraisal","Close and confirm ARM terms on the note and CD","Calendar a refinance review about 12 months before first adjustment","Send the borrower annual updates on SOFR trends without predicting rates","Review options again before each scheduled change if the loan is still held"],"incomeExample":{"title":"7/6 SOFR ARM: payment shock and qualifying, Coronado","steps":["Loan $800,000, 30-year amortization; illustrative initial P&I $4,540 (hypothetical start rate, not a quote)","Balance after 84 payments (7 years) approximately $705,000 (illustrative)","Initial adjustment cap 5 points: worst case new rate = start rate + 5; remaining term 23 years","Illustrative worst-case P&I on $705,000 over 276 months at start + 5 points = about $7,450","Worst-case increase at first adjustment = $7,450 - $4,540 = $2,910/month","Periodic cap 1 point every 6 months afterward; lifetime cap 5 points means the first adjustment can already hit the ceiling","Qualifying: 7-year fixed period qualifies at greater of note rate or fully indexed rate (verify), so DTI uses about $4,540 P&I","Household income $22,000; PITI $6,200; debts $800; DTI = 31.8% at qualifying payment; at worst case DTI = 45.0%"],"result":"Qualifies comfortably at the note rate and remains under 50% DTI even at the worst-case first adjustment, which supports choosing the 7/6 for a 5-6 year expected hold."},"scenarios":[{"t":"Officer with a known PCS window","who":"Tom, 38, Navy Lieutenant Commander, Coronado","situation":"Tom has orders that keep him in San Diego for about 5 years, after which he expects to PCS and sell or rent. He prefers conventional to keep his VA entitlement for a future duty station. His loan will be $800,000 with 15% down.","structure":"Conventional 7/6 SOFR ARM, 85% LTV, BPMI","numbers":"Loan $800,000; illustrative initial P&I $4,540; worst-case first adjustment +$2,910/month (see example)","why":"Initial rate is typically below 30-year fixed pricing, and the fixed period outlasts his expected stay","alternatives":"30-year fixed; VA purchase with entitlement","watch":"If he keeps it as a rental past year 7, payment can jump; plan a refinance review in year 5-6"},{"t":"Retiree planning to downsize","who":"Ann, 62, retired Navy Senior Chief, Carlsbad","situation":"Ann intends to sell in 8-10 years and move closer to grandchildren in Colorado. She has pension, VA compensation and Social Security. She wants the lowest payment that still gives a long fixed period.","structure":"Conventional 10/6 SOFR ARM at 70% LTV","numbers":"Loan $600,000; 10 years of fixed payment","why":"Long fixed period matches her plan with lower initial cost than fixed (when the curve allows)","alternatives":"15-year fixed (higher payment); 30-year fixed","watch":"If plans change and she stays past year 10, adjustments begin"},{"t":"High-balance buyer stretching for payment","who":"Mark, 41, biotech scientist, Del Mar","situation":"Mark is buying at $1,250,000 with 20% down; the loan is high-balance. He wants a lower payment for the first years while equity vests. His stock compensation is irregular.","structure":"High-balance 5/6 ARM (verify LTV cap) only if he qualifies at note + 2%","numbers":"Loan $1,000,000; qualifying at note + 2 points raises DTI","why":"Lower initial payment","alternatives":"7/6 or 10/6 (qualify at note rate); fixed","watch":"5/6 cap 2/1/5 means faster exposure; RSU income documentation"},{"t":"Investor wanting a lower start rate","who":"Rosa, 50, Marine veteran and property manager, Vista","situation":"Rosa is buying a 1-unit rental and plans to sell within 6 years after repositioning. Investment LLPAs push fixed pricing up. She has 25% down.","structure":"Conventional investment 7/6 ARM at 75%","numbers":"Loan $540,000","why":"Initial savings while she executes her plan","alternatives":"DSCR ARM; fixed investment","watch":"Rental cash flow at worst-case payment"},{"t":"Borrower who should choose fixed","who":"Kevin, 34, Navy E-6, Santee","situation":"Kevin wants an ARM because a friend said rates will fall. He plans to stay 15+ years and has a tight budget. Worst-case payment would exceed his comfort.","structure":"Recommend fixed-rate loan or VA fixed; ARM not suitable for his goals","numbers":"Worst-case increase over $1,500/month on his loan size (illustrative)","why":"Suitability and payment certainty","alternatives":"VA fixed; conventional fixed","watch":"Avoid speculating on rate direction; document the recommendation"}],"qa":[{"q":"What does 7/6 mean?","a":"The rate is fixed for 7 years, then adjusts every 6 months."},{"q":"What index is used?","a":"The 30-day average of SOFR, plus the lender's margin."},{"q":"How much can my rate rise?","a":"Caps limit it; 7/6 and 10/6 commonly allow 5 points at first change, 1 point per change and 5 points lifetime (verify)."},{"q":"How do I qualify on an ARM?","a":"5/6 ARMs qualify at the higher of note rate plus 2% or the fully indexed rate; 7/6 and 10/6 at the higher of note or fully indexed (verify)."},{"q":"Can I put 3% down on an ARM?","a":"No, conventional ARMs are capped at 95% LTV."},{"q":"Can I refinance before the first adjustment?","a":"Yes, if you qualify at that time; there's no prepayment penalty on agency ARMs."},{"q":"Is an ARM good for military buyers?","a":"It can fit a known PCS timeline, but orders and markets change, so plan for the worst case."},{"q":"Can I convert my ARM to fixed?","a":"Usually only by refinancing; conversion features are rare."},{"q":"Will my payment fall if rates drop?","a":"It can after the fixed period, but floors and margins limit how low it goes."}],"aeQuestions":["What margins do you offer on 5/6, 7/6 and 10/6 today?","What cap structures do you offer by product?","How do you calculate the qualifying rate on each product?","Max LTV for ARMs and for high-balance ARMs?","Any ARM-specific LLPAs or pricing adjusters?","Do any of your ARMs offer a conversion option?","Do you allow ARMs on investment and second homes?","What lookback period applies to the SOFR index?","Do you offer interest-only ARMs on agency loans (usually not)?"],"redFlags":["Borrower plans to hold beyond fixed period without a plan","Worst-case payment unaffordable","Borrower counting on rates falling","Qualifying at wrong rate","ARM chosen solely for approval","High-balance ARM over LTV cap","Missing CHARM booklet/ARM disclosure"],"pricing":"ARM pricing depends on margin, caps and the shape of the yield curve; when the curve is flat or inverted, ARMs may offer little savings over fixed. Compare the total interest over the expected hold and worst-case scenarios. Compare offers by locking the same day, same lock period, same points or credits, and read Loan Estimate Sections A, B and J plus APR rather than a headline rate. Lender choice is driven by borrower fit and total cost, never by broker compensation: 12 CFR 1026.36(d) bars comp that varies with loan terms, and 1026.36(e) anti-steering requires showing the lowest-rate, lowest-total-cost and no-risky-feature options the borrower likely qualifies for, documented in the file.","marketing":["Military officers with known PCS windows","Move-up buyers planning to sell","Retirees planning moves","Agents in high-cost markets","Content on ARM caps and worst-case math"],"checklist":["CHARM booklet delivery","ARM program disclosure","Qualifying rate calculation","Worst-case payment worksheet","Income docs","Assets","Credit","Appraisal","Purchase contract","Insurance","Lock confirmation","Suitability notes"],"updated":"2026-11"}
});
